window.LESSON_INDEX = {"lessons/01-variables.js":{"title":"* 01 · variables — var, let, const","learn":"* • how to declare variables with var, let, and const * • the difference between declaration, initialization, and reassignment * • scope: function-scope (var) vs block-scope (let/const) * • hoisting and the \"temporal dead zone\" * * rule of thumb * use `const` by default. use `let` only when you must reassign. * avoid `var` — it has confusing scoping and is considered legacy. * * note: reserved keywords (var, let, const, if, else, for, while, function, * return, ...) cannot be used as variable names.","practice":"/* practice ------------------------------------------------------------------- * 1. declare a const for your name and log it. * 2. declare a let counter, set it to 0, then reassign it to 5. * 3. try reassigning a const and read the exact error message. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 01 · variables — var, let, const * ============================================================================= * run: node lessons/01-variables.js * * what you'll learn * • how to declare variables with var, let, and const * • the difference between declaration, initialization, and reassignment * • scope: function-scope (var) vs block-scope (let/const) * • hoisting and the \"temporal dead zone\" * * rule of thumb * use `const` by default. use `let` only when you must reassign. * avoid `var` — it has confusing scoping and is considered legacy. * * note: reserved keywords (var, let, const, if, else, for, while, function, * return, ...) cannot be used as variable names. * ========================================================================== */ // ── 1. declaration & initialization ────────────────────────────────────────── // \"declaration\" = create the variable. \"initialization\" = give it a value. let count; // declaration only — value is `undefined` for now count = 12; // initialization console.log(count); // => 12 const tax_rate = 0.2; // const must be declared and initialized together console.log(tax_rate); // => 0.2 // const rate; // ❌ syntaxerror: missing initializer in const declaration // ── 2. reassignment ────────────────────────────────────────────────────────── let score = 10; score = 25; // ✅ let can be reassigned console.log(score); // => 25 // tax_rate = 0.3; // ❌ typeerror: assignment to constant variable console.log(tax_rate); // => 0.2 (const can never be reassigned) // important: `const` means the *binding* can't change — but if it holds an // object or array, the contents can still be mutated: const user = { name: 'sam' }; user.name = 'alex'; // ✅ allowed — we mutate the object, not the binding console.log(user); // => { name: 'alex' } // ── 3. redeclaration ───────────────────────────────────────────────────────── // \"redeclaration\" = declaring a variable with the same name twice in the same // scope. this is different from reassignment (which only changes the value). // `var` allows redeclaration — the second `var` is silently merged into the // first. this is a common source of bugs, since you can clobber a variable // without realising it: var total = 1; var total = 2; // ✅ no error — `var` lets you redeclare console.log(total); // => 2 // `let` and `const` forbid redeclaration in the same scope: // let count = 1; // let count = 2; // ❌ syntaxerror: identifier 'count' has already been declared // // const pi = 3.14; // const pi = 3.15; // ❌ syntaxerror: identifier 'pi' has already been declared // note: redeclaring in a *different* (nested) block is fine — that's a brand new // variable that \"shadows\" the outer one, not a redeclaration: let level = 'outer'; { let level = 'inner'; // ✅ separate variable in its own block console.log(level); // => inner } console.log(level); // => outer // ── 4. scope ───────────────────────────────────────────────────────────────── // `var` is function-scoped. `let`/`const` are block-scoped ({ ... }). function demoscope() { var functionscoped = 'i live in the whole function'; let blockscoped = 'i live only in my block'; console.log(functionscoped, '|', blockscoped); } demoscope(); // => i live in the whole function | i live only in my block // console.log(functionscoped); // ❌ referenceerror — not visible outside // var ignores block boundaries: { var leaks = 'i escape the block'; } console.log(leaks); // => i escape the block (this is why var is confusing) // let/const respect block boundaries: { let trapped = 'i stay inside'; } // console.log(trapped); // ❌ referenceerror: trapped is not defined // ── 5. hoisting & the temporal dead zone (tdz) ────────────────────────────── // `var` declarations are \"hoisted\" to the top and start as `undefined`. console.log(hoistedvar); // => undefined (declared below, but already exists) var hoistedvar = 'now i have a value'; // `let`/`const` are also hoisted, but you cannot use them before their line. // that gap is the \"temporal dead zone\". try { console.log(hoistedlet); // ❌ throws — we're in the tdz } catch (err) { console.log(err.message); // => cannot access 'hoistedlet' before initialization } let hoistedlet = 'safe to use now'; /* practice ------------------------------------------------------------------- * 1. declare a const for your name and log it. * 2. declare a let counter, set it to 0, then reassign it to 5. * 3. try reassigning a const and read the exact error message. * ------------------------------------------------------------------------- */"},"lessons/02-data-types.js":{"title":"* 02 · data types","learn":"* • the 7 primitive types and the object type * • how `typeof` reports each type (and its one famous bug) * • the difference between value types and reference types","practice":"/* practice ------------------------------------------------------------------- * 1. log the typeof for: \"5\", 5, true, null, undefined, [], {}. * 2. copy an object two ways: by reference and with spread. mutate each copy * and observe which one affects the original. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 02 · data types * ============================================================================= * run: node lessons/02-data-types.js * * what you'll learn * • the 7 primitive types and the object type * • how `typeof` reports each type (and its one famous bug) * • the difference between value types and reference types * ========================================================================== */ // ── 1. the primitive types ─────────────────────────────────────────────────── // primitives are immutable, single values. there are 7: const astring = 'hello'; // string const anumber = 42; // number (integers and decimals) const aboolean = true; // boolean — true / false const nothing = null; // null — an intentional \"empty\" value let notset; // undefined — declared but no value yet const big = 9007199254740993n; // bigint — integers beyond number's safe range const unique = symbol('id'); // symbol — a guaranteed-unique value console.log(typeof astring); // => string console.log(typeof anumber); // => number console.log(typeof aboolean); // => boolean console.log(typeof notset); // => undefined console.log(typeof big); // => bigint console.log(typeof unique); // => symbol // ⚠️ famous bug: typeof null is \"object\". it's a bug from javascript's earliest // days, kept for backwards compatibility. just memorize it. console.log(typeof nothing); // => object (not \"null\"!) // ── 2. objects (everything that isn't a primitive) ─────────────────────────── const obj = { a: 1 }; const arr = [1, 2, 3]; const fn = function () {}; console.log(typeof obj); // => object console.log(typeof arr); // => object (arrays are objects! use array.isarray) console.log(typeof fn); // => function (functions are callable objects) console.log(array.isarray(arr)); // => true ← the correct way to detect arrays console.log(array.isarray(obj)); // => false // ── 3. value vs reference ──────────────────────────────────────────────────── // primitives are copied by value — each variable holds its own copy. let x = 10; let y = x; // y gets a copy of 10 y = 99; console.log(x, y); // => 10 99 (changing y did not affect x) // objects/arrays: assigning copies the reference (the \"address\"), not the data — // so both names end up pointing to the same underlying object. const original = { score: 1 }; const alias = original; // alias gets a copy of the reference → same object alias.score = 100; console.log(original.score); // => 100 (they share one object!) // to truly copy an object, spread it (shallow copy): const copy = { ...original }; copy.score = 5; console.log(original.score, copy.score); // => 100 5 // ── 4. null vs undefined ───────────────────────────────────────────────────── // undefined → \"this has not been given a value yet\" (usually by js) // null → \"this is intentionally empty\" (usually set by you) let unassigned; console.log(unassigned); // => undefined const cleared = null; console.log(cleared); // => null /* practice ------------------------------------------------------------------- * 1. log the typeof for: \"5\", 5, true, null, undefined, [], {}. * 2. copy an object two ways: by reference and with spread. mutate each copy * and observe which one affects the original. * ------------------------------------------------------------------------- */"},"lessons/03-operators.js":{"title":"* 03 · operators","learn":"* • arithmetic, assignment, comparison, and logical operators * • strict (===) vs loose (==) equality — and why you should use === * • modern operators: nullish (??) and optional chaining (?.)","practice":"/* practice ------------------------------------------------------------------- * 1. use % to check whether 17 is even or odd. * 2. predict then verify: 0 == '', 0 === '', null == undefined. * 3. give a setting a default with ?? where 0 should be a valid value. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 03 · operators * ============================================================================= * run: node lessons/03-operators.js * * what you'll learn * • arithmetic, assignment, comparison, and logical operators * • strict (===) vs loose (==) equality — and why you should use === * • modern operators: nullish (??) and optional chaining (?.) * ========================================================================== */ // ── 1. arithmetic ──────────────────────────────────────────────────────────── console.log(7 + 3); // => 10 console.log(7 - 3); // => 4 console.log(7 * 3); // => 21 console.log(7 / 3); // => 2.333... console.log(7 % 3); // => 1 (modulo / remainder — great for \"is it even?\") console.log(2 ** 3); // => 8 (exponentiation: 2 to the power of 3) // ── 2. assignment shorthands ───────────────────────────────────────────────── let n = 10; n += 5; console.log(n); // => 15 (same as n = n + 5) n -= 3; console.log(n); // => 12 n *= 2; console.log(n); // => 24 n /= 4; console.log(n); // => 6 // increment / decrement let i = 0; console.log(i++); // => 0 (post: returns then increments → i is now 1) console.log(++i); // => 2 (pre: increments then returns) // ── 3. comparison ──────────────────────────────────────────────────────────── console.log(5 > 3); // => true console.log(5 <= 5); // => true // === is strict equality: compares value and type, no conversion. prefer it. console.log(5 === 5); // => true console.log(5 === '5'); // => false (number vs string) // == is loose equality: converts types first → surprising results. avoid it. console.log(5 == '5'); // => true (string '5' gets converted to number 5) console.log(0 == false); // => true (😱 this is why we avoid ==) console.log(0 === false);// => false // ── 4. logical operators ───────────────────────────────────────────────────── console.log(true && false); // => false (and — both must be true) console.log(true || false); // => true (or — at least one true) console.log(!true); // => false (not — flips the boolean) // && and || actually return one of the operands, not just true/false: console.log('' || 'fallback'); // => fallback (first truthy value) console.log('hi' && 'world'); // => world (last value if all truthy) // ── 5. nullish coalescing (??) ─────────────────────────────────────────────── // ?? returns the right side only when the left is null or undefined. // unlike ||, it treats 0 and '' as valid values. const volume = 0; console.log(volume || 5); // => 5 (|| sees 0 as falsy — wrong here!) console.log(volume ?? 5); // => 0 (?? keeps 0 — correct) // ── 6. optional chaining (?.) ──────────────────────────────────────────────── // safely read deep properties without crashing on null/undefined. const profile = { name: 'sam', address: { city: 'pune' } }; console.log(profile.address?.city); // => pune console.log(profile.contact?.email); // => undefined (no crash!) // console.log(profile.contact.email); // ❌ typeerror without the ?. /* practice ------------------------------------------------------------------- * 1. use % to check whether 17 is even or odd. * 2. predict then verify: 0 == '', 0 === '', null == undefined. * 3. give a setting a default with ?? where 0 should be a valid value. * ------------------------------------------------------------------------- */"},"lessons/04-type-conversion.js":{"title":"* 04 · type conversion & coercion","learn":"* • explicit conversion (you do it) vs implicit coercion (js does it) * • truthy and falsy values * • the classic gotchas that confuse every beginner","practice":"/* practice ------------------------------------------------------------------- * 1. convert the string \"100\" to a number three different ways. * 2. predict the output of: [] + [], [] + {}, true + 1. then run them. * 3. list all 8 falsy values from memory, then check yourself above. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 04 · type conversion & coercion * ============================================================================= * run: node lessons/04-type-conversion.js * * what you'll learn * • explicit conversion (you do it) vs implicit coercion (js does it) * • truthy and falsy values * • the classic gotchas that confuse every beginner * ========================================================================== */ // ── 1. explicit conversion (recommended) ───────────────────────────────────── // you clearly state the target type. predictable and readable. console.log(number('42')); // => 42 console.log(number('42px')); // => nan (\"not a number\" — conversion failed) console.log(parseint('42px')); // => 42 (parseint grabs the leading number) console.log(parsefloat('3.14rad')); // => 3.14 console.log(string(42)); // => \"42\" console.log(string(true)); // => \"true\" console.log((42).tostring()); // => \"42\" console.log(boolean(1)); // => true console.log(boolean(0)); // => false // ── 2. truthy & falsy ──────────────────────────────────────────────────────── // every value is either \"truthy\" or \"falsy\" in a boolean context (if, &&, etc). // there are exactly 8 falsy values — memorize these; everything else is truthy. const falsyvalues = [false, 0, -0, 0n, '', null, undefined, nan]; falsyvalues.foreach(v => console.log(boolean(v))); // => all false // common surprises — these are all truthy: console.log(boolean('0')); // => true (non-empty string!) console.log(boolean('false')); // => true (non-empty string!) console.log(boolean([])); // => true (empty array is truthy) console.log(boolean({})); // => true (empty object is truthy) // ── 3. implicit coercion (happens automatically) ───────────────────────────── // the + operator: if either side is a string, it concatenates. console.log(1 + '2'); // => \"12\" (number 1 becomes string \"1\") console.log('3' + 4); // => \"34\" console.log(1 + 2 + '3'); // => \"33\" (left-to-right: 1+2=3, then 3+'3'=\"33\") // other math operators (- * / %) convert strings to numbers: console.log('6' - 2); // => 4 console.log('6' * '2'); // => 12 console.log('a' - 2); // => nan // ── 4. the == vs === reminder ──────────────────────────────────────────────── // == coerces types before comparing → unpredictable. always prefer ===. console.log('' == 0); // => true 😱 console.log('0' == 0); // => true 😱 console.log(null == undefined);// => true (the one == case that's handy) console.log(nan === nan); // => false (nan is never equal to anything!) console.log(number.isnan(nan));// => true (the correct way to check for nan) /* practice ------------------------------------------------------------------- * 1. convert the string \"100\" to a number three different ways. * 2. predict the output of: [] + [], [] + {}, true + 1. then run them. * 3. list all 8 falsy values from memory, then check yourself above. * ------------------------------------------------------------------------- */"},"lessons/05-strings.js":{"title":"* 05 · strings","learn":"* • creating strings and template literals * • the most-used string methods * • strings are immutable — methods return new strings","practice":"/* practice ------------------------------------------------------------------- * 1. build a sentence with a template literal using two variables. * 2. take \" hello world \", trim it, lowercase it, and replace the space. * 3. split \"2024-06-04\" by \"-\" and log the year, month, day separately. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 05 · strings * ============================================================================= * run: node lessons/05-strings.js * * what you'll learn * • creating strings and template literals * • the most-used string methods * • strings are immutable — methods return new strings * ========================================================================== */ // ── 1. creating strings ────────────────────────────────────────────────────── const single = 'single quotes'; const double = \"double quotes\"; // identical to single quotes const name = 'sam'; const age = 25; // template literals (backticks): allow ${expressions} and multi-line text. // prefer these — they're cleaner than + concatenation. const greeting = `hi, i'm ${name} and i'm ${age} years old.`; console.log(greeting); // => hi, i'm sam and i'm 25 years old. const multiline = `line one line two`; console.log(multiline); // ── 2. length & accessing characters ───────────────────────────────────────── const text = 'javascript'; console.log(text.length); // => 10 console.log(text[0]); // => j (zero-indexed) console.log(text.at(-1)); // => t (.at() supports negative indexes) // ── 3. searching ───────────────────────────────────────────────────────────── console.log(text.includes('script')); // => true console.log(text.startswith('java')); // => true console.log(text.endswith('pt')); // => true console.log(text.indexof('s')); // => 4 (-1 if not found) // ── 4. transforming (returns a new string — originals never change) ────────── console.log(text.touppercase()); // => javascript console.log(text.tolowercase()); // => javascript console.log(' trim me '.trim()); // => \"trim me\" console.log(text.replace('java', 'type')); // => typescript console.log('a-b-c'.replaceall('-', '/')); // => a/b/c console.log('ab'.repeat(3)); // => ababab // slice(start, end) — extract a portion (end not included) console.log(text.slice(0, 4)); // => java console.log(text.slice(4)); // => script console.log(text.slice(-6)); // => script (negative = from the end) // immutability proof: text itself is unchanged console.log(text); // => javascript // ── 5. splitting & joining ─────────────────────────────────────────────────── const csv = 'red,green,blue'; const colors = csv.split(','); // string → array console.log(colors); // => [ 'red', 'green', 'blue' ] console.log(colors.join(' | ')); // array → string => red | green | blue // ── 6. padding & numbers-as-strings ────────────────────────────────────────── console.log('5'.padstart(3, '0')); // => 005 (handy for time/ids) console.log('5'.padend(3, '.')); // => 5.. /* practice ------------------------------------------------------------------- * 1. build a sentence with a template literal using two variables. * 2. take \" hello world \", trim it, lowercase it, and replace the space. * 3. split \"2024-06-04\" by \"-\" and log the year, month, day separately. * ------------------------------------------------------------------------- */"},"lessons/06-numbers-math.js":{"title":"* 06 · numbers & math","learn":"* • how js represents numbers (one type for ints and decimals) * • rounding and formatting * • the math object * • the floating-point precision gotcha","practice":"/* practice ------------------------------------------------------------------- * 1. round 7.456 to 1 decimal place as a string. * 2. find the largest of [12, 7, 25, 3] using math.max with the spread (...). * 3. write a function that returns a random integer between 1 and 100. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 06 · numbers & math * ============================================================================= * run: node lessons/06-numbers-math.js * * what you'll learn * • how js represents numbers (one type for ints and decimals) * • rounding and formatting * • the math object * • the floating-point precision gotcha * ========================================================================== */ // ── 1. one number type ─────────────────────────────────────────────────────── console.log(10); // integer console.log(10.5); // decimal — both are the same `number` type console.log(1e6); // => 1000000 (scientific notation) console.log(0xff); // => 255 (hexadecimal) // ── 2. formatting & rounding ───────────────────────────────────────────────── const price = 19.99876; console.log(price.tofixed(2)); // => \"20.00\" (string — tofixed rounds: ...876 rounds up) // ⚠️ tofixed rounding is itself subject to the float quirks in §5 below: // (1.005).tofixed(2) is \"1.00\", not \"1.01\". for money, work in integer cents. console.log(math.round(2.5)); // => 3 (nearest integer) console.log(math.floor(2.9)); // => 2 (round down) console.log(math.ceil(2.1)); // => 3 (round up) console.log(math.trunc(-2.7)); // => -2 (drop the decimal, no rounding) // format with thousands separators: console.log((1234567.89).tolocalestring('en-us')); // => 1,234,567.89 // intl.numberformat — the full-control formatter (currency, percent, locales). // build it once and reuse it; it handles the currency symbol and rounding. const usd = new intl.numberformat('en-us', { style: 'currency', currency: 'usd' }); console.log(usd.format(1234.5)); // => $1,234.50 const inr = new intl.numberformat('en-in', { style: 'currency', currency: 'inr' }); console.log(inr.format(1234567)); // => ₹12,34,567.00 (note indian digit grouping) const pct = new intl.numberformat('en-us', { style: 'percent', maximumfractiondigits: 1 }); console.log(pct.format(0.1487)); // => 14.9% // ── 3. the math object ─────────────────────────────────────────────────────── console.log(math.max(3, 7, 2)); // => 7 console.log(math.min(3, 7, 2)); // => 3 console.log(math.abs(-9)); // => 9 console.log(math.sqrt(81)); // => 9 console.log(math.pow(2, 10)); // => 1024 (or use 2 ** 10) console.log(math.pi); // => 3.14159... // random number between 0 (inclusive) and 1 (exclusive): // (commented out so the lesson's output stays stable when you re-run it) // console.log(math.random()); // random integer between min and max (inclusive) — a reusable pattern: function randomint(min, max) { return math.floor(math.random() * (max - min + 1)) + min; } // console.log(randomint(1, 6)); // a dice roll: 1–6 // ── 4. parsing & validating ────────────────────────────────────────────────── console.log(parseint('42px', 10)); // => 42 (always pass the radix 10) console.log(parsefloat('3.14m')); // => 3.14 console.log(number.isinteger(5)); // => true console.log(number.isinteger(5.1));// => false console.log(number.isnan(0 / 0)); // => true (0/0 is nan) console.log(number.isfinite(1/0)); // => false (1/0 is infinity) // ── 5. ⚠️ the floating-point gotcha ────────────────────────────────────────── // computers store decimals in binary, which can't represent some values exactly. console.log(0.1 + 0.2); // => 0.30000000000000004 (not 0.3!) console.log(0.1 + 0.2 === 0.3); // => false // fixes: console.log((0.1 + 0.2).tofixed(2)); // => \"0.30\" console.log(math.abs(0.1 + 0.2 - 0.3) < 1e-9); // => true (compare with tolerance) // for money, work in the smallest unit (cents) as integers to avoid this entirely. /* practice ------------------------------------------------------------------- * 1. round 7.456 to 1 decimal place as a string. * 2. find the largest of [12, 7, 25, 3] using math.max with the spread (...). * 3. write a function that returns a random integer between 1 and 100. * ------------------------------------------------------------------------- */"},"lessons/07-conditionals.js":{"title":"* 07 · conditionals","learn":"* • if / else if / else * • the ternary operator (? :) * • switch statements * • guard clauses for cleaner code","practice":"/* practice ------------------------------------------------------------------- * 1. write an if/else that logs \"even\" or \"odd\" for a number (use % 2). * 2. rewrite it as a ternary. * 3. use a switch to map 1–7 to weekday names. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 07 · conditionals * ============================================================================= * run: node lessons/07-conditionals.js * * what you'll learn * • if / else if / else * • the ternary operator (? :) * • switch statements * • guard clauses for cleaner code * ========================================================================== */ // ── 1. if / else if / else ─────────────────────────────────────────────────── const score = 82; if (score >= 90) { console.log('grade: a'); } else if (score >= 80) { console.log('grade: b'); // => grade: b } else if (score >= 70) { console.log('grade: c'); } else { console.log('grade: f'); } // ── 2. ternary operator — a one-line if/else that returns a value ──────────── const age = 20; const status = age >= 18 ? 'adult' : 'minor'; console.log(status); // => adult // great for assigning a value; avoid nesting them deeply (hard to read). const fee = age < 12 ? 0 : age < 65 ? 100 : 50; console.log(fee); // => 100 // ── 3. logical operators as conditionals ───────────────────────────────────── // && runs the right side only if the left is truthy: const isloggedin = true; isloggedin && console.log('welcome back!'); // => welcome back! // || provides a fallback value: const username = '' || 'guest'; console.log(username); // => guest // ── 4. switch — clean alternative for many discrete cases ──────────────────── const day = 'sat'; let kind; switch (day) { case 'sat': case 'sun': // cases can share a body (no break between them) kind = 'weekend'; break; // ⚠️ without break, execution \"falls through\" to the next case case 'mon': kind = 'start of week'; break; default: // runs if nothing matched kind = 'weekday'; } console.log(kind); // => weekend // ── 5. guard clauses — return early to avoid deep nesting ──────────────────── // ❌ nested and hard to read: function checkoutnested(cart) { if (cart) { if (cart.items.length > 0) { return 'proceeding to payment'; } else { return 'cart is empty'; } } else { return 'no cart'; } } // ✅ flat and readable — handle the exits first: function checkout(cart) { if (!cart) return 'no cart'; if (cart.items.length === 0) return 'cart is empty'; return 'proceeding to payment'; } console.log(checkout({ items: ['book'] })); // => proceeding to payment console.log(checkout({ items: [] })); // => cart is empty console.log(checkout(null)); // => no cart /* practice ------------------------------------------------------------------- * 1. write an if/else that logs \"even\" or \"odd\" for a number (use % 2). * 2. rewrite it as a ternary. * 3. use a switch to map 1–7 to weekday names. * ------------------------------------------------------------------------- */"},"lessons/08-loops.js":{"title":"* 08 · loops","learn":"* • for, while, do...while * • for...of (values) vs for...in (keys) * • break and continue * • which loop to reach for","practice":"/* practice ------------------------------------------------------------------- * 1. print 1–10 with a for loop, but skip multiples of 3 (continue). * 2. sum all numbers in [4, 8, 15, 16, 23, 42] with for...of. * 3. loop over an object's keys and values with for...in. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 08 · loops * ============================================================================= * run: node lessons/08-loops.js * * what you'll learn * • for, while, do...while * • for...of (values) vs for...in (keys) * • break and continue * • which loop to reach for * ========================================================================== */ // ── 1. classic for loop — when you need an index/counter ───────────────────── for (let i = 0; i < 3; i++) { console.log('for', i); // => 0, 1, 2 } // anatomy: for (initialize; condition; aftereachloop) { body } // ── 2. while — loop until a condition becomes false ────────────────────────── let count = 3; while (count > 0) { console.log('while', count); // => 3, 2, 1 count--; } // ── 3. do...while — runs the body at least once, then checks ───────────────── let n = 0; do { console.log('do-while runs once even though condition is false'); } while (n > 0); // ── 4. for...of — iterate over values (arrays, strings, sets, maps) ────────── // this is the modern go-to for looping over a collection. const fruits = ['apple', 'banana', 'cherry']; for (const fruit of fruits) { console.log(fruit); // => apple, banana, cherry } // need the index too? use .entries(): for (const [index, fruit] of fruits.entries()) { console.log(index, fruit); // => 0 apple, 1 banana, 2 cherry } // strings are iterable too: for (const char of 'hi') { console.log(char); // => h, i } // ── 5. for...in — iterate over keys of an object ───────────────────────────── // use this for objects. (avoid it for arrays — for...of is better there.) // ⚠️ for...in also visits inherited enumerable keys (up the prototype chain), // not just an object's own. for own keys only, prefer object.keys() (lesson 14). const user = { name: 'sam', age: 25, city: 'pune' }; for (const key in user) { console.log(`${key}: ${user[key]}`); // => name: sam, age: 25, city: pune } // ── 6. break & continue ────────────────────────────────────────────────────── for (let i = 1; i <= 5; i++) { if (i === 4) break; // stop the loop entirely if (i === 2) continue; // skip the rest of this iteration only console.log('flow', i); // => 1, 3 } // ── 7. array helper loops (preview of lesson 13) ───────────────────────────── // foreach runs a function for each element — no manual index needed. fruits.foreach((fruit, i) => console.log(i, fruit)); /* which loop? ---------------------------------------------------------------- * • looping over array/string values .......... for...of * • looping over object keys .................. for...in * • need a numeric counter / step ............. classic for * • repeat until a condition .................. while * • transforming an array into a new one ...... .map() (lesson 13) * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. print 1–10 with a for loop, but skip multiples of 3 (continue). * 2. sum all numbers in [4, 8, 15, 16, 23, 42] with for...of. * 3. loop over an object's keys and values with for...in. * ------------------------------------------------------------------------- */"},"lessons/09-functions.js":{"title":"* 09 · functions","learn":"* • function declarations vs expressions vs arrow functions * • parameters: default values, rest parameters * • returning values * • functions are \"first-class\" — they're values you can pass around * • recursion — a function that calls itself","practice":"/* practice ------------------------------------------------------------------- * 1. write iseven(n) three ways: declaration, expression, arrow. * 2. write a function with a default greeting parameter. * 3. write average(...nums) that returns the mean of any count of numbers. * 4. write a recursive countdown(n) that logs n, n-1, ... down to 0. * 5. write a recursive power(base, exp) — no math.pow, no ** operator. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 09 · functions * ============================================================================= * run: node lessons/09-functions.js * * what you'll learn * • function declarations vs expressions vs arrow functions * • parameters: default values, rest parameters * • returning values * • functions are \"first-class\" — they're values you can pass around * • recursion — a function that calls itself * ========================================================================== */ // ── 1. function declaration ────────────────────────────────────────────────── // hoisted — you can call it before it's defined in the file. console.log(add(2, 3)); // => 5 (works even though add is defined below) function add(a, b) { return a + b; // `return` sends a value back to the caller } // a function with no `return` returns undefined. // ── 2. function expression ─────────────────────────────────────────────────── // stored in a variable. not hoisted — must be defined before use. const multiply = function (a, b) { return a * b; }; console.log(multiply(4, 5)); // => 20 // ── 3. arrow functions — shorter syntax ────────────────────────────────────── const square = (x) => x * x; // single expression → implicit return console.log(square(6)); // => 36 const subtract = (a, b) => a - b; // multiple params need parentheses console.log(subtract(10, 4)); // => 6 const greet = () => 'hello!'; // no params → empty parentheses console.log(greet()); // => hello! // need multiple lines? use a block { } and an explicit return: const describe = (name, age) => { const label = `${name} is ${age}`; return label; }; console.log(describe('sam', 25)); // => sam is 25 // note: arrows handle `this` differently — covered in lesson 11. // ── 4. default parameters ──────────────────────────────────────────────────── function greetuser(name = 'guest') { return `welcome, ${name}!`; } console.log(greetuser('alex')); // => welcome, alex! console.log(greetuser()); // => welcome, guest! (default kicks in) // ── 5. rest parameters — collect \"the rest\" into an array ──────────────────── function sum(...numbers) { // numbers is a real array: [1, 2, 3, 4] return numbers.reduce((total, n) => total + n, 0); // reduce = \"sum the array\" (lesson 13) } console.log(sum(1, 2, 3, 4)); // => 10 console.log(sum(5, 5)); // => 10 // ── 6. functions are values (first-class) ──────────────────────────────────── // you can store them, pass them as arguments, and return them. function applytwice(fn, value) { return fn(fn(value)); // call the passed-in function twice } console.log(applytwice(square, 2)); // => 16 (square(square(2)) = square(4)) // a function returned by another function (a \"factory\"): function makemultiplier(factor) { return (x) => x * factor; } const triple = makemultiplier(3); console.log(triple(5)); // => 15 // ── 7. recursion — a function that calls itself ────────────────────────────── // every recursion needs two things: // 1. a base case that stops it (no base case → \"maximum call stack\" crash) // 2. a step that moves closer to the base case on each call function factorial(n) { if (n <= 1) return 1; // base case — stop here return n * factorial(n - 1); // recursive step — n gets smaller each time } console.log(factorial(5)); // => 120 (5 * 4 * 3 * 2 * 1) // anything you can do with a loop, you can do with recursion: function sumto(n) { if (n === 0) return 0; // base case return n + sumto(n - 1); } console.log(sumto(4)); // => 10 (4 + 3 + 2 + 1 + 0) // recursion shines on nested/tree-shaped data, where loops get awkward. // here we add up every number in an arbitrarily deep nested array: function deepsum(arr) { let total = 0; for (const item of arr) { // if it's an array, recurse into it; otherwise add the number total += array.isarray(item) ? deepsum(item) : item; } return total; } console.log(deepsum([1, [2, [3, 4], 5], [6]])); // => 21 // mental model: each call waits (\"on the call stack\") for the deeper call to // finish, then combines the result — like opening boxes inside boxes, then // re-stacking them on the way back out. /* practice ------------------------------------------------------------------- * 1. write iseven(n) three ways: declaration, expression, arrow. * 2. write a function with a default greeting parameter. * 3. write average(...nums) that returns the mean of any count of numbers. * 4. write a recursive countdown(n) that logs n, n-1, ... down to 0. * 5. write a recursive power(base, exp) — no math.pow, no ** operator. * ------------------------------------------------------------------------- */"},"lessons/10-scope-closures.js":{"title":"* 10 · scope & closures","learn":"* • global, function, and block scope * • lexical scope (inner functions see outer variables) * • closures — the single most important \"aha\" concept in js","practice":"/* practice ------------------------------------------------------------------- * 1. write makeadder(x) that returns a function adding x to its argument. * const add5 = makeadder(5); add5(10) === 15 * 2. build a once(fn) wrapper that runs fn only the first time it's called. * 3. explain in your own words why `count` survives between counter() calls. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 10 · scope & closures * ============================================================================= * run: node lessons/10-scope-closures.js * * what you'll learn * • global, function, and block scope * • lexical scope (inner functions see outer variables) * • closures — the single most important \"aha\" concept in js * ========================================================================== */ // ── 1. the three scopes ────────────────────────────────────────────────────── const globalvar = 'i am global'; // visible everywhere function outer() { const functionvar = 'i am in outer()'; // visible inside outer() only console.log(globalvar); // ✅ inner code can see outer scopes console.log(functionvar); // ✅ if (true) { const blockvar = 'i am in this block'; // visible in this { } only console.log(blockvar); // ✅ } // console.log(blockvar); // ❌ referenceerror — block-scoped } outer(); // console.log(functionvar); // ❌ referenceerror — not visible outside // ── 2. lexical scope ───────────────────────────────────────────────────────── // \"lexical\" = scope is determined by where code is written, not where it runs. // inner functions always have access to the variables of their parents. function grandparent() { const family = 'smith'; function parent() { function child() { return family; // reaches all the way up to grandparent's variable } return child(); } return parent(); } console.log(grandparent()); // => smith // ── 3. closures ────────────────────────────────────────────────────────────── // a closure = a function that \"remembers\" the variables from where it was // created, even after that outer function has finished running. function makecounter() { let count = 0; // this variable is \"enclosed\" by the inner function return function () { count++; // it keeps living between calls return count; }; } const counter = makecounter(); console.log(counter()); // => 1 console.log(counter()); // => 2 console.log(counter()); // => 3 (count persists — that's the closure!) // each closure gets its own private count (a fresh variable per call): const countera = makecounter(); const counterb = makecounter(); console.log(countera()); // => 1 console.log(countera()); // => 2 console.log(counterb()); // => 1 (independent from countera) // ── 4. practical use: data privacy ─────────────────────────────────────────── // closures let you create \"private\" variables that can't be touched directly. function createbankaccount(initial) { let balance = initial; // private — no outside code can read/write it return { deposit(amount) { balance += amount; return balance; }, withdraw(amount) { if (amount > balance) return 'insufficient funds'; balance -= amount; return balance; }, getbalance() { return balance; }, }; } const account = createbankaccount(100); console.log(account.deposit(50)); // => 150 console.log(account.withdraw(30)); // => 120 console.log(account.getbalance()); // => 120 // account.balance is undefined — it's truly private. console.log(account.balance); // => undefined /* practice ------------------------------------------------------------------- * 1. write makeadder(x) that returns a function adding x to its argument. * const add5 = makeadder(5); add5(10) === 15 * 2. build a once(fn) wrapper that runs fn only the first time it's called. * 3. explain in your own words why `count` survives between counter() calls. * ------------------------------------------------------------------------- */"},"lessons/11-this-keyword.js":{"title":"* 11 · the `this` keyword","learn":"* • what `this` refers to (it depends on how a function is called) * • why arrow functions don't have their own `this` * • call, apply, and bind * * big idea: `this` is not decided where a function is written — it's decided * by how the function is called.","practice":"/* practice ------------------------------------------------------------------- * 1. make an object `dog` with a name and a bark() method using `this`. * 2. break it by extracting the method: const b = dog.bark; b(); — see why. * 3. fix it with .bind(dog). * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 11 · the `this` keyword * ============================================================================= * run: node lessons/11-this-keyword.js * * what you'll learn * • what `this` refers to (it depends on how a function is called) * • why arrow functions don't have their own `this` * • call, apply, and bind * * big idea: `this` is not decided where a function is written — it's decided * by how the function is called. * ========================================================================== */ // ── 1. `this` inside an object method = the object ─────────────────────────── const user = { name: 'sam', greet() { return `hi, i'm ${this.name}`; // `this` = the object the method is called on }, }; console.log(user.greet()); // => hi, i'm sam // ── 2. the classic gotcha: a regular function inside a method ──────────────── const team = { name: 'rockets', members: ['ana', 'bob'], listbroken() { // ❌ a normal function gets its own `this`. called by foreach with no // context, `this` is not the team object — either way `this.name` is // lost. (in strict mode / es modules `this` is `undefined`; in sloppy // mode it's the global object, which has no `name`.) we use `this?.name` // below so it reads `undefined` instead of throwing. const out = []; this.members.foreach(function (m) { out.push(`${m} is on ${this?.name}`); // this?.name → undefined, not \"rockets\" }); return out; }, listfixed() { // ✅ arrow functions don't have their own `this` — they reuse the // surrounding `this` (the team object). this is why arrows shine here. this.members.foreach((m) => { console.log(`${m} is on ${this.name}`); }); }, }; // see the bug for real: the name is lost because `this` isn't the team object. console.log(team.listbroken()); // => [ 'ana is on undefined', 'bob is on undefined' ] team.listfixed(); // => ana is on rockets / bob is on rockets // ── 3. arrow functions inherit `this` ──────────────────────────────────────── const counter = { count: 0, // ❌ don't use an arrow for the method itself — it would grab the outer // (module/global) `this`, not the object. increment() { const helper = () => ++this.count; // arrow keeps `this` = counter return helper(); }, }; console.log(counter.increment()); // => 1 console.log(counter.increment()); // => 2 // ── 4. call / apply / bind — manually set `this` ───────────────────────────── function introduce(greeting) { return `${greeting}, i'm ${this.name}`; } const person = { name: 'alex' }; // call: run now, pass `this` then arguments one by one console.log(introduce.call(person, 'hello')); // => hello, i'm alex // apply: like call, but arguments come as an array console.log(introduce.apply(person, ['hi'])); // => hi, i'm alex // bind: don't run now — return a new function with `this` permanently fixed const boundintro = introduce.bind(person); console.log(boundintro('hey')); // => hey, i'm alex /* quick reference ------------------------------------------------------------ * obj.method() → this = obj * standalone() → this = undefined (strict) or globalthis * arrow function → this = whatever it was in the enclosing scope * fn.call/apply/bind → this = the object you provide * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. make an object `dog` with a name and a bark() method using `this`. * 2. break it by extracting the method: const b = dog.bark; b(); — see why. * 3. fix it with .bind(dog). * ------------------------------------------------------------------------- */"},"lessons/12-arrays.js":{"title":"* 12 · arrays — basics","learn":"* • creating and accessing arrays * • adding / removing elements (the mutating methods) * • mutating vs non-mutating operations * (transform methods like map/filter/reduce get their own lesson — 13.)","practice":"/* practice ------------------------------------------------------------------- * 1. start with [], push 3 items, then remove the first one. * 2. sort [42, 7, 100, 1] numerically ascending and descending. * 3. copy an array, mutate the copy, and prove the original is unchanged. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 12 · arrays — basics * ============================================================================= * run: node lessons/12-arrays.js * * what you'll learn * • creating and accessing arrays * • adding / removing elements (the mutating methods) * • mutating vs non-mutating operations * (transform methods like map/filter/reduce get their own lesson — 13.) * ========================================================================== */ // ── 1. creating & accessing ────────────────────────────────────────────────── const fruits = ['apple', 'banana', 'cherry']; console.log(fruits[0]); // => apple (zero-indexed) console.log(fruits.at(-1)); // => cherry (.at supports negative indexes) console.log(fruits.length); // => 3 // arrays can hold any mix of types (but usually keep them consistent): const mixed = [1, 'two', true, null, { id: 1 }]; console.log(mixed.length); // => 5 // ── 2. add / remove at the ends (these mutate the array) ───────────────────── const stack = ['a', 'b']; stack.push('c'); // add to end → ['a','b','c'] console.log(stack.pop());// remove from end → returns 'c', array is ['a','b'] stack.unshift('z'); // add to start → ['z','a','b'] console.log(stack.shift());// remove from start → returns 'z', array is ['a','b'] console.log(stack); // => [ 'a', 'b' ] // ── 3. splice — remove/insert anywhere (mutates) ───────────────────────────── const nums = [1, 2, 3, 4, 5]; // splice(startindex, deletecount, ...itemstoinsert) nums.splice(1, 2); // remove 2 items starting at index 1 console.log(nums); // => [ 1, 4, 5 ] nums.splice(1, 0, 'x', 'y');// insert without deleting console.log(nums); // => [ 1, 'x', 'y', 4, 5 ] // ── 4. slice — copy a portion (does not mutate) ────────────────────────────── const letters = ['a', 'b', 'c', 'd']; console.log(letters.slice(1, 3)); // => [ 'b', 'c' ] (end not included) console.log(letters.slice(-2)); // => [ 'c', 'd' ] console.log(letters); // => [ 'a', 'b', 'c', 'd' ] (unchanged — slice copies) // ── 5. searching ───────────────────────────────────────────────────────────── const colors = ['red', 'green', 'blue']; console.log(colors.includes('green')); // => true console.log(colors.indexof('blue')); // => 2 (-1 if not found) // ── 6. combining & converting ──────────────────────────────────────────────── console.log([1, 2].concat([3, 4])); // => [1,2,3,4] (non-mutating join) console.log([1, 2, 3].join('-')); // => \"1-2-3\" (array → string) console.log([3, 1, 2].sort()); // => [1,2,3] (⚠️ mutates, sorts as text) console.log([1, 2, 3].reverse()); // => [3,2,1] (⚠️ mutates) // ⚠️ default sort is alphabetical! for numbers, pass a comparator: console.log([10, 2, 1].sort()); // => [1, 10, 2] (wrong!) console.log([10, 2, 1].sort((a, b) => a - b)); // => [1, 2, 10] (correct) // ── 7. copying safely (avoid accidental shared references) ─────────────────── const source = [1, 2, 3]; const copy1 = [...source]; // spread copy const copy2 = source.slice(); // slice copy copy1.push(4); console.log(source, copy1); // => [1,2,3] [1,2,3,4] (source untouched) // `fill` overwrites a range with one value (mutates the array): console.log([1, 2, 3, 4].fill(0, 1, 3)); // => [1, 0, 0, 4] (indices 1–2 → 0) /* mutating vs non-mutating --------------------------------------------------- * mutates: push pop shift unshift splice sort reverse fill * returns new: slice concat map filter [...spread] join * when in doubt, prefer non-mutating — it prevents sneaky bugs. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. start with [], push 3 items, then remove the first one. * 2. sort [42, 7, 100, 1] numerically ascending and descending. * 3. copy an array, mutate the copy, and prove the original is unchanged. * ------------------------------------------------------------------------- */"},"lessons/13-array-methods.js":{"title":"* 13 · array methods — map, filter, reduce & friends","learn":"* • the \"iteration\" methods every js developer uses daily * • how they take a callback function * • chaining them together for clean data transformations * * these are non-mutating — they return new arrays/values and leave the * original alone. this is the heart of modern, readable javascript.","practice":"/* practice ------------------------------------------------------------------- * 1. from [1..10], map to squares, then filter to keep only even squares. * 2. use reduce to find the longest word in ['hi','hello','hey','howdy']. * 3. from a list of {name, age} people, get the names of everyone 18+. * 4. use tosorted to sort [5, 3, 8, 1] descending, and prove the original * array is unchanged. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 13 · array methods — map, filter, reduce & friends * ============================================================================= * run: node lessons/13-array-methods.js * * what you'll learn * • the \"iteration\" methods every js developer uses daily * • how they take a callback function * • chaining them together for clean data transformations * * these are non-mutating — they return new arrays/values and leave the * original alone. this is the heart of modern, readable javascript. * ========================================================================== */ const numbers = [1, 2, 3, 4, 5, 6]; // ── 1. foreach — do something for each item (returns nothing) ───────────────── numbers.foreach((n) => console.log('item:', n)); // side effects only // ── 2. map — transform each item into a new array (same length) ────────────── const doubled = numbers.map((n) => n * 2); console.log(doubled); // => [ 2, 4, 6, 8, 10, 12 ] const names = ['ana', 'bob']; console.log(names.map((name) => name.touppercase())); // => [ 'ana', 'bob' ] // ── 3. filter — keep only items that pass a test (length may shrink) ───────── const evens = numbers.filter((n) => n % 2 === 0); console.log(evens); // => [ 2, 4, 6 ] // ── 4. reduce — boil an array down to a single value ───────────────────────── // reduce((accumulator, current) => ..., startingvalue) const total = numbers.reduce((sum, n) => sum + n, 0); console.log(total); // => 21 // reduce is powerful — e.g. find the max, or count occurrences: const max = numbers.reduce((biggest, n) => (n > biggest ? n : biggest)); console.log(max); // => 6 // ⚠️ this reduce has no starting value (it uses the first item as the seed). // fine for a non-empty array — but `[].reduce((a, b) => a + b)` throws // \"reduce of empty array with no initial value\". pass a seed (like the `, 0` // in the sum above) whenever the array might be empty. const letters = ['a', 'b', 'a', 'c', 'b', 'a']; const counts = letters.reduce((tally, letter) => { tally[letter] = (tally[letter] || 0) + 1; return tally; }, {}); console.log(counts); // => { a: 3, b: 2, c: 1 } // ── 5. find / findindex — get the first match ──────────────────────────────── const users = [ { id: 1, name: 'ana' }, { id: 2, name: 'bob' }, ]; console.log(users.find((u) => u.id === 2)); // => { id: 2, name: 'bob' } console.log(users.findindex((u) => u.id === 2)); // => 1 // (find returns undefined and findindex returns -1 when nothing matches) // ── 6. some / every — boolean tests across the array ───────────────────────── console.log(numbers.some((n) => n > 5)); // => true (at least one matches) console.log(numbers.every((n) => n > 0)); // => true (all match) // ── 7. sort (non-mutating with a copy) ─────────────────────────────────────── const scores = [42, 7, 100, 1]; const sorted = [...scores].sort((a, b) => a - b); // copy first to avoid mutation console.log(sorted); // => [ 1, 7, 42, 100 ] console.log(scores); // => [ 42, 7, 100, 1 ] (original preserved) // ── 7b. immutable versions (es2023): tosorted / toreversed / with / findlast ── // these make the copy for you — no more [...spread] before sort/reverse, and // `.sort()`/`.reverse()`/`arr[i] = x` are the mutating ones to avoid. console.log(scores.tosorted((a, b) => a - b)); // => [ 1, 7, 42, 100 ] (brand-new array) console.log(scores); // => [ 42, 7, 100, 1 ] (still untouched) console.log([1, 2, 3].toreversed()); // => [ 3, 2, 1 ] console.log([1, 2, 3].with(1, 99)); // => [ 1, 99, 3 ] (copy, index 1 replaced) console.log([1, 2, 3, 4].findlast((n) => n % 2 === 0)); // => 4 (like find, but from the end) // ── 8. flat / flatmap ──────────────────────────────────────────────────────── console.log([1, [2, [3]]].flat()); // => [ 1, 2, [3] ] (one level) console.log([1, [2, [3]]].flat(infinity)); // => [ 1, 2, 3 ] (all levels) // ── 9. chaining — the real power ───────────────────────────────────────────── // \"from these orders, get the total of completed orders over $50.\" const orders = [ { item: 'pen', price: 5, done: true }, { item: 'laptop', price: 900, done: true }, { item: 'mouse', price: 60, done: false }, { item: 'monitor',price: 200, done: true }, ]; const revenue = orders .filter((o) => o.done) // keep completed .filter((o) => o.price > 50) // keep > $50 .map((o) => o.price) // get just the prices .reduce((sum, p) => sum + p, 0); // add them up console.log(revenue); // => 1100 /* practice ------------------------------------------------------------------- * 1. from [1..10], map to squares, then filter to keep only even squares. * 2. use reduce to find the longest word in ['hi','hello','hey','howdy']. * 3. from a list of {name, age} people, get the names of everyone 18+. * 4. use tosorted to sort [5, 3, 8, 1] descending, and prove the original * array is unchanged. * ------------------------------------------------------------------------- */"},"lessons/14-objects.js":{"title":"* 14 · objects","learn":"* • creating objects, reading/writing/deleting properties * • methods and shorthand syntax * • iterating with object.keys / values / entries * • copying and merging objects * • getters/setters, property descriptors, and freezing * • json — turning objects into text and back","practice":"/* practice ------------------------------------------------------------------- * 1. build a `book` object with title, author, and a summary() method. * 2. loop over its entries and print \"key: value\" lines. * 3. merge two settings objects so the second overrides the first. * 4. json.stringify the book, then json.parse it back — notice the * summary() method is gone. why? (json only stores plain data.) * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 14 · objects * ============================================================================= * run: node lessons/14-objects.js * * what you'll learn * • creating objects, reading/writing/deleting properties * • methods and shorthand syntax * • iterating with object.keys / values / entries * • copying and merging objects * • getters/setters, property descriptors, and freezing * • json — turning objects into text and back * ========================================================================== */ // ── 1. creating & accessing ────────────────────────────────────────────────── const user = { name: 'sam', age: 25, 'favorite color': 'blue', // keys with spaces need quotes }; console.log(user.name); // => sam (dot notation — preferred) console.log(user['age']); // => 25 (bracket notation) console.log(user['favorite color']); // => blue (brackets required for odd keys) // bracket notation is essential when the key is in a variable: const key = 'name'; console.log(user[key]); // => sam // ── 2. adding, updating, deleting ──────────────────────────────────────────── user.email = 'sam@example.com'; // add user.age = 26; // update delete user['favorite color']; // delete console.log(user); // => { name: 'sam', age: 26, email: 'sam@example.com' } // check if a key exists: console.log('email' in user); // => true console.log(user.phone === undefined); // => true (phone doesn't exist) // ── 3. methods & `this` ────────────────────────────────────────────────────── const account = { owner: 'alex', balance: 100, // method shorthand (no `function` keyword needed): describe() { return `${this.owner} has $${this.balance}`; }, }; console.log(account.describe()); // => alex has $100 // ── 4. shorthand property names ────────────────────────────────────────────── const name = 'dana'; const age = 30; // instead of { name: name, age: age }: const person = { name, age }; console.log(person); // => { name: 'dana', age: 30 } // ── 5. computed property names ─────────────────────────────────────────────── const field = 'score'; const result = { [field]: 95 }; // the key comes from a variable console.log(result); // => { score: 95 } // ── 6. iterating over an object ────────────────────────────────────────────── const car = { make: 'toyota', model: 'corolla', year: 2020 }; console.log(object.keys(car)); // => [ 'make', 'model', 'year' ] console.log(object.values(car)); // => [ 'toyota', 'corolla', 2020 ] console.log(object.entries(car));// => [ ['make','toyota'], ['model','corolla'], ['year',2020] ] // entries() pairs nicely with for...of and destructuring: for (const [k, v] of object.entries(car)) { console.log(`${k} = ${v}`); // => make = toyota, etc. } // ── 7. copying & merging (shallow) ─────────────────────────────────────────── const defaults = { theme: 'light', fontsize: 14 }; const overrides = { fontsize: 18 }; const settings = { ...defaults, ...overrides }; // later keys win console.log(settings); // => { theme: 'light', fontsize: 18 } // object.assign does the same (mutates the first argument): const merged = object.assign({}, defaults, overrides); console.log(merged); // => { theme: 'light', fontsize: 18 } // ⚠️ spread is a shallow copy — nested objects are still shared: const original = { nested: { a: 1 } }; const shallow = { ...original }; shallow.nested.a = 99; console.log(original.nested.a); // => 99 (the nested object is shared!) // for a deep copy of plain data: structuredclone(original) const deep = structuredclone(original); deep.nested.a = 1; console.log(original.nested.a, deep.nested.a); // => 99 1 // ── 8. nested objects & optional chaining ──────────────────────────────────── const company = { ceo: { name: 'lee', contact: { city: 'pune' } } }; console.log(company.ceo.contact.city); // => pune console.log(company.cfo?.contact?.city); // => undefined (no crash) // ── 9. getters & setters on plain objects ──────────────────────────────────── // a getter/setter looks like a normal property from the outside, but runs a // function. great for computed/derived values. (classes do this too — lesson 17.) const temperature = { celsius: 25, get fahrenheit() { // read like a property: temperature.fahrenheit return this.celsius * 1.8 + 32; }, set fahrenheit(f) { // write like a property: temperature.fahrenheit = 212 this.celsius = (f - 32) / 1.8; }, }; console.log(temperature.fahrenheit); // => 77 (computed, no parentheses) temperature.fahrenheit = 212; console.log(temperature.celsius); // => 100 (the setter ran) // ── 10. property descriptors & object.defineproperty ───────────────────────── // every property secretly has flags: writable, enumerable, configurable. // normal assignment makes all three true. defineproperty lets you control them. const config = {}; object.defineproperty(config, 'version', { value: '1.0', writable: false, // can't be reassigned enumerable: false, // hidden from object.keys / for...in / json configurable: false,// can't be deleted or redefined }); config.version = '2.0'; // silently ignored (throws in strict mode) console.log(config.version); // => 1.0 console.log(object.keys(config)); // => [] (it's non-enumerable) console.log(object.getownpropertydescriptor(config, 'version')); // => { value: '1.0', writable: false, enumerable: false, configurable: false } // ── 11. locking objects: freeze & seal ─────────────────────────────────────── // freeze: no add, no remove, no change — fully read-only (shallow). const settingsfrozen = object.freeze({ theme: 'dark', fontsize: 14 }); settingsfrozen.fontsize = 99; // ignored (throws in strict mode) settingsfrozen.newkey = 1; // ignored — can't add either console.log(settingsfrozen, object.isfrozen(settingsfrozen)); // => {...unchanged}, true // seal: can change existing values, but can't add or remove keys. const sealed = object.seal({ count: 0 }); sealed.count = 5; // ✅ allowed (existing key) sealed.extra = 1; // ❌ ignored (can't add) console.log(sealed, object.issealed(sealed)); // => { count: 5 }, true // ⚠️ freeze is shallow — nested objects can still change. // for deep immutability, freeze recursively or keep data flat. // ── 12. json — objects as text ─────────────────────────────────────────────── // json (javascript object notation) is how objects travel: saved to a file, // stored in localstorage, or sent over the network. it is plain text, not an // object. two functions convert back and forth: const profile = { name: 'sam', age: 25, tags: ['js', 'css'], active: true }; const text = json.stringify(profile); // object → json string console.log(text); // => {\"name\":\"sam\",\"age\":25,\"tags\":[\"js\",\"css\"],\"active\":true} const back = json.parse(text); // json string → object (a new object) console.log(back.name, back.tags[0]); // => sam js // pretty-print: pass a \"space\" argument (great for logs and files): console.log(json.stringify(profile, null, 2)); // 2-space indented, multi-line // pick/transform fields with a replacer (array = allowlist, or a function): console.log(json.stringify(profile, ['name', 'age'])); // => {\"name\":\"sam\",\"age\":25} // revive values while parsing with a reviver (e.g. rebuild dates): const order = json.parse('{\"id\":1,\"when\":\"2026-06-05t00:00:00.000z\"}', (k, v) => k === 'when' ? new date(v) : v ); console.log(order.when instanceof date); // => true // ⚠️ what json drops — it only understands plain data: // • functions, undefined, and symbols are omitted from objects // • date becomes a string (use a reviver to turn it back, as above) // • map/set become {} ; nan and infinity become null const messy = { fn() {}, skip: undefined, when: new date(0), n: nan }; console.log(json.stringify(messy)); // => {\"when\":\"1970-01-01t00:00:00.000z\",\"n\":null} // ⚠️ always guard json.parse — bad text throws: try { json.parse('{ not valid }'); } catch (err) { console.log('parse failed:', err.name); // => syntaxerror } // the \"json deep-copy trick\" — quick, but only for plain json-safe data // (loses the same things listed above). prefer structuredclone for general use. const copy = json.parse(json.stringify(profile)); copy.tags.push('html'); console.log(profile.tags.length, copy.tags.length); // => 2 3 (independent) /* practice ------------------------------------------------------------------- * 1. build a `book` object with title, author, and a summary() method. * 2. loop over its entries and print \"key: value\" lines. * 3. merge two settings objects so the second overrides the first. * 4. json.stringify the book, then json.parse it back — notice the * summary() method is gone. why? (json only stores plain data.) * ------------------------------------------------------------------------- */"},"lessons/15-destructuring-spread.js":{"title":"* 15 · destructuring & spread / rest","learn":"* • pulling values out of arrays and objects in one line (destructuring) * • spreading (...) to expand arrays/objects * • rest (...) to collect leftovers * these show up everywhere in modern js — learn them well.","practice":"/* practice ------------------------------------------------------------------- * 1. destructure { title, year } from a movie object, defaulting year to 2024. * 2. merge two arrays and dedupe them with [...new set([...a, ...b])]. * 3. write a function printfirstandrest(first, ...rest) and test it. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 15 · destructuring & spread / rest * ============================================================================= * run: node lessons/15-destructuring-spread.js * * what you'll learn * • pulling values out of arrays and objects in one line (destructuring) * • spreading (...) to expand arrays/objects * • rest (...) to collect leftovers * these show up everywhere in modern js — learn them well. * ========================================================================== */ // ── 1. array destructuring ─────────────────────────────────────────────────── const rgb = [255, 128, 0]; const [red, green, blue] = rgb; // unpack by position console.log(red, green, blue); // => 255 128 0 // skip items with empty commas: const [first, , third] = ['a', 'b', 'c']; console.log(first, third); // => a c // default values for missing items: const [x = 0, y = 0, z = 0] = [10, 20]; console.log(x, y, z); // => 10 20 0 // swap variables without a temp variable: let a = 1, b = 2; [a, b] = [b, a]; console.log(a, b); // => 2 1 // ── 2. object destructuring ────────────────────────────────────────────────── const user = { name: 'sam', age: 25, city: 'pune' }; const { name, age } = user; // unpack by key name (order doesn't matter) console.log(name, age); // => sam 25 // rename while unpacking: const { name: fullname } = user; console.log(fullname); // => sam // defaults for missing keys: const { country = 'india' } = user; console.log(country); // => india // nested destructuring: const order = { id: 7, customer: { email: 'a@b.com' } }; const { customer: { email } } = order; console.log(email); // => a@b.com // ── 3. destructuring in function parameters (very common) ──────────────────── // instead of accepting an object and reading props inside: function greet({ name, greeting = 'hello' }) { return `${greeting}, ${name}!`; } console.log(greet({ name: 'ana' })); // => hello, ana! console.log(greet({ name: 'bob', greeting: 'hey' })); // => hey, bob! // ── 4. spread (...) — expand an iterable into individual elements ──────────── // combine arrays: const lows = [1, 2]; const highs = [3, 4]; console.log([...lows, ...highs]); // => [ 1, 2, 3, 4 ] // copy an array (shallow): const copy = [...lows]; // pass array items as separate arguments: console.log(math.max(...[5, 9, 2])); // => 9 // merge / clone objects (later keys win): const base = { theme: 'light', size: 14 }; const custom = { ...base, size: 18 }; // => { theme: 'light', size: 18 } console.log(custom); // spread a string into characters: console.log([...'abc']); // => [ 'a', 'b', 'c' ] // ── 5. rest (...) — collect \"the rest\" into an array/object ────────────────── // in array destructuring: const [winner, ...runnersup] = ['gold', 'silver', 'bronze']; console.log(winner); // => gold console.log(runnersup); // => [ 'silver', 'bronze' ] // in object destructuring: const { id, ...details } = { id: 1, name: 'sam', age: 25 }; console.log(id); // => 1 console.log(details); // => { name: 'sam', age: 25 } // in function parameters (gather all arguments): function sum(...nums) { return nums.reduce((t, n) => t + n, 0); } console.log(sum(1, 2, 3, 4)); // => 10 // spread vs rest: same `...` symbol, opposite jobs. // spread → expands something out (used in calls/literals). // rest → collects many into one (used in parameters/patterns). /* practice ------------------------------------------------------------------- * 1. destructure { title, year } from a movie object, defaulting year to 2024. * 2. merge two arrays and dedupe them with [...new set([...a, ...b])]. * 3. write a function printfirstandrest(first, ...rest) and test it. * ------------------------------------------------------------------------- */"},"lessons/16-sets-maps.js":{"title":"* 16 · sets & maps","learn":"* • set — a collection of unique values * • map — key/value pairs where keys can be any type * • when to reach for these instead of arrays/objects","practice":"/* practice ------------------------------------------------------------------- * 1. count unique words in \"the cat the dog the bird\" using a set. * 2. build a map of country → capital and print each pair. * 3. use a map to tally how many times each letter appears in \"banana\". * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 16 · sets & maps * ============================================================================= * run: node lessons/16-sets-maps.js * * what you'll learn * • set — a collection of unique values * • map — key/value pairs where keys can be any type * • when to reach for these instead of arrays/objects * ========================================================================== */ // ── 1. set — unique values, fast membership checks ─────────────────────────── const ids = new set(); ids.add(1); ids.add(2); ids.add(2); // ignored — already present ids.add(3); console.log(ids); // => set(3) { 1, 2, 3 } console.log(ids.size); // => 3 console.log(ids.has(2)); // => true (o(1) lookup — beats array.includes for big collections) ids.delete(1); console.log([...ids]); // => [ 2, 3 ] (spread to convert back to an array) // ⭐ most common use: remove duplicates from an array in one line. const withdupes = [1, 2, 2, 3, 3, 3, 4]; const unique = [...new set(withdupes)]; console.log(unique); // => [ 1, 2, 3, 4 ] // iterating a set: for (const id of ids) console.log('id:', id); // ── 2. map — key/value pairs with any key type ─────────────────────────────── // unlike objects (whose keys are only strings or symbols), map keys can be numbers, // objects, functions — anything. and it remembers insertion order. const scores = new map(); scores.set('ana', 90); scores.set('bob', 75); console.log(scores.get('ana')); // => 90 console.log(scores.has('bob')); // => true console.log(scores.size); // => 2 scores.delete('bob'); // object keys (impossible with a plain object): const usera = { id: 1 }; const lastseen = new map(); lastseen.set(usera, '2026-06-04'); console.log(lastseen.get(usera)); // => 2026-06-04 // iterating a map (entries are [key, value] pairs): const colors = new map([ ['red', '#f00'], ['green', '#0f0'], ]); for (const [name, hex] of colors) { console.log(`${name} → ${hex}`); // => red → #f00, green → #0f0 } console.log([...colors.keys()]); // => [ 'red', 'green' ] console.log([...colors.values()]); // => [ '#f00', '#0f0' ] // ── 3. object vs map — which to use? ───────────────────────────────────────── // use a plain object when: // • keys are fixed, known strings (\"structured record\") // • you want json serialization (json.stringify works on objects) // use a map when: // • keys are dynamic, or not strings // • you frequently add/remove entries // • you need a reliable .size and guaranteed insertion order // convert between them: const obj = object.fromentries(colors); // map → object console.log(obj); // => { red: '#f00', green: '#0f0' } const backtomap = new map(object.entries(obj)); // object → map console.log(backtomap.size); // => 2 /* practice ------------------------------------------------------------------- * 1. count unique words in \"the cat the dog the bird\" using a set. * 2. build a map of country → capital and print each pair. * 3. use a map to tally how many times each letter appears in \"banana\". * ------------------------------------------------------------------------- */"},"lessons/17-classes-oop.js":{"title":"* 17 · classes & object-oriented programming","learn":"* • defining a class with a constructor and methods * • creating instances with `new` * • inheritance with `extends` and `super` * • getters/setters, static members, and private fields (#)","practice":"/* practice ------------------------------------------------------------------- * 1. make a class rectangle(width, height) with an area() method. * 2. extend it as square(side) using super. * 3. add a static method rectangle.fromobject({width, height}). * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 17 · classes & object-oriented programming * ============================================================================= * run: node lessons/17-classes-oop.js * * what you'll learn * • defining a class with a constructor and methods * • creating instances with `new` * • inheritance with `extends` and `super` * • getters/setters, static members, and private fields (#) * ========================================================================== */ // ── 1. a basic class ───────────────────────────────────────────────────────── class animal { // the constructor runs when you do `new animal(...)`. constructor(name, sound) { this.name = name; // instance properties this.sound = sound; } // a method (shared by all instances): speak() { return `${this.name} says ${this.sound}`; } } const dog = new animal('rex', 'woof'); console.log(dog.speak()); // => rex says woof console.log(dog instanceof animal); // => true // ── 2. inheritance with extends / super ────────────────────────────────────── class dog extends animal { constructor(name, breed) { super(name, 'woof'); // call the parent constructor first this.breed = breed; } // add new behavior: fetch() { return `${this.name} fetches the ball`; } // override a parent method (and optionally reuse it via super): speak() { return `${super.speak()} (a ${this.breed})`; } } const buddy = new dog('buddy', 'labrador'); console.log(buddy.speak()); // => buddy says woof (a labrador) console.log(buddy.fetch()); // => buddy fetches the ball // ── 3. getters & setters — computed/guarded properties ─────────────────────── class temperature { constructor(celsius) { this.celsius = celsius; } // accessed like a property (no parentheses): temp.fahrenheit get fahrenheit() { return this.celsius * 1.8 + 32; } set fahrenheit(value) { this.celsius = (value - 32) / 1.8; } } const temp = new temperature(25); console.log(temp.fahrenheit); // => 77 (getter — note: no () ) temp.fahrenheit = 212; // setter console.log(temp.celsius); // => 100 // ── 4. static members — belong to the class, not instances ─────────────────── class mathutils { static pi = 3.14159; static double(n) { return n * 2; } } console.log(mathutils.pi); // => 3.14159 (called on the class itself) console.log(mathutils.double(8)); // => 16 // const m = new mathutils(); m.double(8) // ❌ static methods aren't on instances // ── 5. private fields (#) — true encapsulation ─────────────────────────────── class bankaccount { #balance = 0; // private — only accessible inside this class constructor(initial) { this.#balance = initial; } deposit(amount) { this.#balance += amount; return this.#balance; } get balance() { return this.#balance; } } const acct = new bankaccount(100); console.log(acct.deposit(50)); // => 150 console.log(acct.balance); // => 150 // console.log(acct.#balance); // ❌ syntaxerror — private outside the class /* oop vocab ------------------------------------------------------------------ * class → a blueprint for objects * instance → an object made from a class (via `new`) * constructor → sets up a new instance * inheritance → a class building on another (extends/super) * encapsulation → hiding internal state (#private fields) * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. make a class rectangle(width, height) with an area() method. * 2. extend it as square(side) using super. * 3. add a static method rectangle.fromobject({width, height}). * ------------------------------------------------------------------------- */"},"lessons/18-prototypes.js":{"title":"* 18 · prototypes — how inheritance really works","learn":"* • the prototype chain — js's actual inheritance mechanism * • that `class` (lesson 17) is \"syntactic sugar\" over prototypes * • how property lookup walks up the chain * * this is more advanced/theoretical. you can write js for a long time using * only `class`, but understanding prototypes explains why things work.","practice":"/* practice ------------------------------------------------------------------- * 1. use object.create to make an object that inherits a `describe` method. * 2. check hasownproperty for an own vs inherited property. * 3. log the prototype chain of [] until you reach null. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 18 · prototypes — how inheritance really works * ============================================================================= * run: node lessons/18-prototypes.js * * what you'll learn * • the prototype chain — js's actual inheritance mechanism * • that `class` (lesson 17) is \"syntactic sugar\" over prototypes * • how property lookup walks up the chain * * this is more advanced/theoretical. you can write js for a long time using * only `class`, but understanding prototypes explains why things work. * ========================================================================== */ // ── 1. every object has a hidden link to a \"prototype\" ─────────────────────── // when you read obj.something, js looks on obj first; if not found, it follows // the link to obj's prototype, then its prototype, and so on — the \"chain\". const animal = { eats: true, walk() { return 'walking...'; }, }; // create `rabbit` whose prototype is `animal`: const rabbit = object.create(animal); rabbit.jumps = true; console.log(rabbit.jumps); // => true (own property) console.log(rabbit.eats); // => true (inherited from animal via the chain) console.log(rabbit.walk());// => walking... (method found on the prototype) // where did each property come from? console.log(rabbit.hasownproperty('jumps')); // => true (its own) console.log(rabbit.hasownproperty('eats')); // => false (inherited) // ── 2. the chain ends at null ──────────────────────────────────────────────── // rabbit → animal → object.prototype → null console.log(object.getprototypeof(rabbit) === animal); // => true console.log(object.getprototypeof(animal) === object.prototype); // => true console.log(object.getprototypeof(object.prototype)); // => null // ── 3. built-in methods live on prototypes ─────────────────────────────────── // when you call [1,2,3].map(...), `map` isn't on your array — it's on // array.prototype, found by walking the chain. const arr = [1, 2, 3]; console.log(object.getprototypeof(arr) === array.prototype); // => true console.log(arr.map === array.prototype.map); // => true // ── 4. constructor functions (the pre-`class` style) ───────────────────────── // before es6 classes, this is how \"classes\" were written. methods go on // the constructor's .prototype so all instances share one copy (memory-efficient). function person(name) { this.name = name; // instance-specific data } person.prototype.greet = function () { // shared method return `hi, i'm ${this.name}`; }; const sam = new person('sam'); console.log(sam.greet()); // => hi, i'm sam console.log(sam.greet === new person('x').greet); // => true (same shared function) // ── 5. `class` is sugar over all of this ───────────────────────────────────── // these two are essentially equivalent: class personclass { constructor(name) { this.name = name; } greet() { return `hi, i'm ${this.name}`; } } const sam2 = new personclass('sam'); console.log(typeof personclass); // => function (!) console.log(personclass.prototype.greet === object.getprototypeof(sam2).greet); // => true // the class syntax just put `greet` on the prototype for you, like §4. /* mental model --------------------------------------------------------------- * • reading a property → js walks up the prototype chain until it finds it. * • methods are stored once on the prototype and shared by all instances. * • `class` is friendlier syntax; under the hood it's prototypes all the way. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. use object.create to make an object that inherits a `describe` method. * 2. check hasownproperty for an own vs inherited property. * 3. log the prototype chain of [] until you reach null. * ------------------------------------------------------------------------- */"},"lessons/19-callbacks-promises.js":{"title":"* 19 · callbacks & promises (asynchronous javascript)","learn":"* • why js needs async (it's single-threaded) * • callbacks and \"callback hell\" * • promises: then / catch / finally * • promise.all / race / allsettled * * watch the output order when you run this — it teaches the event loop.","practice":"/* practice ------------------------------------------------------------------- * 1. wrap settimeout in a `delay(ms)` function that returns a promise. * 2. chain delay(100) → log \"done after 100ms\". * 3. use promise.all to wait for delay(50) and delay(150) together. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 19 · callbacks & promises (asynchronous javascript) * ============================================================================= * run: node lessons/19-callbacks-promises.js * * what you'll learn * • why js needs async (it's single-threaded) * • callbacks and \"callback hell\" * • promises: then / catch / finally * • promise.all / race / allsettled * * watch the output order when you run this — it teaches the event loop. * ========================================================================== */ // ── 1. js is single-threaded — it can't \"wait\" and block ───────────────────── // slow things (timers, network, files) are handed off and finish later. console.log('1: start'); settimeout(() => console.log('3: timeout finished (later)'), 0); console.log('2: end'); // output order: 1, 2, then 3 — even though the timeout was 0ms. the synchronous // code runs first; the callback waits in a queue until the stack is clear. // ── 2. callbacks — \"call this function when you're done\" ───────────────────── function fetchuser(id, callback) { settimeout(() => { callback({ id, name: 'sam' }); // simulate a 200ms network delay }, 200); } fetchuser(1, (user) => console.log('callback got:', user.name)); // => sam (after 200ms) // ⚠️ callback hell: nesting callbacks for sequential async steps gets ugly: // fetchuser(1, (user) => { // fetchposts(user, (posts) => { // fetchcomments(posts[0], (comments) => { ... }); // deeply nested 😖 // }); // }); // promises were invented to flatten this. // ── 3. promises — an object representing a future value ────────────────────── // a promise is in one of three states: pending → fulfilled (resolve) or rejected. const promise = new promise((resolve, reject) => { const success = true; settimeout(() => { if (success) resolve('✅ data loaded'); else reject(new error('❌ failed')); }, 100); }); promise .then((result) => console.log('then:', result)) // runs on resolve .catch((err) => console.log('catch:', err.message)) // runs on reject .finally(() => console.log('finally: always runs')); // ── 4. chaining — each .then returns a new promise (no more nesting!) ──────── function getuser(id) { return new promise((resolve) => settimeout(() => resolve({ id, name: 'ana' }), 50) ); } function getposts(user) { return new promise((resolve) => settimeout(() => resolve([`${user.name}'s post`]), 50) ); } getuser(1) .then((user) => getposts(user)) // return a promise → the chain waits for it .then((posts) => console.log('chained:', posts)) // => [ \"ana's post\" ] .catch((err) => console.log('error:', err)); // ── 5. running promises together ───────────────────────────────────────────── const p1 = promise.resolve('a'); const p2 = new promise((r) => settimeout(() => r('b'), 80)); const p3 = promise.resolve('c'); // promise.all — wait for all to finish (rejects if any one rejects): promise.all([p1, p2, p3]).then((values) => console.log('all:', values)); // => ['a','b','c'] // promise.race — settle as soon as the first one settles: promise.race([p2, promise.resolve('fast')]).then((v) => console.log('race:', v)); // => fast // promise.allsettled — wait for all, never rejects; reports each outcome: promise.allsettled([promise.resolve('ok'), promise.reject('bad')]).then((results) => console.log('allsettled:', results) ); // => [{status:'fulfilled',value:'ok'}, {status:'rejected',reason:'bad'}] /* key takeaways -------------------------------------------------------------- * • synchronous code always runs before any async callback/promise. * • .then chains replace nested callbacks. * • always end a chain with .catch to handle errors. * • next lesson (async/await) makes promises read like normal code. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. wrap settimeout in a `delay(ms)` function that returns a promise. * 2. chain delay(100) → log \"done after 100ms\". * 3. use promise.all to wait for delay(50) and delay(150) together. * ------------------------------------------------------------------------- */"},"lessons/20-async-await.js":{"title":"* 20 · async / await","learn":"* • async/await — write asynchronous code that reads like synchronous code * • error handling with try/catch * • running tasks in sequence vs in parallel (a common performance trap) * * async/await is just nicer syntax over promises (lesson 19). under the hood, * an async function always returns a promise.","practice":"/* practice ------------------------------------------------------------------- * 1. rewrite a .then() chain from lesson 19 using async/await. * 2. fetch two things in parallel with promise.all and time the difference. * 3. wrap a failing await in try/catch and log a friendly error message. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 20 · async / await * ============================================================================= * run: node lessons/20-async-await.js * * what you'll learn * • async/await — write asynchronous code that reads like synchronous code * • error handling with try/catch * • running tasks in sequence vs in parallel (a common performance trap) * * async/await is just nicer syntax over promises (lesson 19). under the hood, * an async function always returns a promise. * ========================================================================== */ // a tiny helper used throughout: resolves after `ms` milliseconds. function delay(ms, value) { return new promise((resolve) => settimeout(() => resolve(value), ms)); } // ── 1. the basics: async marks a function, await pauses for a promise ──────── async function loaddata() { console.log('loading...'); const result = await delay(100, '✅ data'); // pause here until it resolves console.log('got:', result); // runs after the await return result; // async functions return a promise } // compare to the promise version — same thing, fewer .then() callbacks: // const x = await loaddata() === loaddata().then(x => ...) // ── 2. error handling with try/catch (clean!) ──────────────────────────────── async function riskyload() { try { const data = await promise.reject(new error('network down')); console.log(data); // skipped — the await threw } catch (err) { console.log('caught:', err.message); // => caught: network down } finally { console.log('cleanup runs either way'); } } // ── 3. sequential vs parallel — a critical distinction ─────────────────────── async function sequential() { // ❌ slow: each await waits for the previous one. total ≈ 100+100+100 = 300ms. const a = await delay(100, 'a'); const b = await delay(100, 'b'); const c = await delay(100, 'c'); return [a, b, c]; } async function parallel() { // ✅ fast: start all three first, then await them together. total ≈ 100ms. const pa = delay(100, 'a'); // started now const pb = delay(100, 'b'); // started now const pc = delay(100, 'c'); // started now return promise.all([pa, pb, pc]); // wait for all in parallel } // rule: if tasks don't depend on each other, run them in parallel. // ── 4. await in a loop ─────────────────────────────────────────────────────── async function processinorder(items) { const results = []; for (const item of items) { const r = await delay(30, item.touppercase()); // one at a time, in order results.push(r); } return results; } // for independent items, prefer: await promise.all(items.map(processone)) // ── 5. run everything (top-level) ──────────────────────────────────────────── // we use an async iife so we can `await` at the top level in any environment. (async () => { await loaddata(); // => loading... / got: ✅ data await riskyload(); // => caught: network down / cleanup... console.log('sequential:', await sequential());// => [ 'a', 'b', 'c' ] (~300ms) console.log('parallel:', await parallel()); // => [ 'a', 'b', 'c' ] (~100ms) console.log('inorder:', await processinorder(['x', 'y', 'z'])); // => ['x','y','z'] })(); /* mental model --------------------------------------------------------------- * • `await x` means \"pause this function until promise x settles, then * give me its value (or throw its error)\". * • the rest of your program keeps running while an async function awaits. * • await only works inside an async function. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. rewrite a .then() chain from lesson 19 using async/await. * 2. fetch two things in parallel with promise.all and time the difference. * 3. wrap a failing await in try/catch and log a friendly error message. * ------------------------------------------------------------------------- */"},"lessons/21-how-javascript-runs.js":{"title":"* 21 · how javascript runs — execution context, the call stack & the event loop","learn":"* • what an execution context is (global + one per function call) * • its two phases — creation (memory) then execution — and how hoisting * falls right out of that * • the call stack: how js keeps track of \"where am i?\" * • why js is single-threaded, and what the event loop actually does * • microtasks (promises) vs macrotasks (timers) — and who runs first * • how async/await is \"just\" promises + the event loop underneath * * you've already used promises (lesson 19) and async/await (lesson 20). this * lesson reveals the machine underneath — the model that explains every * \"why did it log in that order?\" surprise. it's the single most-probed topic * in senior javascript interviews.","practice":"/* practice ------------------------------------------------------------------- * 1. predict the output order, then run to check: * console.log('a'); * settimeout(() => console.log('b'), 0); * promise.resolve().then(() => console.log('c')); * console.log('d'); * 2. write `boom()` that calls itself with no base case, wrap the call in * try/catch, and log the error's `.name` (you should see rangeerror). * 3. explain in a comment why `console.log(typeof y); let y = 1;` throws while * the same code with `var` prints `undefined`. * 4. using only promise.resolve().then(...) and settimeout(...), make four * logs print in the exact order: 1, 2, 3, 4 — where 1 & 2 are sync, * 3 is a microtask, and 4 is a macrotask. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 21 · how javascript runs — execution context, the call stack & the event loop * ============================================================================= * run: node lessons/21-how-javascript-runs.js * * what you'll learn * • what an execution context is (global + one per function call) * • its two phases — creation (memory) then execution — and how hoisting * falls right out of that * • the call stack: how js keeps track of \"where am i?\" * • why js is single-threaded, and what the event loop actually does * • microtasks (promises) vs macrotasks (timers) — and who runs first * • how async/await is \"just\" promises + the event loop underneath * * you've already used promises (lesson 19) and async/await (lesson 20). this * lesson reveals the machine underneath — the model that explains every * \"why did it log in that order?\" surprise. it's the single most-probed topic * in senior javascript interviews. * ========================================================================== */ 'use strict'; // ── 1. execution context & hoisting ────────────────────────────────────────── // when js runs a file (or enters a function) it builds an \"execution context\" // in two phases: // (a) creation phase — it scans the code and reserves memory: `var`s start as // `undefined`, function declarations are stored whole, `let`/`const` are // reserved but left uninitialised (the \"temporal dead zone\", lesson 01). // (b) execution phase — it runs the lines top to bottom, assigning values. // \"hoisting\" isn't magic — it's just what you see because of the creation phase. console.log(typeof reserved); // => undefined (var seen in creation, set later) var reserved = 42; console.log(reserved); // => 42 // function declarations are stored whole in the creation phase, so you can call // them before their line in the source: console.log(square(5)); // => 25 function square(n) { return n * n; } // ── 2. the call stack ──────────────────────────────────────────────────────── // js does one thing at a time. the call stack is the to-do pile: calling a // function pushes a context on top; returning pops it off. the function on top // is the one currently running. function greet(name) { return 'hi ' + name; } function welcome(name) { return greet(name) + '!'; // welcome pushes greet on top of itself } console.log(welcome('ada')); // => hi ada! // stack grows: [global] → [welcome] → [greet] then unwinds greet → welcome // if the stack never pops (infinite recursion) you get \"maximum call stack size // exceeded\" — a stack overflow. (try it yourself in the exercises below.) // ── 3. the event loop: microtasks vs macrotasks ────────────────────────────── // one thread can't block on slow things (timers, network, disk). so slow work is // handed to the host (node / the browser); when it's ready, its callback is put // on a queue. the event loop runs that callback only once the call stack is // empty. there are two queues, and the order between them is the classic gotcha: // // ┌─────────────┐ stack empty? ┌────────────────────────────┐ // │ call stack │ ───────────────▶ │ 1. drain all microtasks │ // └─────────────┘ │ (promise .then, await, │ // ▲ │ queuemicrotask) │ // │ run next │ 2. then one macrotask │ // └───────────────────────────│ (settimeout, setinterval,│ // │ i/o) — then back to 1 │ // └────────────────────────────┘ // rule of thumb: all microtasks run before the next macrotask. console.log('sync 1'); // => sync 1 settimeout(() => console.log('macrotask settimeout'), 0); promise.resolve().then(() => console.log('microtask promise then')); queuemicrotask(() => console.log('microtask queuemicrotask')); console.log('sync 2'); // => sync 2 // both sync lines run first (they're on the stack). then the loop drains the // microtask queue (fifo), then the one macrotask. real printed order: // => microtask promise then // => microtask queuemicrotask // => macrotask settimeout // ── 4. async/await is promises + the event loop ────────────────────────────── // `async` makes a function return a promise. `await` splits the function: the // part before it runs now (synchronously); everything after it is resumed later // as a microtask, once the awaited value settles. so `await` never \"blocks the // thread\" — it yields control back to the event loop. async function task() { console.log('task sync part'); // runs immediately, on the calling stack await promise.resolve(); console.log('task resumed after await'); // scheduled as a microtask } // we run this phase from inside a timer so its output prints cleanly after the // section-3 tasks have drained (a timer is a macrotask, so it waits its turn): settimeout(() => { console.log('before calling task'); // => before calling task task(); console.log('after calling task'); // => after calling task // order here: 'before calling task', then 'task sync part' (the sync half of // task runs on this stack), then 'after calling task', and finally — once the // stack is empty — the microtask resumes: 'task resumed after await'. // => task sync part // => task resumed after await }, 10); /* ----------------------------------------------------------------------------- * interview corner * q: \"what logs first — a settimeout(fn, 0) or a promise.resolve().then(fn)?\" * a: the promise. timers are macrotasks; promise callbacks are microtasks, and * every microtask runs before the next macrotask. * * q: \"does `await` block the thread?\" * a: no. it suspends only the async function and returns control to the event * loop; the rest resumes as a microtask when the awaited promise settles. * * q: \"why does `console.log(x); var x = 1;` print `undefined`, not crash?\" * a: creation phase reserved `x` as `undefined`; the assignment happens later. * (with `let`, the same code throws — the temporal dead zone.) * * common mistakes * • thinking timers are precise. settimeout(fn, 0) means \"after >= 0 ms and the * stack is clear and microtasks have drained\" — often much later than 0 ms. * • a long synchronous loop \"freezes\" everything: it never lets the stack empty, * so no callbacks, no rendering. break big work up (see lesson 30 · advanced * async) or move it off-thread (workers, lesson 47). * • assuming `await` parallelises. `await a(); await b();` is sequential; use * `promise.all([a(), b()])` to overlap them (lesson 20). * ---------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. predict the output order, then run to check: * console.log('a'); * settimeout(() => console.log('b'), 0); * promise.resolve().then(() => console.log('c')); * console.log('d'); * 2. write `boom()` that calls itself with no base case, wrap the call in * try/catch, and log the error's `.name` (you should see rangeerror). * 3. explain in a comment why `console.log(typeof y); let y = 1;` throws while * the same code with `var` prints `undefined`. * 4. using only promise.resolve().then(...) and settimeout(...), make four * logs print in the exact order: 1, 2, 3, 4 — where 1 & 2 are sync, * 3 is a microtask, and 4 is a macrotask. * ------------------------------------------------------------------------- */"},"lessons/22-error-handling.js":{"title":"* 22 · error handling","learn":"* • try / catch / finally * • throw and the error object * • custom error classes * • handling errors in async code * • global \"last resort\" handlers (browser & node)","practice":"/* best practices ------------------------------------------------------------- * • throw error objects, not strings. * • only catch errors you can meaningfully handle; re-throw the rest. * • don't leave an empty catch {} — at minimum, log it. * • use custom error classes so callers can react to specific failures. * --------------------------------------------------------------------------- */","body":"/* ============================================================================= * 22 · error handling * ============================================================================= * run: node lessons/22-error-handling.js * * what you'll learn * • try / catch / finally * • throw and the error object * • custom error classes * • handling errors in async code * • global \"last resort\" handlers (browser & node) * ========================================================================== */ // ── 1. try / catch / finally ───────────────────────────────────────────────── try { console.log('trying...'); const data = json.parse('{ invalid json }'); // this throws console.log(data); // skipped } catch (err) { console.log('caught:', err.message); // => caught: ... (parse error) } finally { console.log('finally always runs (cleanup, closing files, etc.)'); } // ── 2. throwing your own errors ────────────────────────────────────────────── // `throw` stops the function and jumps to the nearest catch. function divide(a, b) { if (b === 0) { throw new error('cannot divide by zero'); } return a / b; } try { console.log(divide(10, 2)); // => 5 console.log(divide(10, 0)); // throws } catch (err) { console.log('error:', err.message); // => error: cannot divide by zero } // always throw an error object (not a string) — it carries a message + stack. // ── 3. the error object & built-in error types ─────────────────────────────── const err = new error('something broke'); console.log(err.name); // => error console.log(err.message); // => something broke // err.stack contains the file/line trace (useful when debugging/logging). // built-in subtypes js throws automatically: // typeerror → wrong type (e.g. null.foo) // referenceerror → using an undeclared variable // syntaxerror → invalid code / bad json // rangeerror → value out of range (e.g. new array(-1)) try { null.foo; } catch (e) { console.log(e.name); // => typeerror } // ── 4. custom error classes — meaningful, catchable error types ────────────── class validationerror extends error { constructor(message, field) { super(message); this.name = 'validationerror'; this.field = field; // attach extra context } } function createuser(name) { if (!name) { throw new validationerror('name is required', 'name'); } return { name }; } try { createuser(''); } catch (err) { if (err instanceof validationerror) { console.log(`[${err.field}] ${err.message}`); // => [name] name is required } else { throw err; // not ours — re-throw so it isn't silently swallowed } } // ── 5. errors in async code ────────────────────────────────────────────────── async function fetchthing() { // in async functions, use plain try/catch around awaits: try { await promise.reject(new error('timeout')); } catch (err) { console.log('async caught:', err.message); // => async caught: timeout } } fetchthing(); // for raw promises, use .catch(): promise.reject(new error('boom')).catch((e) => console.log('promise caught:', e.message)); // ── 6. global \"last resort\" handlers ───────────────────────────────────────── // try/catch handles errors you expect. but something always slips through — an // unexpected throw, a promise with no .catch(). a global handler is your safety // net: log it (to a monitoring service — lesson 48) so you find out in prod. // // in the browser: // window.addeventlistener('error', (e) => { // report({ msg: e.message, file: e.filename, line: e.lineno }); // log it // }); // // a promise that rejects with nobody listening fires this instead: // window.addeventlistener('unhandledrejection', (e) => { // report({ msg: 'unhandled rejection', reason: e.reason }); // e.preventdefault(); // stops the default console error (optional) // }); // // in node (this part runs): process.on('unhandledrejection', (reason) => { console.log('global: unhandled rejection ->', reason?.message ?? reason); }); process.on('uncaughtexception', (err) => { console.log('global: uncaught exception ->', err.message); // a truly uncaught error left the app in an unknown state. best practice: // log, then exit and let a process manager restart you cleanly: // process.exit(1); }); // trigger the rejection handler on purpose (no .catch on this one): promise.reject(new error('nobody caught me')); // ⚠️ global handlers are a net, not a strategy — handle errors locally where you // can actually recover; let the global handler only log the ones that escape. /* best practices ------------------------------------------------------------- * • throw error objects, not strings. * • only catch errors you can meaningfully handle; re-throw the rest. * • don't leave an empty catch {} — at minimum, log it. * • use custom error classes so callers can react to specific failures. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. write parseage(str) that throws a rangeerror if the age is negative. * 2. create a notfounderror class and throw it from a lookup function. * 3. wrap a json.parse in try/catch and return a default object on failure. * 4. add a process.on('unhandledrejection', ...) and trigger it with a * promise.reject that has no .catch — confirm your handler logs it. * ------------------------------------------------------------------------- */"},"lessons/23-modules.js":{"title":"* 23 · modules — import / export","learn":"* • why we split code into modules (files) * • es modules (import/export) — the modern standard * • commonjs (require/module.exports) — node's older system * • dynamic import() — load a module on demand (code splitting) * * modules need multiple files to truly demonstrate, so the import/export * examples below are shown as comments — but there is a real, runnable pair * of files in lessons/modules-demo/ that you can run right now: * * node lessons/modules-demo/app.mjs # es modules (import/export) * node lessons/modules-demo/app.cjs # commonjs (require/exports) * * open those four files (math.mjs/app.mjs and math.cjs/app.cjs) alongside this * lesson. the self-contained demo at the bottom of this file just lets it run * on its own with `node lessons/23-modules.js`.","practice":"/* practice ------------------------------------------------------------------- * first, run the real demo and read its files: * node lessons/modules-demo/app.mjs * node lessons/modules-demo/app.cjs * then try these: * 1. add a `subtract` named export to modules-demo/math.mjs and import it * in app.mjs. re-run: node lessons/modules-demo/app.mjs * 2. change which function is the `default` export and update app.mjs. * 3. add a `multiply` export to math.cjs and use it from app.cjs. * 4. in app.mjs, load math.mjs with a dynamic `await import('./math.mjs')` * instead of a top-of-file import — log the returned namespace object. * 5. add a top-level `await` to math.mjs (e.g. `export const ready = * await promise.resolve(true);`), import `ready` in app.mjs, and confirm * it's already resolved when app.mjs runs. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 23 · modules — import / export * ============================================================================= * run: node lessons/23-modules.js (the runnable demo at the bottom) * * what you'll learn * • why we split code into modules (files) * • es modules (import/export) — the modern standard * • commonjs (require/module.exports) — node's older system * • dynamic import() — load a module on demand (code splitting) * * modules need multiple files to truly demonstrate, so the import/export * examples below are shown as comments — but there is a real, runnable pair * of files in lessons/modules-demo/ that you can run right now: * * node lessons/modules-demo/app.mjs # es modules (import/export) * node lessons/modules-demo/app.cjs # commonjs (require/exports) * * open those four files (math.mjs/app.mjs and math.cjs/app.cjs) alongside this * lesson. the self-contained demo at the bottom of this file just lets it run * on its own with `node lessons/23-modules.js`. * ========================================================================== */ /* ── 1. why modules? ───────────────────────────────────────────────────────── * one giant file is hard to navigate and reuse. modules let each file own one * job and explicitly share (export) only what others need (import). anything * not exported stays private to the file. */ /* ── 2. es modules (esm) — the modern standard ─────────────────────────────── * enable in node by adding \"type\": \"module\" to package.json, * or by naming files with the .mjs extension. in the browser, use * <script type=\"module\" src=\"app.js\"></script>. * * ---- file: math.js ---- * // named exports — export many values by name: * export const pi = 3.14159; * export function add(a, b) { return a + b; } * * // default export — one main value per file: * export default function multiply(a, b) { return a * b; } * * ---- file: app.js ---- * import multiply, { pi, add } from './math.js'; * // ^default ^named (names must match, braces required) * * import { add as sum } from './math.js'; // rename on import * import * as math from './math.js'; // grab everything as a namespace * console.log(math.pi, math.add(2, 3)); * * notes: * • import lines are hoisted and run first, before other code. * • paths are relative ('./') and must include the file extension (e.g. .js) in node esm. */ /* ── 3. commonjs (cjs) — node's original system ────────────────────────────── * the default in node when there's no \"type\": \"module\". you'll see this a lot * in existing node code. * * ---- file: math.cjs ---- * const pi = 3.14159; * function add(a, b) { return a + b; } * module.exports = { pi, add }; // export an object * * ---- file: app.cjs ---- * const { pi, add } = require('./math.cjs'); * const math = require('./math.cjs'); // or grab the whole object * * esm vs cjs quick map: * export default x ↔ module.exports = x * export { a, b } ↔ module.exports = { a, b } * import x from '…' ↔ const x = require('…') */ /* ── 3b. dynamic import() — load a module on demand ─────────────────────────── * the `import ... from` form is static: it runs at the top, always, before * anything else. `import()` is a function that returns a promise — so you can * load a module later, conditionally, or only when it's actually needed. * * button.addeventlistener('click', async () => { * const { renderchart } = await import('./chart.js'); // fetched only on click * renderchart(data); * }); * * why it matters — code splitting (lesson 42): * bundlers (lesson 45) split each dynamic import into its own file, so the * initial page ships less javascript and the heavy bits load on demand. * * other uses: * • conditional/lazy loading: if (isadmin) await import('./admin-panel.js'); * • load a commonjs module from esm: const cjs = await import('./old.cjs'); * • import() works even in plain <script> (no type=\"module\" required). * * it returns the module's namespace object (default export is `.default`): * const mod = await import('./math.js'); * mod.add(2, 3); mod.default(4, 5); // named + default */ // runnable taste of it: import a built-in node module dynamically. import('node:os').then((os) => { console.log('dynamic import → platform:', os.platform()); // e.g. 'linux' }); /* ── 3c. top-level await — `await` at module scope (es2022) ─────────────────── * inside an es module you can use `await` at the top level — no `async` * function wrapper needed. the module's own evaluation pauses until it resolves: * * // config.mjs * const res = await fetch('https://api.example.com/config'); * export const config = await res.json(); // ← awaited at top level * * // app.mjs — importing waits until config.mjs has finished awaiting: * import { config } from './config.mjs'; // `config` is already resolved * * why it matters: * • initialise things that need async work (config, db connection, a wasm * module) before the module's exports are usable — no half-ready exports. * • combine with dynamic import() to pick a module at load time: * const { strings } = await import(`./i18n/${navigator.language}.mjs`); * * caveats: * • esm only. it does not work in commonjs (.cjs) or in classic <script>; * needs type=\"module\" / a .mjs file / \"type\":\"module\" in package.json. * • a slow top-level await delays every module that imports this one, so keep * it for genuine startup work — not per-request logic. */ // runnable taste of it: static `import` and top-level `await` don't work in // commonjs, so we demo top-level await indirectly via a dynamic import() of an // esm data: url (the module awaits internally — and import() works in cjs *and* esm). import('data:text/javascript,export default await promise.resolve(42)') .then((m) => console.log('top-level await → default export:', m.default)); // => 42 // ── 4. runnable demo (no real imports needed) ──────────────────────────────── // this simulates a \"module\" as a self-contained object so the file still runs. const mathmodule = (() => { const pi = 3.14159; // \"private\" until exported const add = (a, b) => a + b; const multiply = (a, b) => a * b; return { pi, add, multiply }; // the file's \"exports\" })(); console.log('pi:', mathmodule.pi); // => 3.14159 console.log('add:', mathmodule.add(2, 3)); // => 5 console.log('multiply:', mathmodule.multiply(4, 5)); // => 20 /* practice ------------------------------------------------------------------- * first, run the real demo and read its files: * node lessons/modules-demo/app.mjs * node lessons/modules-demo/app.cjs * then try these: * 1. add a `subtract` named export to modules-demo/math.mjs and import it * in app.mjs. re-run: node lessons/modules-demo/app.mjs * 2. change which function is the `default` export and update app.mjs. * 3. add a `multiply` export to math.cjs and use it from app.cjs. * 4. in app.mjs, load math.mjs with a dynamic `await import('./math.mjs')` * instead of a top-of-file import — log the returned namespace object. * 5. add a top-level `await` to math.mjs (e.g. `export const ready = * await promise.resolve(true);`), import `ready` in app.mjs, and confirm * it's already resolved when app.mjs runs. * ------------------------------------------------------------------------- */"},"lessons/24-dom.js":{"title":"* 24 · the dom — document object model ⚠️ browser only","learn":"* • selecting elements * • reading/changing text, html, attributes, classes, and styles * • creating and removing elements","practice":"/* practice (in the browser) -------------------------------------------------- * 1. add a <ul id=\"list\"></ul> to index.html, then append 3 <li>s with js. * 2. select the <h1> and change its color and text. * 3. toggle a \"dark\" class on the <body> from the console. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 24 · the dom — document object model ⚠️ browser only * ============================================================================= * the dom is how js reads and changes the web page. it does not exist in node * (there's no page), so running this with `node` just prints a reminder. * * how to run this lesson: * 1. open index.html in the js-learn folder. * 2. change its script tag to: <script src=\"lessons/24-dom.js\"></script> * 3. open the browser, then open devtools (f12) → console tab. * * what you'll learn * • selecting elements * • reading/changing text, html, attributes, classes, and styles * • creating and removing elements * ========================================================================== */ // guard so this file is harmless when run in node: if (typeof document === 'undefined') { console.log('⚠️ this is a browser lesson. open it via index.html — see the header.'); } else { // ── 1. selecting elements ────────────────────────────────────────────────── // queryselector uses css selectors and returns the first match (or null). const title = document.queryselector('h1'); // by tag const box = document.queryselector('#box'); // by id (#) const items = document.queryselectorall('.item'); // all matches (a nodelist) // older, still-valid alternatives: // document.getelementbyid('box'); // document.getelementsbyclassname('item'); // ── 2. reading & changing content ────────────────────────────────────────── if (title) { console.log(title.textcontent); // read the text title.textcontent = 'updated by js!'; // change the text (safe — no html) title.innerhtml = 'now <em>italic</em>'; // parses html (⚠️ never with user input — xss risk) } // ── 3. attributes ────────────────────────────────────────────────────────── const link = document.queryselector('a'); if (link) { link.getattribute('href'); link.setattribute('target', '_blank'); link.href = 'https://example.com'; // many attributes are also properties } // ── 4. classes & styles ──────────────────────────────────────────────────── if (box) { box.classlist.add('active'); box.classlist.remove('hidden'); box.classlist.toggle('open'); // add if absent, remove if present box.classlist.contains('active'); // => true/false box.style.color = 'white'; box.style.backgroundcolor = 'navy'; // note: camelcase (background-color) } // ── 5. creating & inserting elements ─────────────────────────────────────── const list = document.queryselector('ul'); if (list) { const li = document.createelement('li'); // create (not yet on the page) li.textcontent = 'new item'; li.classlist.add('item'); list.appendchild(li); // add as the last child // list.prepend(li); // add as the first child // li.remove(); // remove an element } // ── 6. looping over a nodelist ───────────────────────────────────────────── items.foreach((item, i) => { item.textcontent = `item ${i + 1}`; }); } /* practice (in the browser) -------------------------------------------------- * 1. add a <ul id=\"list\"></ul> to index.html, then append 3 <li>s with js. * 2. select the <h1> and change its color and text. * 3. toggle a \"dark\" class on the <body> from the console. * ------------------------------------------------------------------------- */"},"lessons/25-events.js":{"title":"* 25 · events ⚠️ browser only","learn":"* • addeventlistener * • the event object (event.target, preventdefault) * • event bubbling and delegation * • common events (click, input, submit, keydown)","practice":"/* practice (in the browser) -------------------------------------------------- * 1. add a button that increments a counter shown in a <span>. * 2. add an input that live-updates an <h2> as you type. * 3. use delegation: one listener on a <ul> that strikes through any <li> * you click. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 25 · events ⚠️ browser only * ============================================================================= * events are how your page reacts to the user: clicks, typing, submitting forms, * scrolling, etc. like the dom lesson, this runs in a browser, not node. * * how to run: see lesson 24's header (open via index.html, check the console). * * what you'll learn * • addeventlistener * • the event object (event.target, preventdefault) * • event bubbling and delegation * • common events (click, input, submit, keydown) * ========================================================================== */ if (typeof document === 'undefined') { console.log('⚠️ this is a browser lesson. open it via index.html — see lesson 24.'); } else { // ── 1. addeventlistener — the standard way to respond to events ──────────── const button = document.queryselector('#mybutton'); if (button) { button.addeventlistener('click', (event) => { console.log('button clicked!'); console.log('clicked element:', event.target); // the element that fired it }); // you can attach many listeners to the same element — they all run. // remove one later with button.removeeventlistener('click', namedhandler). } // ── 2. the event object ──────────────────────────────────────────────────── const input = document.queryselector('#nameinput'); if (input) { // 'input' fires on every keystroke; event.target.value is the current text. input.addeventlistener('input', (event) => { console.log('typing:', event.target.value); }); } // ── 3. forms — preventdefault stops the page reload ──────────────────────── const form = document.queryselector('#myform'); if (form) { form.addeventlistener('submit', (event) => { event.preventdefault(); // stop the browser's default submit/reload const data = new formdata(form); console.log('form name field:', data.get('name')); }); } // ── 4. keyboard events ───────────────────────────────────────────────────── document.addeventlistener('keydown', (event) => { console.log('key pressed:', event.key); // e.g. \"enter\", \"a\", \"escape\" if (event.key === 'escape') console.log('escape pressed!'); }); // ── 5. bubbling & delegation ─────────────────────────────────────────────── // when you click a child, the event \"bubbles\" up through its ancestors. // delegation uses this: attach one listener to a parent instead of many to // each child — great for lists that change over time. const list = document.queryselector('#todolist'); if (list) { list.addeventlistener('click', (event) => { // did the click land on an <li>? (closest walks up to find a match) const li = event.target.closest('li'); if (li) { li.classlist.toggle('done'); console.log('toggled:', li.textcontent); } }); // now any <li> inside #todolist responds — even ones added later. } } /* common events -------------------------------------------------------------- * click, dblclick → mouse clicks * input, change → form field value changed * submit → form submitted (use preventdefault) * keydown, keyup → keyboard * mouseover, mouseout → hover * load, domcontentloaded → page/resources ready * --------------------------------------------------------------------------- */ /* practice (in the browser) -------------------------------------------------- * 1. add a button that increments a counter shown in a <span>. * 2. add an input that live-updates an <h2> as you type. * 3. use delegation: one listener on a <ul> that strikes through any <li> * you click. * ------------------------------------------------------------------------- */"},"lessons/26-fetch-apis.js":{"title":"* 26 · fetch & apis — talking to the internet","learn":"* • http fundamentals: methods, status codes, headers, rest * • fetch() — making http requests (get and post) * • working with json * • handling errors and http status codes * • retrying transient failures with backoff (retryable vs fatal) * • this ties together promises + async/await from lessons 19–20 * * `fetch` is built into modern browsers and node 18+. it returns a promise.","practice":"/* practice ------------------------------------------------------------------- * 1. fetch https://jsonplaceholder.typicode.com/users and log every name. * 2. fetch a single todo and log whether it's completed. * 3. add a check that logs a friendly message when response.ok is false * (try a url ending in /posts/99999999). * 4. log response.status and response.headers.get('content-type') for a get. * 5. send a delete to /posts/1 and log the status code you get back. * 6. use fetchretry() against a url that 500s a few times (or a fake fetch) * and log each attempt — confirm it backs off, then gives up or succeeds. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 26 · fetch & apis — talking to the internet * ============================================================================= * run: node lessons/26-fetch-apis.js (needs internet; node 18+ has fetch) * * what you'll learn * • http fundamentals: methods, status codes, headers, rest * • fetch() — making http requests (get and post) * • working with json * • handling errors and http status codes * • retrying transient failures with backoff (retryable vs fatal) * • this ties together promises + async/await from lessons 19–20 * * `fetch` is built into modern browsers and node 18+. it returns a promise. * ========================================================================== */ /* ── 0. http in 60 seconds — what fetch is actually doing ───────────────────── * every request is: a method + a url + headers (+ an optional body). the server * replies with a status code + headers + a body. know these and apis stop being * mysterious. * * methods (the \"verb\" — what you want to do): * get read data (no body) post create something (has a body) * put replace a whole resource patch update part of a resource * delete remove a resource * * status codes (grouped by first digit): * 2xx success → 200 ok, 201 created, 204 no content * 3xx redirect → 301 moved, 304 not modified (cached) * 4xx your fault → 400 bad request, 401 unauthorized, 403 forbidden, * 404 not found, 429 too many requests * 5xx server fault → 500 internal error, 502/503 upstream/unavailable * * common headers: * content-type: application/json → what the body is * accept: application/json → what you want back * authorization: bearer <token> → who you are (lesson 40) * * rest = a convention for designing urls around \"resources\" (nouns) + methods: * get /users list users post /users create a user * get /users/42 read user 42 patch /users/42 update user 42 * delete /users/42 delete user 42 * the same idea powers almost every api you'll call. */ // ── 1. json — the data format of the web ───────────────────────────────────── // apis send/receive text in json format. convert between js and json like so: const user = { name: 'sam', age: 25, hobbies: ['code', 'chess'] }; const json = json.stringify(user); // js object → json string console.log(json); // => {\"name\":\"sam\",\"age\":25,\"hobbies\":[\"code\",\"chess\"]} const parsed = json.parse(json); // json string → js object console.log(parsed.name); // => sam // pretty-print with indentation (handy for logging/debugging): console.log(json.stringify(user, null, 2)); // ── 1b. building urls with query strings (urlsearchparams) ─────────────────── // many get requests need a \"?key=value&key=value\" query string. don't glue it // by hand — urlsearchparams encodes spaces and special characters correctly. const params = new urlsearchparams({ q: 'iced coffee', page: 2, sort: 'new' }); console.log(params.tostring()); // => q=iced+coffee&page=2&sort=new const searchurl = `https://api.example.com/search?${params}`; console.log(searchurl); // => https://api.example.com/search?q=iced+coffee&page=2&sort=new // you'd then: await fetch(searchurl) // (urlsearchparams also parses query strings — see lesson 35.) // ── 2. a get request with async/await ──────────────────────────────────────── async function getpost(id) { // fetch returns a response. .json() reads & parses the body (also a promise). const response = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`); // ⚠️ fetch does not throw on 404/500 — you must check response.ok yourself. if (!response.ok) { throw new error(`http ${response.status} ${response.statustext}`); } const data = await response.json(); return data; } // ── 3. a post request — sending data ───────────────────────────────────────── async function createpost(post) { const response = await fetch('https://jsonplaceholder.typicode.com/posts', { method: 'post', headers: { 'content-type': 'application/json' }, body: json.stringify(post), // body must be a string }); return response.json(); } // ── 4. fetching several things in parallel ─────────────────────────────────── async function getmanyposts(ids) { // start all requests at once, then await them together (fast — see lesson 20). const requests = ids.map((id) => getpost(id)); return promise.all(requests); } // ── 4b. timeouts: give fetch a deadline with abortsignal (see lesson 30) ───── // fetch has no built-in timeout — a dead server could leave you hanging forever. // abortsignal.timeout(ms) auto-aborts the request after `ms`, rejecting with a // timeouterror you can catch. (older code uses an abortcontroller + settimeout.) async function getpostwithtimeout(id, ms) { const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, { signal: abortsignal.timeout(ms), // cancel the request if it takes longer than ms }); return res.json(); } // ── 4c. retrying transient failures with backoff ───────────────────────────── // not every failure is permanent. a 5xx (server), 429 (rate limited), or a // network blip is often transient — worth trying again. a 4xx like 400/401/404 // is your bug: retrying just hammers the server and still fails. so: retry only // the transient ones, waiting a little longer each time (backoff — lesson 30). const isretryable = (status) => status === 429 || status >= 500; async function fetchretry(url, { attempts = 3, ...options } = {}) { for (let i = 1; i <= attempts; i++) { try { const res = await fetch(url, options); if (res.ok) return res; // fatal status, or we're out of tries → stop and surface the error. if (!isretryable(res.status) || i === attempts) { throw new error(`http ${res.status} ${res.statustext}`); } } catch (err) { if (i === attempts) throw err; // network error on the final attempt → give up } await new promise((r) => settimeout(r, 2 ** (i - 1) * 100)); // 100ms, 200ms, 400ms… (prod: add random jitter) } } // usage: const res = await fetchretry('https://api.example.com/flaky', { attempts: 4 }); // ── 5. run it (with proper error handling) ─────────────────────────────────── (async () => { try { const post = await getpost(1); console.log('get post 1 title:', post.title); const created = await createpost({ title: 'hello', body: 'world', userid: 1 }); console.log('post created id:', created.id); // => 101 (this fake api echoes back) const many = await getmanyposts([1, 2, 3]); console.log('parallel fetched titles:', many.map((p) => p.title.slice(0, 15))); // a 1ms deadline is sure to fire, so this demonstrates the timeout path: try { await getpostwithtimeout(1, 1); } catch (err) { console.log('timeout demo:', err.name); // => timeout demo: timeouterror } // which failures fetchretry() would retry vs give up on (no network needed): console.log('retry 503?', isretryable(503), '| retry 404?', isretryable(404)); // => retry 503? true | retry 404? false } catch (err) { // network failure (e.g. offline) or a thrown http error lands here. console.log('request failed:', err.message); console.log('(if you are offline, that is expected — the code is correct.)'); } })(); /* the pattern to remember ---------------------------------------------------- * const res = await fetch(url, options); * if (!res.ok) throw new error(res.status); // fetch won't throw for you * const data = await res.json(); // parse the body * ... wrap the whole thing in try/catch. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. fetch https://jsonplaceholder.typicode.com/users and log every name. * 2. fetch a single todo and log whether it's completed. * 3. add a check that logs a friendly message when response.ok is false * (try a url ending in /posts/99999999). * 4. log response.status and response.headers.get('content-type') for a get. * 5. send a delete to /posts/1 and log the status code you get back. * 6. use fetchretry() against a url that 500s a few times (or a fake fetch) * and log each attempt — confirm it backs off, then gives up or succeeds. * ------------------------------------------------------------------------- */"},"lessons/27-regular-expressions.js":{"title":"* 27 · regular expressions (regex)","learn":"* • creating patterns and the common flags * • character classes, quantifiers, anchors, groups * • lookahead & lookbehind (match based on what's around) * • the modern flags: u (unicode), s (dotall), y (sticky), v (unicodesets) * • test / match / matchall / replace / split with regex * * a regex is a tiny pattern language for finding/validating/replacing text. * read each pattern's comment slowly — that's how regex \"clicks\".","practice":"/* practice ------------------------------------------------------------------- * 1. write a regex that matches a 10-digit phone number. * 2. extract all hashtags from \"love #js and #coding\" using matchall. * 3. replace every vowel in \"hello world\" with \"*\". * 4. use a lookbehind to grab the number after \"id=\" in \"?id=42&x=1\". * 5. use a negative lookahead to match \"cat\" only when not followed by \"alog\". * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 27 · regular expressions (regex) * ============================================================================= * run: node lessons/27-regular-expressions.js * * what you'll learn * • creating patterns and the common flags * • character classes, quantifiers, anchors, groups * • lookahead & lookbehind (match based on what's around) * • the modern flags: u (unicode), s (dotall), y (sticky), v (unicodesets) * • test / match / matchall / replace / split with regex * * a regex is a tiny pattern language for finding/validating/replacing text. * read each pattern's comment slowly — that's how regex \"clicks\". * ========================================================================== */ // ── 1. creating a regex ────────────────────────────────────────────────────── const literal = /cat/; // literal notation (preferred) const fromstring = new regexp('cat'); // when the pattern is dynamic/in a variable console.log(literal.test('a cat')); // => true (.test → does it match? boolean) console.log(fromstring.test('dog')); // => false // ── 2. flags (after the closing slash) ─────────────────────────────────────── // g → global (find all matches, not just the first) // i → case-insensitive // m → multiline (^ and $ match per line) console.log('cat cat cat'.match(/cat/gi)); // => [ 'cat', 'cat', 'cat' ] // ── 3. character classes — what kind of character ──────────────────────────── // \\d digit \\w word char (a-z a-z 0-9 _) \\s whitespace // \\d not-digit \\w not-word \\s not-space // . any char (except newline) // [abc] one of a/b/c [a-z] a range [^abc] not a/b/c console.log('order #42 ok'.match(/\\d+/)); // => [ '42', ... ] (\\d+ = one or more digits) console.log('a1 b2 c3'.match(/[a-c]\\d/g)); // => [ 'a1', 'b2', 'c3' ] // ── 4. quantifiers — how many ──────────────────────────────────────────────── // * zero or more + one or more ? zero or one (optional) // {3} exactly 3 {2,4} between 2-4 {2,} 2 or more console.log(/colou?r/.test('color')); // => true (the u is optional) console.log(/colou?r/.test('colour')); // => true console.log('aaa'.match(/a{2}/)); // => [ 'aa', ... ] // ── 5. anchors — position ──────────────────────────────────────────────────── // ^ start of string $ end of string \\b word boundary console.log(/^hello/.test('hello world')); // => true (starts with hello) console.log(/world$/.test('hello world')); // => true (ends with world) console.log(/\\bcat\\b/.test('the cat sat')); // => true (whole word \"cat\") console.log(/\\bcat\\b/.test('category')); // => false (cat is part of a word) // ── 6. groups & capturing ──────────────────────────────────────────────────── // ( ) captures part of the match so you can reuse it. const date = '2026-06-04'; const match = date.match(/(\\d{4})-(\\d{2})-(\\d{2})/); console.log(match[0]); // => 2026-06-04 (whole match) console.log(match[1]); // => 2026 (first group) console.log(match[2]); // => 06 (second group) // named groups are clearer: const named = date.match(/(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})/); console.log(named.groups.year, named.groups.month); // => 2026 06 // non-capturing group (?:...) — group for structure without creating a $1 slot: console.log('abcabc'.match(/(?:abc)+/)[0]); // => abcabc (grouped, not captured) // ── 6b. lookahead & lookbehind — match by context (not consumed) ────────────── // these assert what comes before/after without including it in the match. // (?=...) positive lookahead — followed by ... // (?!...) negative lookahead — not followed by ... // (?<=...) positive lookbehind — preceded by ... // (?<!...) negative lookbehind — not preceded by ... // get the number, but only when it's followed by \"px\" (the px isn't captured): console.log('width: 42px'.match(/\\d+(?=px)/)[0]); // => 42 // get the amount after a \"$\" (the $ isn't part of the match): console.log('total $59 now'.match(/(?<=\\$)\\d+/)[0]); // => 59 // negative lookahead — a word not followed by \"ing\": console.log('run runs running'.match(/run(?!ning)/g)); // => [ 'run', 'run' ] // classic use: add thousands separators by inserting commas at the right spots. console.log('1234567'.replace(/\\b(?=(\\d{3})+(?!\\d))/g, ',')); // => 1,234,567 // ── 6c. modern flags: u (unicode), s (dotall), y (sticky) ──────────────────── // u → full unicode mode. required for \\p{...} property escapes & astral chars. console.log(/\\p{emoji}/u.test('hi 👋')); // => true (match by unicode property) // ⚠️ \\p{emoji} also matches 0-9, # and * — for \"is this an emoji?\" prefer \\p{extended_pictographic}. console.log([...'a😀b'].length); // => 3 (spread is unicode-aware) // s → \"dotall\": let . match newlines too (by default it doesn't). console.log(/a.b/s.test('a\\nb')); // => true (without /s → false) // y → \"sticky\": match only at regex.lastindex, then advance it. great for // tokenizers/parsers that scan a string piece by piece. const sticky = /\\d+/y; sticky.lastindex = 5; console.log(sticky.exec('abc 123')[0]); // => 123 (matches starting at idx 5) // v → \"unicodesets\" (es2024): a smarter, stricter superset of u. it adds set // operations inside character classes and matches multi-codepoint graphemes. // • intersection [a&&b] — match chars in both sets: console.log('café'.replace(/[\\p{l}&&\\p{ascii}]/gu, '*')); // => \"****\" (u: can't and; && is literal → letters or ascii) console.log('café'.replace(/[\\p{l}&&\\p{ascii}]/gv, '*')); // => \"***é\" (v: letters and ascii → é kept, it's non-ascii) // • subtraction [a--b] — match chars in a but not b: console.log('café 123!'.replace(/[\\p{l}--[aeiou]]/gv, '*')); // => \"*a** 123!\" (letters except vowels) // • match a whole multi-codepoint grapheme via \\q{} string literals: console.log(/[\\q{👍🏽}]/v.test('👍🏽')); // => true (one class entry = a string) // rule of thumb: prefer /v over /u in new code when you use \\p{...} or classes. // ── 7. the string methods that take a regex ────────────────────────────────── // match — first match (or with /g, all matches as an array) console.log('cat bat hat'.match(/[cbh]at/g)); // => [ 'cat', 'bat', 'hat' ] // matchall — all matches with their groups (returns an iterator) for (const m of 'a1 b2'.matchall(/(\\w)(\\d)/g)) { console.log(m[1], m[2]); // => a 1 / b 2 } // replace — find & replace ($1 refers to a captured group) console.log('2026-06-04'.replace(/(\\d{4})-(\\d{2})-(\\d{2})/, '$3/$2/$1')); // => 04/06/2026 console.log('a b c d'.replace(/\\s+/g, ' ')); // => \"a b c d\" (collapse spaces) // split — split on a pattern console.log('a, b ,c , d'.split(/\\s*,\\s*/)); // => [ 'a', 'b', 'c', 'd' ] // ── 8. practical validators ────────────────────────────────────────────────── const isemail = (s) => /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(s); console.log(isemail('sam@example.com')); // => true console.log(isemail('not-an-email')); // => false // ⚠️ don't over-trust regex for emails/urls in production — but it's great for // quick format checks and pulling data out of text. /* cheat sheet ---------------------------------------------------------------- * \\d \\w \\s digit / word / space ^ $ \\b start / end / boundary * * + ? many / 1+ / optional {n} {n,m} exact / range counts * [abc] [^abc] one-of / none-of ( ) capture (?<name> ) named * (?:..) non-capturing group (?=) (?!) lookahead pos/neg * (?<=) (?<!) lookbehind pos/neg \\p{...} unicode property (needs u) * flags: g (all) i (ignore case) m (multiline) s (dot matches \\n) * u (unicode) y (sticky — match at lastindex only) d (match indices) * v (unicodesets — superset of u: set ops [a&&b]/[a--b] & \\q{} strings) * tip: build & test patterns at regex101.com — it explains every token. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. write a regex that matches a 10-digit phone number. * 2. extract all hashtags from \"love #js and #coding\" using matchall. * 3. replace every vowel in \"hello world\" with \"*\". * 4. use a lookbehind to grab the number after \"id=\" in \"?id=42&x=1\". * 5. use a negative lookahead to match \"cat\" only when not followed by \"alog\". * ------------------------------------------------------------------------- */"},"lessons/28-generators-iterators.js":{"title":"* 28 · generators & iterators","learn":"* • the iterator protocol (what makes something \"for...of\"-able) * • generator functions (function*) and yield * • lazy / infinite sequences * • making your own objects iterable with symbol.iterator","practice":"/* practice ------------------------------------------------------------------- * 1. write a generator fibonacci() and take the first 10 numbers. * 2. make an object { from, to } iterable so [...it] counts from→to. * 3. write a generator that yields only the even numbers of an array. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 28 · generators & iterators * ============================================================================= * run: node lessons/28-generators-iterators.js * * what you'll learn * • the iterator protocol (what makes something \"for...of\"-able) * • generator functions (function*) and yield * • lazy / infinite sequences * • making your own objects iterable with symbol.iterator * ========================================================================== */ // ── 1. the iterator protocol ───────────────────────────────────────────────── // an \"iterator\" is any object with a .next() that returns { value, done }. // arrays, strings, sets, maps are \"iterable\" because they can produce one. const arr = [10, 20]; const it = arr[symbol.iterator](); // get the array's iterator console.log(it.next()); // => { value: 10, done: false } console.log(it.next()); // => { value: 20, done: false } console.log(it.next()); // => { value: undefined, done: true } // ── 2. generator functions — the easy way to make iterators ────────────────── // function* + yield. calling it does not run the body — it returns a generator. // each .next() runs until the next yield, then pauses there. function* counttothree() { yield 1; yield 2; yield 3; } const gen = counttothree(); console.log(gen.next()); // => { value: 1, done: false } console.log(gen.next()); // => { value: 2, done: false } console.log(gen.next()); // => { value: 3, done: false } console.log(gen.next()); // => { value: undefined, done: true } // generators are iterable, so for...of and spread just work: console.log([...counttothree()]); // => [ 1, 2, 3 ] for (const n of counttothree()) console.log('got', n); // => 1, 2, 3 // ── 3. generators keep state between yields ────────────────────────────────── function* idmaker() { let id = 1; while (true) { // an \"infinite\" generator — safe because it's lazy yield id++; } } const ids = idmaker(); console.log(ids.next().value); // => 1 console.log(ids.next().value); // => 2 console.log(ids.next().value); // => 3 // it only computes the next value when you ask — never runs forever. // ── 4. lazy sequences — compute only what you need ─────────────────────────── function* take(iterable, n) { let count = 0; for (const item of iterable) { if (count++ >= n) return; yield item; } } function* naturals() { let i = 1; while (true) yield i++; } console.log([...take(naturals(), 5)]); // => [ 1, 2, 3, 4, 5 ] (from an infinite source!) // ── 5. yield* — delegate to another generator/iterable ─────────────────────── function* letters() { yield 'a'; yield 'b'; } function* combined() { yield* letters(); // yield everything from letters() yield* [1, 2]; // yield* works on any iterable } console.log([...combined()]); // => [ 'a', 'b', 1, 2 ] // ── 6. make your own object iterable ───────────────────────────────────────── // add a [symbol.iterator] method (a generator is the simplest way). const range = { start: 1, end: 5, *[symbol.iterator]() { for (let i = this.start; i <= this.end; i++) yield i; }, }; console.log([...range]); // => [ 1, 2, 3, 4, 5 ] for (const n of range) process.stdout.write(n + ' '); // => 1 2 3 4 5 console.log(); /* why use generators? -------------------------------------------------------- * • represent infinite or huge sequences without storing them all in memory. * • produce values lazily, on demand. * • write custom iteration for your own data structures cleanly. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. write a generator fibonacci() and take the first 10 numbers. * 2. make an object { from, to } iterable so [...it] counts from→to. * 3. write a generator that yields only the even numbers of an array. * ------------------------------------------------------------------------- */"},"lessons/29-symbols-proxy-reflect.js":{"title":"* 29 · symbols, proxy & reflect (metaprogramming)","learn":"* • symbol — unique, hidden-ish keys * • proxy — intercept operations on an object (get/set/has/delete...) * • reflect — the standard helpers proxy traps delegate to * * this is \"metaprogramming\": code that customizes how objects behave. * you won't use it daily, but libraries (vue, mobx) are built on it.","practice":"/* practice ------------------------------------------------------------------- * 1. create two symbols with the same description and prove they differ. * 2. build a proxy that makes an object read-only (set throws). * 3. use reflect.ownkeys to list every key (including symbols) of an object. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 29 · symbols, proxy & reflect (metaprogramming) * ============================================================================= * run: node lessons/29-symbols-proxy-reflect.js * * what you'll learn * • symbol — unique, hidden-ish keys * • proxy — intercept operations on an object (get/set/has/delete...) * • reflect — the standard helpers proxy traps delegate to * * this is \"metaprogramming\": code that customizes how objects behave. * you won't use it daily, but libraries (vue, mobx) are built on it. * ========================================================================== */ // ── 1. symbols — guaranteed-unique values ──────────────────────────────────── const a = symbol('id'); // the 'id' is just a description (for debugging) const b = symbol('id'); console.log(a === b); // => false (every symbol is unique, even same desc) console.log(a.tostring());// => symbol(id) // use as object keys that won't collide with normal string keys: const id = symbol('id'); const user = { name: 'sam', [id]: 12345 }; console.log(user[id]); // => 12345 console.log(object.keys(user)); // => [ 'name' ] (symbol keys are skipped here) console.log(user.name); // normal keys still work as usual // well-known symbols let you hook into language behavior (lesson 28 used // symbol.iterator). another example — customize tostring tagging: const widget = { [symbol.tostringtag]: 'widget' }; console.log(object.prototype.tostring.call(widget)); // => [object widget] // ── 2. proxy — wrap an object and intercept operations ─────────────────────── // a proxy sits in front of a \"target\" and runs your \"traps\" on access. const target = { message: 'hello' }; const logged = new proxy(target, { get(obj, prop) { console.log(`(read ${string(prop)})`); return obj[prop]; }, set(obj, prop, value) { console.log(`(write ${string(prop)} = ${value})`); obj[prop] = value; return true; // set traps must return true on success }, }); logged.message; // => (read message) logged.message = 'hi'; // => (write message = hi) console.log(target.message); // => hi (the real object was updated) // ── 3. proxy use-case: validation ──────────────────────────────────────────── function createvalidateduser() { return new proxy({}, { set(obj, prop, value) { if (prop === 'age' && (typeof value !== 'number' || value < 0)) { throw new typeerror('age must be a non-negative number'); } obj[prop] = value; return true; }, }); } const person = createvalidateduser(); person.age = 30; console.log(person.age); // => 30 try { person.age = -5; // blocked by the trap } catch (e) { console.log('blocked:', e.message); // => blocked: age must be a non-negative number } // ── 4. proxy use-case: default values for missing keys ─────────────────────── const withdefault = new proxy({}, { get: (obj, prop) => (prop in obj ? obj[prop] : `<no ${string(prop)}>`), }); withdefault.name = 'ana'; console.log(withdefault.name); // => ana console.log(withdefault.email);// => <no email> (instead of undefined) // ── 5. reflect — the \"default behaviors\" as functions ──────────────────────── // reflect mirrors the proxy traps. inside a trap, delegate to reflect so you // keep the standard behavior while adding your own logic on top. const obj = { x: 1 }; console.log(reflect.get(obj, 'x')); // => 1 (same as obj.x) reflect.set(obj, 'y', 2); // same as obj.y = 2 console.log(reflect.has(obj, 'y')); // => true (same as 'y' in obj) console.log(reflect.ownkeys(obj)); // => [ 'x', 'y' ] // idiomatic proxy using reflect (forwards everything, logs reads): const clean = new proxy({ score: 9 }, { get(t, p, r) { console.log(`accessed ${string(p)}`); return reflect.get(t, p, r); // default get, no manual t[p] }, }); console.log(clean.score); // => accessed score / 9 /* when do you use this? ------------------------------------------------------ * • symbol: unique keys, hooking into iteration/string-tagging. * • proxy + reflect: reactive state (vue 3), observable objects, validation, * logging, virtualized/lazy objects, api mocking. * • for everyday app code you rarely need these — but knowing they exist * explains how \"magic\" libraries work. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. create two symbols with the same description and prove they differ. * 2. build a proxy that makes an object read-only (set throws). * 3. use reflect.ownkeys to list every key (including symbols) of an object. * ------------------------------------------------------------------------- */"},"lessons/30-advanced-async.js":{"title":"* 30 · advanced async","learn":"* • microtasks vs macrotasks (the real event-loop order) * • async iteration: for await...of and async generators * • abortcontroller — cancelling async work * • debounce & throttle — controlling how often a function runs * • retry with backoff, and concurrency limiting (a \"pool\") * * builds on lessons 19–20. these are the patterns senior devs reach for.","practice":"/* practice ------------------------------------------------------------------- * 1. predict the log order of a sync log, a settimeout(0), and a promise.then. * 2. write an async generator that yields 1..n with a small delay each. * 3. wrap a debounce around a function and call it rapidly — watch it fire once. * 4. use maplimit to \"fetch\" 10 fake urls 3 at a time; log when each starts. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 30 · advanced async * ============================================================================= * run: node lessons/30-advanced-async.js * * what you'll learn * • microtasks vs macrotasks (the real event-loop order) * • async iteration: for await...of and async generators * • abortcontroller — cancelling async work * • debounce & throttle — controlling how often a function runs * • retry with backoff, and concurrency limiting (a \"pool\") * * builds on lessons 19–20. these are the patterns senior devs reach for. * ========================================================================== */ const delay = (ms, v) => new promise((r) => settimeout(() => r(v), ms)); // ── 1. microtasks vs macrotasks (event-loop ordering) ──────────────────────── // after the current synchronous code finishes, the engine drains all // microtasks (promise callbacks) before the next macrotask (settimeout). console.log('a: sync'); settimeout(() => console.log('d: settimeout (macrotask)'), 0); promise.resolve().then(() => console.log('c: promise (microtask)')); console.log('b: sync'); // order: a, b, c, d → promises always jump ahead of settimeout. // ── 2. async generators + for await...of ───────────────────────────────────── // a generator that yields promises. for await...of awaits each one in turn. async function* fetchpages() { for (let page = 1; page <= 3; page++) { const data = await delay(20, `page ${page} data`); // pretend network call yield data; } } async function readpages() { for await (const page of fetchpages()) { console.log('received:', page); // => received: page 1 data, ... 2, ... 3 } } // ── 3. abortcontroller — cancel async work ─────────────────────────────────── // the standard way to cancel fetches, timers, or any awaitable. function cancellabledelay(ms, signal) { return new promise((resolve, reject) => { const id = settimeout(resolve, ms); signal.addeventlistener('abort', () => { cleartimeout(id); reject(new error('aborted')); }); }); } async function abortdemo() { const controller = new abortcontroller(); settimeout(() => controller.abort(), 30); // cancel after 30ms try { await cancellabledelay(1000, controller.signal); // would take 1s console.log('completed'); // never reached } catch (err) { console.log('abort demo:', err.message); // => abort demo: aborted } // real fetch supports this directly: fetch(url, { signal: controller.signal }) } // ── 4. debounce — run only after activity stops ────────────────────────────── // \"wait until the user stops typing for 300ms, then search.\" resets on each call. function debounce(fn, wait) { let timer; return function (...args) { cleartimeout(timer); timer = settimeout(() => fn.apply(this, args), wait); }; } // ── 5. throttle — run at most once per interval ────────────────────────────── // \"no matter how often this fires (scroll/resize), run at most once per 200ms.\" function throttle(fn, interval) { let last = 0; return function (...args) { const now = date.now(); if (now - last >= interval) { last = now; fn.apply(this, args); } // (a production throttle often also schedules a trailing call; omitted here) }; } // debounce → \"settle then act\" (search box). throttle → \"steady rate\" (scroll). // ── 6. retry with backoff — a real-world async pattern ─────────────────────── async function withretry(task, attempts = 3) { for (let i = 1; i <= attempts; i++) { try { return await task(); } catch (err) { if (i === attempts) throw err; // out of tries → give up await delay(10 * i); // wait longer each time (backoff; prod adds jitter) console.log(`retry ${i} after failure: ${err.message}`); } } } // ── 7. concurrency limiting — a \"pool\" of n at a time ──────────────────────── // promise.all (lesson 20) starts everything at once. with 1,000 urls that can // overwhelm the server (or your rate limit). a pool runs at most `limit` tasks // concurrently: as each finishes, the next starts. keeps results in order. async function maplimit(items, limit, task) { const results = new array(items.length); let next = 0; async function worker() { while (next < items.length) { const i = next++; // claim the next index results[i] = await task(items[i], i); } } // start `limit` workers; they pull from the shared queue until it's empty const pool = array.from({ length: math.min(limit, items.length) }, worker); await promise.all(pool); return results; } // ── 8. run the demos ───────────────────────────────────────────────────────── (async () => { await readpages(); await abortdemo(); let flaky = 0; const result = await withretry(async () => { flaky++; if (flaky < 3) throw new error(`fail #${flaky}`); return 'success on attempt 3'; }); console.log(result); // => success on attempt 3 // concurrency demo: 6 tasks, only 2 run at a time → finishes in ~3 \"waves\". let active = 0, peak = 0; const out = await maplimit([1, 2, 3, 4, 5, 6], 2, async (n) => { active++; peak = math.max(peak, active); await delay(20); active--; return n * 10; }); console.log('maplimit result:', out); // => [10,20,30,40,50,60] (in order) console.log('maplimit peak concurrency:', peak); // => 2 (never more than the limit) // debounce demo: 5 rapid calls → fn runs once, with the last argument. const search = debounce((q) => console.log('searching for:', q), 50); ['a', 'ap', 'app', 'appl', 'apple'].foreach((q) => search(q)); // => searching for: apple (only once, after the burst settles) })(); /* practice ------------------------------------------------------------------- * 1. predict the log order of a sync log, a settimeout(0), and a promise.then. * 2. write an async generator that yields 1..n with a small delay each. * 3. wrap a debounce around a function and call it rapidly — watch it fire once. * 4. use maplimit to \"fetch\" 10 fake urls 3 at a time; log when each starts. * ------------------------------------------------------------------------- */"},"lessons/31-functional-programming.js":{"title":"* 31 · functional programming","learn":"* • pure functions & immutability * • higher-order functions * • currying & partial application * • function composition (pipe / compose) * * fp is a style: build programs from small, predictable functions that don't * change shared state. it makes code easier to test and reason about.","practice":"/* practice ------------------------------------------------------------------- * 1. rewrite a loop that mutates an array as a pure map/filter chain. * 2. curry a function divide(a)(b) and make a halve = divide-by-2 helper. * 3. use pipe to: trim → lowercase → replace spaces with \"-\" on a string. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 31 · functional programming * ============================================================================= * run: node lessons/31-functional-programming.js * * what you'll learn * • pure functions & immutability * • higher-order functions * • currying & partial application * • function composition (pipe / compose) * * fp is a style: build programs from small, predictable functions that don't * change shared state. it makes code easier to test and reason about. * ========================================================================== */ // ── 1. pure functions ──────────────────────────────────────────────────────── // a pure function: (1) same input → same output, (2) no side effects. const addpure = (a, b) => a + b; // ✅ pure console.log(addpure(2, 3)); // => 5 (always) let total = 0; const addimpure = (n) => (total += n); // ❌ impure — mutates outside state addimpure(5); console.log(total); // => 5 (depends on history; harder to test) // ── 2. immutability — don't mutate, return new data ────────────────────────── const nums = [1, 2, 3]; // ❌ mutating: // nums.push(4); nums.sort(); // ✅ immutable: produce new arrays/objects instead const added = [...nums, 4]; // => [1,2,3,4], nums untouched const doubled = nums.map((n) => n * 2); // => [2,4,6] const sorted = [...nums].sort((a, b) => b - a); // copy before sort console.log(nums, added, doubled, sorted); // => [1,2,3] [1,2,3,4] [2,4,6] [3,2,1] const user = { name: 'sam', age: 25 }; const older = { ...user, age: 26 }; // new object, original unchanged console.log(user.age, older.age); // => 25 26 // ── 3. higher-order functions (take or return functions) ───────────────────── // map/filter/reduce are hofs (lesson 13). you can write your own: const withlogging = (fn) => (...args) => { console.log(`calling with ${args}`); return fn(...args); }; const loggedadd = withlogging(addpure); console.log(loggedadd(4, 5)); // => calling with 4,5 / 9 // ── 4. currying — turn f(a, b, c) into f(a)(b)(c) ──────────────────────────── // lets you \"fix\" arguments one at a time and build specialized functions. const multiply = (a) => (b) => a * b; console.log(multiply(3)(4)); // => 12 const triple = multiply(3); // pre-fill the first argument console.log(triple(10)); // => 30 // a generic curry helper: function curry(fn) { return function curried(...args) { if (args.length >= fn.length) return fn(...args); return (...more) => curried(...args, ...more); }; } const sum3 = curry((a, b, c) => a + b + c); console.log(sum3(1)(2)(3)); // => 6 console.log(sum3(1, 2)(3)); // => 6 console.log(sum3(1)(2, 3)); // => 6 // ── 5. partial application — pre-fill some arguments ───────────────────────── const greet = (greeting, name) => `${greeting}, ${name}!`; const sayhello = greet.bind(null, 'hello'); // fix the first arg console.log(sayhello('ana')); // => hello, ana! // ── 6. composition — pipe data through a series of functions ───────────────── // pipe: left → right (read top to bottom). compose: right → left (math style). const pipe = (...fns) => (input) => fns.reduce((acc, fn) => fn(acc), input); const compose = (...fns) => (input) => fns.reduceright((acc, fn) => fn(acc), input); const inc = (n) => n + 1; const double = (n) => n * 2; const square = (n) => n * n; const transform = pipe(inc, double, square); // ((n+1)*2)^2 console.log(transform(3)); // => 64 (3→4→8→64) const transform2 = compose(square, double, inc); // same result, reversed order console.log(transform2(3)); // => 64 // ── 7. putting it together (declarative data pipeline) ─────────────────────── const orders = [ { item: 'pen', price: 5, qty: 3 }, { item: 'pad', price: 8, qty: 2 }, { item: 'ink', price: 12, qty: 1 }, ]; const grandtotal = orders .map((o) => o.price * o.qty) // line totals: [15, 16, 12] .filter((t) => t >= 13) // keep big lines: [15, 16] (drops the 12) .reduce((sum, t) => sum + t, 0); console.log(grandtotal); // => 31 /* why fp? -------------------------------------------------------------------- * • pure + immutable = predictable, easy to test, fewer \"spooky\" bugs. * • small composable functions read like a recipe. * • you don't have to go 100% fp — adopting purity & immutability where it * helps already makes most codebases cleaner. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. rewrite a loop that mutates an array as a pure map/filter chain. * 2. curry a function divide(a)(b) and make a halve = divide-by-2 helper. * 3. use pipe to: trim → lowercase → replace spaces with \"-\" on a string. * ------------------------------------------------------------------------- */"},"lessons/32-tricky-concepts.js":{"title":"* 32 · tricky concepts & interview gotchas","learn":"* • the classic puzzles that trip up everyone (and show up in interviews) * • why each one behaves the way it does * * for each: read the setup, guess the output, then check the // => comment. * understanding the \"why\" means you've truly understood the language.","practice":"/* practice ------------------------------------------------------------------- * 1. fix a \"3,3,3\" var loop two ways: with let, and with an iife closure. * 2. explain out loud why [] == ![] is true, token by token. * 3. write a function that safely copies before mutating its array argument. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 32 · tricky concepts & interview gotchas * ============================================================================= * run: node lessons/32-tricky-concepts.js * * what you'll learn * • the classic puzzles that trip up everyone (and show up in interviews) * • why each one behaves the way it does * * for each: read the setup, guess the output, then check the // => comment. * understanding the \"why\" means you've truly understood the language. * ========================================================================== */ // ── 1. var in a loop with settimeout (the #1 classic) ──────────────────────── // var is function-scoped: all callbacks share one i, which is 3 by the time // they run. let is block-scoped: each iteration gets its own i. console.log('--- var vs let in loops ---'); for (var i = 0; i < 3; i++) { settimeout(() => console.log('var i =', i), 0); // => 3, 3, 3 } for (let j = 0; j < 3; j++) { settimeout(() => console.log('let j =', j), 10); // => 0, 1, 2 } // ── 2. hoisting: function declarations vs expressions ──────────────────────── console.log('--- hoisting ---'); console.log(declared()); // => \"i work!\" (declarations hoist fully) function declared() { return 'i work!'; } try { expressed(); // ❌ typeerror: expressed is not a function } catch (e) { console.log('expression:', e.constructor.name); // => typeerror } var expressed = function () { return 'nope'; }; // var = undefined when called above // ── 3. reference equality ──────────────────────────────────────────────────── console.log('--- reference vs value ---'); console.log({} === {}); // => false (two different objects) console.log([] === []); // => false const x = {}; const y = x; console.log(x === y); // => true (same reference) console.log(0.1 + 0.2 === 0.3); // => false (floating point — lesson 06) // ── 4. == coercion landmines (why we use ===) ──────────────────────────────── console.log('--- loose equality ---'); console.log([] == ![]); // => true 😱 (![] is false → [] == false → '' == 0 → true) console.log(null == undefined); // => true console.log(null == 0); // => false (null only loosely equals undefined) console.log(nan === nan); // => false (use number.isnan instead) // ── 5. this depends on the call site ───────────────────────────────────────── console.log('--- this binding ---'); const obj = { name: 'sam', regular() { return this?.name; }, // `this` is whatever is to the left of the dot }; console.log(obj.regular()); // => sam (obj.method() → this = obj) const detached = obj.regular; console.log(detached()); // => undefined (plain call → no object, no this) // arrow functions have no own `this`; they capture it from the surrounding scope. // that makes them the wrong choice for a method that needs to reach its object: const witharrow = { name: 'sam', get: () => this?.name }; console.log(witharrow.get()); // => undefined (arrow's `this` is not witharrow) // ── 6. array holes & common surprises ──────────────────────────────────────── console.log('--- array quirks ---'); console.log(typeof nan); // => number (nan is a number!) console.log([1, 2, 3].map(string)); // => [ '1', '2', '3' ] console.log(['1', '7', '11'].sort()); // => [ '1', '11', '7' ] (string sort!) console.log([1, 7, 11].sort((a, b) => a - b)); // => [ 1, 7, 11 ] (numeric sort) console.log(parseint('08')); // => 8 (but always pass a radix:) console.log(parseint('08', 10)); // => 8 (radix 10 — never trust the default) // ── 7. closures capturing a shared variable ────────────────────────────────── console.log('--- closure capture ---'); function makefns() { const fns = []; for (let k = 0; k < 3; k++) fns.push(() => k); // let → each captures its own k return fns; } console.log(makefns().map((f) => f())); // => [ 0, 1, 2 ] // (with var k, this would be [3, 3, 3] — same trap as #1.) // ── 8. object key coercion ─────────────────────────────────────────────────── console.log('--- object keys are strings ---'); const o = {}; o[1] = 'number one'; o['1'] = 'string one'; // same key — keys are coerced to strings console.log(o[1]); // => string one (the second write won) console.log(object.keys(o));// => [ '1' ] (only one key) // ── 9. truthy/falsy in conditions ──────────────────────────────────────────── console.log('--- truthy/falsy ---'); if ([]) console.log('empty array is truthy'); // prints (empty array → truthy) if ('0') console.log('\"0\" string is truthy'); // prints (non-empty string) if (!0) console.log('0 is falsy'); // prints // the 8 falsy values: false, 0, -0, 0n, \"\", null, undefined, nan. else → truthy. // ── 10. the mutation-by-reference bug ──────────────────────────────────────── console.log('--- shared reference bug ---'); function additem(item, list = []) { list.push(item); return list; } console.log(additem('a')); // => [ 'a' ] console.log(additem('b')); // => [ 'b' ] (default param is fresh each call — safe) // ⚠️ but a shared outer array would accumulate: const shared = []; const buggy = (item) => { shared.push(item); return shared; }; buggy('x'); buggy('y'); console.log(shared); // => [ 'x', 'y' ] (mutated across calls — often a bug) /* interview tips ------------------------------------------------------------- * • always prefer let/const over var (kills the loop-closure trap). * • always use === ; reserve == only for `== null` (catches null+undefined). * • remember: this is set by how a function is called, not where it's defined. * • objects/arrays are passed by reference — copy before mutating. * • know the 8 falsy values cold. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. fix a \"3,3,3\" var loop two ways: with let, and with an iife closure. * 2. explain out loud why [] == ![] is true, token by token. * 3. write a function that safely copies before mutating its array argument. * ------------------------------------------------------------------------- */"},"lessons/33-dates-time.js":{"title":"* 33 · dates & time","learn":"* • creating date objects * • reading & changing parts of a date * • timestamps and date math (durations) * • formatting dates for humans with intl.datetimeformat * * note: date is quirky (months are 0-based!). read the comments carefully.","practice":"/* practice ------------------------------------------------------------------- * 1. log today's date as \"weekday, month day, year\" using intl. * 2. compute how many days until a target date. * 3. build a function adddays(date, n) that returns a new date n days later. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 33 · dates & time * ============================================================================= * run: node lessons/33-dates-time.js * * what you'll learn * • creating date objects * • reading & changing parts of a date * • timestamps and date math (durations) * • formatting dates for humans with intl.datetimeformat * * note: date is quirky (months are 0-based!). read the comments carefully. * ========================================================================== */ // ── 1. creating dates ──────────────────────────────────────────────────────── const now = new date(); // current date & time const fromiso = new date('2026-06-04'); // from an iso string (recommended format) const fromparts = new date(2026, 5, 4); // ⚠️ month is 0-based! 5 = june const fromstamp = new date(0); // from a timestamp (ms since 1970-01-01 utc) console.log(fromiso.toisostring()); // => 2026-06-04t00:00:00.000z console.log(fromparts.getfullyear(), fromparts.getmonth()); // => 2026 5 (june) console.log(fromstamp.toisostring()); // => 1970-01-01t00:00:00.000z // ── 2. reading parts of a date ─────────────────────────────────────────────── const d = new date('2026-06-04t09:30:00'); console.log(d.getfullyear()); // => 2026 console.log(d.getmonth()); // => 5 (0=jan … 5=jun — add 1 for humans) console.log(d.getdate()); // => 4 (day of month, 1-based) console.log(d.getday()); // => 4 (day of week, 0=sun … 4=thu) console.log(d.gethours(), d.getminutes()); // => 9 30 // utc variants exist too: getutcfullyear(), getutchours(), ... // ── 3. timestamps & \"now\" ──────────────────────────────────────────────────── const ms = date.now(); // milliseconds since 1970 (an integer) console.log(typeof ms); // => number console.log(d.gettime()); // => the timestamp of date d // timestamps make dates easy to compare and subtract. // ── 4. date math — durations ───────────────────────────────────────────────── const start = new date('2026-06-01'); const end = new date('2026-06-04'); const diffms = end - start; // subtracting dates → milliseconds const diffdays = diffms / (1000 * 60 * 60 * 24); console.log(diffdays); // => 3 // add time by working in ms (or with setdate): const tomorrow = new date(start); tomorrow.setdate(start.getdate() + 1); // setdate handles month rollovers console.log(tomorrow.toisostring().slice(0, 10)); // => 2026-06-02 // a reusable \"days between\" helper: const daysbetween = (a, b) => math.round((b - a) / 86_400_000); console.log(daysbetween(start, end)); // => 3 // ── 5. formatting for humans — intl.datetimeformat (the modern way) ────────── const date = new date('2026-06-04t15:05:00'); console.log(new intl.datetimeformat('en-us').format(date)); // => 6/4/2026 console.log(new intl.datetimeformat('en-gb').format(date)); // => 04/06/2026 const long = new intl.datetimeformat('en-us', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', }); console.log(long.format(date)); // => thursday, june 4, 2026 const withtime = new intl.datetimeformat('en-us', { hour: '2-digit', minute: '2-digit', hour12: true, // set hour12 so am/pm isn't locale-dependent }); console.log(withtime.format(date)); // => 03:05 pm // quick built-ins (less control, but easy): console.log(date.todatestring()); // => thu jun 04 2026 console.log(date.tolocaledatestring());// => locale-specific short date // ── 6. \"time ago\" — a common real-world function ───────────────────────────── function timeago(date, from) { const seconds = math.floor((from - date) / 1000); const units = [ ['year', 31536000], ['month', 2592000], ['day', 86400], ['hour', 3600], ['minute', 60], ['second', 1], ]; for (const [name, secs] of units) { const value = math.floor(seconds / secs); if (value >= 1) return `${value} ${name}${value > 1 ? 's' : ''} ago`; } return 'just now'; } const past = new date('2026-06-01t12:00:00'); const reference = new date('2026-06-04t12:00:00'); console.log(timeago(past, reference)); // => 3 days ago /* gotchas -------------------------------------------------------------------- * • months are 0-based (january = 0). days of month are 1-based. confusing! * • always prefer iso strings ('2026-06-04') — other formats are ambiguous. * • a date is just a utc timestamp shown in your local zone. a date-only string * '2026-06-04' parses as utc midnight, but a date-time string with no offset * ('2026-06-04t09:30') parses as local time — a classic footgun. * • for heavy date work, libraries like date-fns or day.js save headaches. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. log today's date as \"weekday, month day, year\" using intl. * 2. compute how many days until a target date. * 3. build a function adddays(date, n) that returns a new date n days later. * ------------------------------------------------------------------------- */"},"lessons/34-browser-storage.js":{"title":"* 34 · browser storage ⚠️ mostly browser","learn":"* • localstorage vs sessionstorage vs cookies — when to use each * • storing & reading data (it's always strings → use json) * • a typical \"save/load app state\" pattern * * localstorage doesn't exist in node, so this file runs a tiny in-memory * stand-in when needed, and shows the real browser api in comments.","practice":"/* practice ------------------------------------------------------------------- * 1. save a to-do array to storage, reload it, and add one item. * 2. build loadtheme()/savetheme() that default to 'light' when unset. * 3. in the browser, make a counter that survives page refreshes. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 34 · browser storage ⚠️ mostly browser * ============================================================================= * run: node lessons/34-browser-storage.js (runs a node-safe simulation) * or load via index.html to use real localstorage in the browser. * * what you'll learn * • localstorage vs sessionstorage vs cookies — when to use each * • storing & reading data (it's always strings → use json) * • a typical \"save/load app state\" pattern * * localstorage doesn't exist in node, so this file runs a tiny in-memory * stand-in when needed, and shows the real browser api in comments. * ========================================================================== */ // ── 0. get a storage object (real in browser, simulated in node) ───────────── const storage = typeof localstorage !== 'undefined' ? localstorage : (() => { // minimal in-memory mock so the lesson runs in node: const map = new map(); return { setitem: (k, v) => map.set(k, string(v)), getitem: (k) => (map.has(k) ? map.get(k) : null), removeitem: (k) => map.delete(k), clear: () => map.clear(), }; })(); // ── 1. the basics: setitem / getitem / removeitem ──────────────────────────── // ⚠️ storage only holds strings. numbers/booleans get converted to strings. storage.setitem('username', 'sam'); console.log(storage.getitem('username')); // => sam console.log(storage.getitem('missing')); // => null (not undefined!) storage.setitem('count', 5); console.log(typeof storage.getitem('count')); // => string (\"5\", not 5!) // ── 2. storing objects/arrays → json.stringify on the way in, parse on out ─── const user = { name: 'ana', theme: 'dark', favorites: ['js', 'css'] }; storage.setitem('user', json.stringify(user)); // object → string const loaded = json.parse(storage.getitem('user')); // string → object console.log(loaded.favorites); // => [ 'js', 'css' ] // ── 3. a safe save/load helper (handles missing keys & bad json) ───────────── function save(key, value) { storage.setitem(key, json.stringify(value)); } function load(key, fallback = null) { const raw = storage.getitem(key); if (raw === null) return fallback; try { return json.parse(raw); } catch { return fallback; // corrupted data → return the default instead of crashing } } save('settings', { volume: 0.8, muted: false }); console.log(load('settings')); // => { volume: 0.8, muted: false } console.log(load('nothing', 'default')); // => default // ── 4. removing & clearing ─────────────────────────────────────────────────── storage.removeitem('count'); // delete one key console.log(storage.getitem('count')); // => null // storage.clear(); // ⚠️ wipes everything for this site /* ── 5. localstorage vs sessionstorage vs cookies ──────────────────────────── * * localstorage → persists forever (until cleared). same api as above. * use for: theme, settings, draft content, cached data. * * sessionstorage → cleared when the tab closes. identical api: * sessionstorage.setitem('k', 'v') * use for: one-visit state, multi-step form progress. * * cookies → small (~4kb), sent to the server on every request. * read/write the raw string: * document.cookie = 'token=abc; max-age=3600; path=/'; * document.cookie // \"token=abc; other=...\" * use for: auth tokens / things the server must see. * (for real apps, set auth cookies from the server as * httponly so js can't read them — safer.) * * limits: localstorage/sessionstorage ~5mb, synchronous, strings only, * per-origin (one site can't read another's storage). */ /* ── 6. real browser example (uncomment when loaded via index.html) ────────── * // persist a counter across page reloads: * const n = number(localstorage.getitem('visits') || 0) + 1; * localstorage.setitem('visits', n); * console.log(`you've visited ${n} times`); */ /* practice ------------------------------------------------------------------- * 1. save a to-do array to storage, reload it, and add one item. * 2. build loadtheme()/savetheme() that default to 'light' when unset. * 3. in the browser, make a counter that survives page refreshes. * ------------------------------------------------------------------------- */"},"lessons/35-bom-timers.js":{"title":"* 35 · bom & timers (the browser object model)","learn":"* • settimeout / setinterval and how to cancel them * • the bom: window, location, history, navigator, screen * • a practical countdown timer pattern * * the dom (lessons 24–25) is the page. the bom is the browser around it — * the window, the url, history, the device. timers work everywhere.","practice":"/* practice ------------------------------------------------------------------- * 1. build a clock that logs the time every second, then stops after 5. * 2. parse \"?theme=dark&lang=en\" with urlsearchparams and read both values. * 3. (browser) log location.pathname and navigator.language in the console. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 35 · bom & timers (the browser object model) * ============================================================================= * run: node lessons/35-bom-timers.js (timers run; bom parts are shown safely) * * what you'll learn * • settimeout / setinterval and how to cancel them * • the bom: window, location, history, navigator, screen * • a practical countdown timer pattern * * the dom (lessons 24–25) is the page. the bom is the browser around it — * the window, the url, history, the device. timers work everywhere. * ========================================================================== */ // ── 1. settimeout — run once after a delay ─────────────────────────────────── const id = settimeout(() => { console.log('runs after 50ms'); }, 50); // cancel it before it fires with cleartimeout(id): // cleartimeout(id); // ── 2. setinterval — run repeatedly every n ms ─────────────────────────────── let ticks = 0; const intervalid = setinterval(() => { ticks++; console.log('tick', ticks); if (ticks >= 3) { clearinterval(intervalid); // ⚠️ always stop intervals or they run forever console.log('interval stopped'); } }, 20); // ── 3. a practical countdown ───────────────────────────────────────────────── function countdown(from, ontick, ondone) { let n = from; const t = setinterval(() => { ontick(n); if (n === 0) { clearinterval(t); ondone(); } n--; }, 15); return t; } countdown(3, (n) => console.log(`t-minus ${n}`), () => console.log('🚀 liftoff')); // ── 4. settimeout(0) — defer work to \"after the current code\" ──────────────── // not actually 0ms — it runs after the current synchronous code & microtasks. console.log('sync 1'); settimeout(() => console.log('deferred (macrotask)'), 0); console.log('sync 2'); // logs before \"deferred\" — see lesson 30's event loop /* ── 5. the bom objects (browser only — shown as comments) ─────────────────── * * window — the global object in browsers. window.x === x at top level. * window.innerwidth / innerheight → viewport size * window.alert() / confirm() / prompt() → dialog boxes * window.scrollto(0, 0) → scroll the page * * location — the current url (read and navigate): * location.href // \"https://site.com/page?q=1#top\" * location.pathname // \"/page\" * location.search // \"?q=1\" * location.hash // \"#top\" * location.href = 'https://example.com' // navigate to a new page * location.reload() // refresh * * history — the back/forward stack: * history.back(); history.forward(); history.go(-2); * history.pushstate({}, '', '/new-url'); // change url, no reload (spas) * * navigator — info about the browser/device: * navigator.language // \"en-us\" * navigator.online // true / false * navigator.clipboard.writetext('copied!') * navigator.geolocation.getcurrentposition(...) * * screen — the physical display: screen.width, screen.height */ // ── 6. reading query params (works in browser; demo'd with url here) ───────── // in a browser you'd use: new urlsearchparams(location.search) const params = new urlsearchparams('?user=sam&page=2'); console.log(params.get('user')); // => sam console.log(params.get('page')); // => 2 console.log([...params]); // => [ [ 'user', 'sam' ], [ 'page', '2' ] ] /* globalthis — the global object everywhere ----------------------------------- * in browsers the global is `window`; in node it's `global`. `globalthis` * works in both, so portable code uses it. */ console.log(typeof globalthis); // => object /* practice ------------------------------------------------------------------- * 1. build a clock that logs the time every second, then stops after 5. * 2. parse \"?theme=dark&lang=en\" with urlsearchparams and read both values. * 3. (browser) log location.pathname and navigator.language in the console. * ------------------------------------------------------------------------- */"},"lessons/36-debugging-console.js":{"title":"* 36 · debugging & the console","learn":"* • the console methods beyond console.log * • reading error messages & stack traces * • the `debugger` statement and breakpoints * • a practical debugging mindset * * debugging is half of programming. knowing your tools turns \"why won't this * work?!\" into a calm, 2-minute investigation.","practice":"/* practice ------------------------------------------------------------------- * 1. use console.table to print an array of 3 product objects. * 2. trigger a \"cannot read properties of undefined\" on purpose, then fix it * with optional chaining. * 3. wrap a slow loop in console.time/timeend and read the duration. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 36 · debugging & the console * ============================================================================= * run: node lessons/36-debugging-console.js * * what you'll learn * • the console methods beyond console.log * • reading error messages & stack traces * • the `debugger` statement and breakpoints * • a practical debugging mindset * * debugging is half of programming. knowing your tools turns \"why won't this * work?!\" into a calm, 2-minute investigation. * ========================================================================== */ // ── 1. beyond console.log — the full console toolkit ───────────────────────── console.log('plain message'); console.info('ℹ️ informational'); console.warn('⚠️ a warning (yellow in browsers)'); console.error('❌ an error (red — does not stop the program)'); // console.table — gorgeous for arrays of objects: console.table([ { name: 'ana', age: 25 }, { name: 'bob', age: 30 }, ]); // grouping related logs (indented; collapsible in the browser): console.group('user load'); console.log('fetching...'); console.log('done'); console.groupend(); // counting how many times a line runs: console.count('loop'); // => loop: 1 console.count('loop'); // => loop: 2 // timing how long something takes: console.time('work'); let sum = 0; for (let i = 0; i < 1e6; i++) sum += i; console.timeend('work'); // => work: 1.2ms (your number will vary) // assertions — log only if the condition is false (great for sanity checks): console.assert(sum > 0, 'sum should be positive'); // (prints nothing — it passed) // ── 2. the log-the-label trick (see which variable is which) ───────────────── const x = 5, y = 10; // wrap variables in an object → labels come for free: console.log({ x, y }); // => { x: 5, y: 10 } (clearer than console.log(x, y)) // ── 3. reading a stack trace ───────────────────────────────────────────────── function level3() { throw new error('something failed deep down'); } function level2() { level3(); } function level1() { level2(); } try { level1(); } catch (err) { console.log('message:', err.message); // => something failed deep down // err.stack lists the call path innermost-first: where it threw, then its callers. console.log('first stack line:', err.stack.split('\\n')[1].trim()); // the first line of err.stack is the error message; the next line (the first // `at …` frame — index 1 above) is where it actually threw, then its callers. } // ── 4. the `debugger` statement & breakpoints ──────────────────────────────── // drop `debugger;` into your code. when devtools (browser) or an inspector // (node --inspect) is open, execution pauses there so you can inspect variables // step by step. it's ignored when no debugger is attached. function buggyaverage(nums) { // debugger; // ← uncomment, run `node --inspect-brk` or use vs code's debugger const total = nums.reduce((a, b) => a + b, 0); return total / nums.length; } console.log(buggyaverage([2, 4, 6])); // => 4 /* ── 5. a debugging mindset (more useful than any tool) ────────────────────── * 1. reproduce it reliably — know the exact steps that trigger the bug. * 2. read the full error message + the first line of the stack trace. * 3. isolate: log values right before the failing line. what's unexpected? * 4. check assumptions: log the type too — console.log(typeof x, x). * (most bugs are \"i thought this was a number but it's a string/undefined.\") * 5. narrow it down: comment out half, see if the bug remains. repeat. * 6. fix the cause, not the symptom. then re-run to confirm. * * common error messages, decoded: * \"x is not defined\" → typo, or used before declaring (tdz). * \"cannot read properties of → you accessed .foo on null/undefined. * undefined (reading 'foo')\" log the object first; use ?. (lesson 03). * \"x is not a function\" → it's not what you think (typo, or undefined). * \"unexpected token\" → a syntax error (missing }, ), or comma). */ /* practice ------------------------------------------------------------------- * 1. use console.table to print an array of 3 product objects. * 2. trigger a \"cannot read properties of undefined\" on purpose, then fix it * with optional chaining. * 3. wrap a slow loop in console.time/timeend and read the duration. * ------------------------------------------------------------------------- */"},"lessons/37-weakmap-memory.js":{"title":"* 37 · weakmap, memory & final language details","learn":"* • how js memory & garbage collection work (the short version) * • weakmap / weakset and why \"weak\" matters * • weakref & finalizationregistry (advanced gc hooks) * • strict mode * • tagged template literals * * the last few pieces to round out your javascript knowledge.","practice":"/* practice ------------------------------------------------------------------- * 1. use a weakmap to cache a computed result keyed by an object argument. * 2. add 'use strict' to a function and trigger an accidental-global error. * 3. write a tag function that uppercases every interpolated value. * 4. wrap an object in a weakref, log .deref()?.x, then set the original to * null and explain why .deref() might (eventually) return undefined. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 37 · weakmap, memory & final language details * ============================================================================= * run: node lessons/37-weakmap-memory.js * * what you'll learn * • how js memory & garbage collection work (the short version) * • weakmap / weakset and why \"weak\" matters * • weakref & finalizationregistry (advanced gc hooks) * • strict mode * • tagged template literals * * the last few pieces to round out your javascript knowledge. * ========================================================================== */ // ── 1. garbage collection in 60 seconds ────────────────────────────────────── // js manages memory for you. an object stays in memory as long as something // can still reach it (a variable, an array, a property...). when nothing // references it anymore, the garbage collector frees it automatically. let data = { big: 'lots of stuff' }; data = null; // the object is now unreachable → eligible to be cleaned up // you don't free memory manually — but you can cause \"leaks\" by holding // references you forgot about (e.g. an ever-growing array, or listeners you // never remove). the fix is usually: stop referencing what you're done with. // ── 2. map vs weakmap ──────────────────────────────────────────────────────── // a normal map holds its keys strongly — they can never be garbage-collected // while the map exists. a weakmap holds keys weakly: if the key object is no // longer referenced anywhere else, it (and its value) can be cleaned up. const weak = new weakmap(); let user = { name: 'sam' }; weak.set(user, { lastlogin: '2026-06-04' }); // associate metadata with an object console.log(weak.get(user)); // => { lastlogin: '2026-06-04' } console.log(weak.has(user)); // => true user = null; // now nothing else references the user object → // the weakmap entry becomes eligible for garbage collection. // restrictions (the price of being \"weak\"): // • keys must be objects (not strings/numbers). // • not iterable — no .size, no for...of, no .keys(). you can't list entries. // use cases: attach private/extra data to objects without preventing their // cleanup — caches, metadata, \"have i processed this object?\" tracking. // ── 3. weakset — same idea, for a set of objects ───────────────────────────── const seen = new weakset(); let task = { id: 1 }; seen.add(task); console.log(seen.has(task)); // => true task = null; // entry can be garbage-collected; you don't have to clean up // great for \"have i already handled this object?\" without leaking memory. // ── 3b. weakref & finalizationregistry (advanced — use rarely) ─────────────── // a weakref holds a reference that does not keep its target alive: the gc may // still collect the object. call .deref() to get it back — or `undefined` if // it's already been collected. useful for memory-sensitive caches. let cached = { data: 'expensive to compute' }; const ref = new weakref(cached); console.log(ref.deref()?.data); // => expensive to compute (still alive here) // after `cached = null` and a gc cycle, ref.deref() would return undefined. // ⚠️ you can't predict when the gc runs, so never rely on timing. // a finalizationregistry lets you register a cleanup callback that may run after // an object is collected — e.g. to release an external resource tied to it. const registry = new finalizationregistry((heldvalue) => { console.log('cleanup ran for:', heldvalue); // may fire later, or never }); registry.register(cached, 'cache-entry-1'); // associate a label with the object // ⚠️ finalizers are not guaranteed to run (e.g. on exit) and timing is // unpredictable. treat them as a best-effort safety net, never your main logic. // rule of thumb: prefer weakmap/weakset; reach for weakref/finalizationregistry // only for genuine memory caches or wrapping external (c/wasm) resources. // ── 4. strict mode ─────────────────────────────────────────────────────────── // 'use strict' opts into a safer js: it turns silent mistakes into errors. // es modules (lesson 23) and class bodies are always strict automatically. function sloppyvsstrict() { 'use strict'; // mistyped = 5; // ❌ in strict mode: referenceerror (without it: silently // // creates a global — a classic hard-to-find bug!) return 'strict mode catches accidental globals & other footguns'; } console.log(sloppyvsstrict()); // strict mode also: forbids duplicate params, makes `this` undefined in plain // function calls (lesson 11), and disallows deleting variables. prefer it // (you get it free with modules/classes). // ── 5. tagged template literals ────────────────────────────────────────────── // a function placed before a template literal receives the string pieces and // the interpolated values separately — letting you process them. function highlight(strings, ...values) { // strings: the text chunks; values: the ${...} results return strings.reduce( (out, str, i) => out + str + (i < values.length ? `[${values[i]}]` : ''), '' ); } const name = 'sam'; const score = 95; console.log(highlight`user ${name} scored ${score} points`); // => user [sam] scored [95] points // real-world tags: styled-components (css-in-js), string.raw, safe html/sql // escaping, i18n. string.raw is a built-in tag that ignores escape sequences: console.log(string.raw`c:\\new\\test`); // => c:\\new\\test (\\n not a newline) /* memory-leak avoidance tips ------------------------------------------------- * • remove event listeners when you're done (removeeventlistener). * • clear timers you no longer need (clearinterval / cleartimeout). * • don't let global arrays/objects grow forever — cap or clear them. * • use weakmap/weakset when associating data with objects you don't own. * --------------------------------------------------------------------------- */ /* 🎉 that's the whole core language — basics, intermediate, advanced, and the * browser. from here the course shifts gears: * • part 10 (38) — modern js (es2021–es2026) * • part 11 (39–47) — professional & production engineering * • part 12 (48–56) — computer-science core (data structures, * algorithms, binary data) + specialist topics * a great next step right now: build a small app (to-do, weather, quiz) * using lessons 24–26 + 33. building is what makes it all stick. */ /* practice ------------------------------------------------------------------- * 1. use a weakmap to cache a computed result keyed by an object argument. * 2. add 'use strict' to a function and trigger an accidental-global error. * 3. write a tag function that uppercases every interpolated value. * 4. wrap an object in a weakref, log .deref()?.x, then set the original to * null and explain why .deref() might (eventually) return undefined. * ------------------------------------------------------------------------- */"},"lessons/38-modern-js.js":{"title":"* 38 · modern javascript (es2021 → es2026)","learn":"* the newest, genuinely useful additions to javascript — grouped by year. * these make a lot of older patterns cleaner. several replace workarounds * you saw earlier in the course (noted with \"↪ replaces ...\"). * * note: very new features need an up-to-date runtime. everything here runs in * node 22/24 and current browsers (2024+). older environments may not * support the es2024/es2025 items yet.","practice":"/* practice ------------------------------------------------------------------- * 1. rewrite lesson 13's letter-counting reduce using object.groupby. * 2. replace a [...arr].sort() somewhere in your code with arr.tosorted(). * 3. use set.intersection to find common items in two arrays of tags. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 38 · modern javascript (es2021 → es2026) * ============================================================================= * run: node lessons/38-modern-js.js (needs node 22+ ; you have v24 ✅) * * (heads-up: node prints a harmless \"module_typeless_package_json\" warning — * this file is an es module and package.json has no \"type\" on purpose. ignore it.) * * what you'll learn * the newest, genuinely useful additions to javascript — grouped by year. * these make a lot of older patterns cleaner. several replace workarounds * you saw earlier in the course (noted with \"↪ replaces ...\"). * * note: very new features need an up-to-date runtime. everything here runs in * node 22/24 and current browsers (2024+). older environments may not * support the es2024/es2025 items yet. * ========================================================================== */ console.log('===== es2021 ====='); // ── logical assignment: ??= ||= &&= ──────────────────────────────────────── // combine a logical check with assignment. super handy for defaults. let config = { theme: null, retries: 0 }; config.theme ??= 'light'; // assign only if null/undefined → 'light' config.retries ||= 3; // assign if falsy (0 counts!) → 3 config.theme &&= 'dark'; // assign only if already truthy → 'dark' console.log(config); // => { theme: 'dark', retries: 3 } // ↪ replaces: if (config.theme == null) config.theme = 'light' // ── promise.any — first to succeed wins ────────────────────────────────────── // (vs promise.race which settles on the first to finish, success or fail) const fastest = await promise.any([ promise.reject('server a down'), promise.resolve('server b responded'), ]); console.log(fastest); // => server b responded console.log('===== es2022 ====='); // ── top-level await ────────────────────────────────────────────────────────── // in es modules you can `await` at the top level — no async iife wrapper. // (this file uses it; that's why awaits above work without an async function.) const ready = await promise.resolve('no iife needed'); console.log(ready); // => no iife needed // ── object.hasown(obj, key) — the safe \"has own property\" check ────────────── const obj = { a: 1 }; console.log(object.hasown(obj, 'a')); // => true console.log(object.hasown(obj, 'tostring')); // => false (inherited, not own) // ↪ replaces the clunky: object.prototype.hasownproperty.call(obj, 'a') // ── error cause — chain errors without losing the original ─────────────────── try { try { throw new error('low-level network fail'); } catch (original) { throw new error('could not load user', { cause: original }); } } catch (err) { console.log(err.message, '| caused by:', err.cause.message); // => could not load user | caused by: low-level network fail } console.log('===== es2023 ====='); // ── findlast / findlastindex — search from the end ─────────────────────────── const nums = [1, 2, 3, 4, 5]; console.log(nums.findlast((n) => n % 2 === 1)); // => 5 (last odd) console.log(nums.findlastindex((n) => n % 2 === 1)); // => 4 // ── immutable array methods — return a new array, no mutation ⭐ ────────────── // these are the modern fix for the \"copy-before-sort\" dance from lessons 12/13. const original = [3, 1, 2]; console.log(original.tosorted((a, b) => a - b)); // => [1, 2, 3] console.log(original.toreversed()); // => [2, 1, 3] console.log(original.with(0, 99)); // => [99, 1, 2] (replace index 0) console.log(original.tospliced(1, 1)); // => [3, 2] (remove 1 at idx 1) console.log(original); // => [3, 1, 2] unchanged ✅ // ↪ replaces: [...arr].sort(...) and [...arr].reverse() console.log('===== es2024 ====='); // ── object.groupby — group array items by a key ⭐ ─────────────────────────── const people = [ { name: 'ana', dept: 'eng' }, { name: 'bob', dept: 'sales' }, { name: 'cy', dept: 'eng' }, ]; const bydept = object.groupby(people, (p) => p.dept); console.log(bydept.eng.map((p) => p.name)); // => [ 'ana', 'cy' ] // ↪ replaces a whole reduce() into an object (you wrote one in lesson 13!) // map.groupby is the same, but returns a map (keys can be any type): const byparity = map.groupby([1, 2, 3, 4], (n) => (n % 2 ? 'odd' : 'even')); console.log(byparity.get('odd')); // => [ 1, 3 ] // ── promise.withresolvers — get a promise + its resolve/reject together ────── // cleaner than capturing them inside the executor with outer `let`s. const { promise, resolve } = promise.withresolvers(); settimeout(() => resolve('done!'), 10); console.log(await promise); // => done! // ── array.fromasync — build an array from an async iterable ────────────────── async function* drip() { yield 1; yield 2; yield 3; } console.log(await array.fromasync(drip())); // => [ 1, 2, 3 ] console.log('===== es2025 (newest) ====='); // ── iterator helpers — map/filter/take lazily, without arrays ⭐ ────────────── // you can now chain methods directly on iterators (e.g. from .values(), // generators, map/set entries) — processed lazily, one item at a time. function* naturals() { let i = 1; while (true) yield i++; } const firstthreeevens = naturals() .filter((n) => n % 2 === 0) .map((n) => n * 10) .take(3) // stop after 3 — works on an infinite source .toarray(); console.log(firstthreeevens); // => [ 20, 40, 60 ] // ↪ before, .map/.filter only existed on arrays (you had to materialize first) // ── new set methods — real set algebra ⭐ ──────────────────────────────────── const a = new set([1, 2, 3, 4]); const b = new set([3, 4, 5, 6]); console.log([...a.union(b)]); // => [ 1, 2, 3, 4, 5, 6 ] console.log([...a.intersection(b)]); // => [ 3, 4 ] console.log([...a.difference(b)]); // => [ 1, 2 ] console.log([...a.symmetricdifference(b)]);// => [ 1, 2, 5, 6 ] console.log(new set([1, 2]).issubsetof(a));// => true // ── promise.try — run a function and always get a promise back ──────────────── // wraps sync or async functions uniformly; sync throws become rejections. const result = await promise.try(() => 42); console.log(result); // => 42 // ── regexp.escape — safely put arbitrary text into a regex ─────────────────── const userinput = 'a.b*c'; const safe = new regexp(regexp.escape(userinput)); // dots/stars treated literally console.log(safe.test('a.b*c')); // => true console.log(safe.test('axbyc')); // => false (the . and * are not wildcards now) console.log('===== es2026 & the cutting edge ====='); // ── using / await using — automatic cleanup (explicit resource management) ──── // a `using` declaration auto-calls the resource's [symbol.dispose]() when the // block ends — like try/finally, but automatic. `await using` calls the async // [symbol.asyncdispose](). perfect for files, db connections, locks, sockets. // (stage 3 / es2026; needs a very recent runtime. shown so you recognize it.) // // function openresource(name) { // return { [symbol.dispose]() { console.log(`closing ${name}`); } }; // } // { // using db = openresource('db'); // no manual close needed // using file = openresource('file'); // // ...use them... // } // ← here both are disposed automatically, in reverse order // // ↪ replaces the try { } finally { db.close(); file.close(); } dance. // ── import attributes — import non-js modules safely ───────────────────────── // tell the engine what kind of module you're importing (currently json): // import config from './config.json' with { type: 'json' }; // const data = await import('./data.json', { with: { type: 'json' } }); // ↪ replaces reading + json.parse-ing a file by hand for static config. // ── decorators — annotate classes/methods with @reusable behavior ───────────── // a decorator is a function that wraps a class/method to add behavior (logging, // validation, memoization) declaratively. (stage 3; typescript/angular already // use them; frameworks lean on them heavily.) // // function logged(originalmethod, ctx) { // return function (...args) { // console.log(`calling ${ctx.name}`); // return originalmethod.call(this, ...args); // }; // } // class api { @logged getuser(id) { /* ... */ } } // @logged wraps the method // ↪ a standardized version of the \"decorator\" pattern from lesson 41. // ── float16array & math.f16round — half-precision numbers (es2025/26) ───────── // 16-bit floats: half the memory, enough precision for ml weights, graphics, // and gpu data. a typed array (lesson 51) for compact decimal data. if (typeof float16array !== 'undefined') { const half = new float16array([1.5, 2.25]); console.log('float16array:', half[0]); // => 1.5 } else { console.log('float16array: not in this runtime yet (very new)'); } console.log('===== on the horizon ====='); /* ── temporal api — the modern replacement for date (not shipped yet) ───────── * date is famously awkward (0-based months, mutable, no time-zone clarity). * temporal fixes all of it. it's at stage 3 and not yet in node/most browsers, * so this is shown as a comment. use the @js-temporal/polyfill package to try it. * * const today = temporal.now.plaindateiso(); // 2026-06-04 (immutable) * const next = today.add({ days: 7 }); // clean date math * const meeting = temporal.zoneddatetime.from('2026-06-04t15:00[asia/kolkata]'); * today.month // 6 (1-based — finally sane!) * today.until(next).days // 7 * * until it ships, use lesson 33's date + intl, or a library (date-fns, day.js). */ console.log('temporal: coming soon — see comments. for now use lesson 33.'); /* what changed for your everyday code ---------------------------------------- * • sorting without mutating ......... arr.tosorted() (was [...arr].sort()) * • grouping data .................... object.groupby(...) (was a reduce) * • defaults ......................... x ??= value * • own-property check ............... object.hasown(o, k) * • lazy pipelines ................... iterator.map().filter().take() * • set math ......................... a.union(b), a.intersection(b) * these are all \"nice to have\" — the fundamentals you already learned still * work everywhere. reach for these when your runtime supports them. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. rewrite lesson 13's letter-counting reduce using object.groupby. * 2. replace a [...arr].sort() somewhere in your code with arr.tosorted(). * 3. use set.intersection to find common items in two arrays of tags. * ------------------------------------------------------------------------- */"},"lessons/39-testing.js":{"title":"* 39 · testing — proving your code works","learn":"* • why we write automated tests * • node's built-in test runner (node:test) + assert — zero install * • unit tests, grouping, async tests, and mocking * • the testing pyramid: unit → integration → end-to-end (e2e) * • code coverage * • the tdd loop (red → green → refactor) * * node 18+ ships a real test runner. the same ideas map 1:1 onto jest/vitest * (describe/it/expect) — only the import and matcher names differ.","practice":"/* practice ------------------------------------------------------------------- * 1. write a test for a `capitalize(str)` function (first letter upper). * 2. test that it throws (or returns '') on an empty string. * 3. mock a `logger` and assert it was called with the right message. * 4. run this file with --experimental-test-coverage and read the report. * 5. sketch (in comments) one unit, one integration, and one e2e test for a * login feature — note what each would and wouldn't catch. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 39 · testing — proving your code works * ============================================================================= * run: node --test lessons/39-testing.js (or just: node lessons/39-testing.js) * * (heads-up: node prints a harmless \"module_typeless_package_json\" warning — * this file is an es module and package.json has no \"type\" on purpose. ignore it.) * * what you'll learn * • why we write automated tests * • node's built-in test runner (node:test) + assert — zero install * • unit tests, grouping, async tests, and mocking * • the testing pyramid: unit → integration → end-to-end (e2e) * • code coverage * • the tdd loop (red → green → refactor) * * node 18+ ships a real test runner. the same ideas map 1:1 onto jest/vitest * (describe/it/expect) — only the import and matcher names differ. * ========================================================================== */ import { test, describe, mock, before, after } from 'node:test'; import assert from 'node:assert/strict'; // \"strict\" = uses === by default // ── the code we want to test (normally this lives in another file) ─────────── function add(a, b) { return a + b; } function divide(a, b) { if (b === 0) throw new error('cannot divide by zero'); return a / b; } async function fetchuser(id) { // pretend this hits a network; resolves after a tick return { id, name: 'sam' }; } // ── 1. a single unit test ──────────────────────────────────────────────────── test('add() sums two numbers', () => { assert.equal(add(2, 3), 5); // pass: 2 + 3 === 5 assert.notequal(add(2, 3), 6); }); // ── 2. grouping related tests with describe ────────────────────────────────── describe('divide()', () => { test('divides normally', () => { assert.equal(divide(10, 2), 5); }); test('throws on divide-by-zero', () => { // assert.throws checks that the function does throw (and the message matches) assert.throws(() => divide(1, 0), /cannot divide by zero/); }); }); // ── 3. common assertions ───────────────────────────────────────────────────── test('assertion styles', () => { assert.ok(1 < 2); // truthy check assert.equal('a', 'a'); // === for primitives assert.deepequal({ a: 1 }, { a: 1 }); // structural equality for objects assert.deepequal([1, 2], [1, 2]); // ...and arrays }); // ── 4. async tests — just make the test function async and await ───────────── test('fetchuser() resolves with a user', async () => { const user = await fetchuser(7); assert.equal(user.id, 7); assert.equal(user.name, 'sam'); }); // assert.rejects is the async cousin of assert.throws — it awaits a rejection: test('loaduser() rejects on a bad id', async () => { async function loaduser(id) { if (id < 0) throw new error('invalid id'); return { id }; } await assert.rejects(() => loaduser(-1), /invalid id/); // passes: it rejected as expected }); // ── 5. mocking — replace a real dependency with a fake you control ─────────── describe('mocking', () => { test('mock.fn records calls and returns what you tell it', () => { const sendemail = mock.fn(() => 'sent'); // fake function function notify(send, to) { return send(`hello ${to}`); } const result = notify(sendemail, 'ana@example.com'); assert.equal(result, 'sent'); assert.equal(sendemail.mock.callcount(), 1); // called once assert.equal(sendemail.mock.calls[0].arguments[0], 'hello ana@example.com'); }); }); // ── 6. setup / teardown hooks ──────────────────────────────────────────────── describe('hooks (before/after)', () => { let db; before(() => { db = { rows: [] }; }); // runs once before the tests below after(() => { db = null; }); // cleanup after test('starts empty', () => { assert.equal(db.rows.length, 0); }); }); /* ── 7. the testing pyramid — unit / integration / e2e ─────────────────────── * different tests catch different bugs. the pyramid = lots of fast unit tests, * fewer integration tests, a handful of slow end-to-end tests. * * unit (most) — one function/module in isolation (everything above). * fast, run on every save. mock the outside world. * integration (some) — several pieces together (e.g. a route + its database). * catches \"they each work but don't fit\" bugs. * e2e (few) — drive the real app in a real browser like a user would: * click, type, assert what's on screen. slow but proves * the whole thing actually works. * * e2e is done with a browser-automation tool — playwright (or cypress): * // npm i -d @playwright/test && npx playwright install * import { test, expect } from '@playwright/test'; * test('user can log in', async ({ page }) => { * await page.goto('http://localhost:3000'); * await page.fill('#email', 'ana@example.com'); * await page.fill('#password', 'secret'); * await page.click('button[type=submit]'); * await expect(page.getbytext('welcome, ana')).tobevisible(); // real ui check * }); * playwright can also test across chromium/firefox/webkit and take screenshots. */ /* ── 8. code coverage — how much of your code the tests run ─────────────────── * coverage shows which lines/branches your tests actually exercise. node has it * built in — no install: * * node --test --experimental-test-coverage lessons/39-testing.js * * it prints a table of % lines/branches/functions covered, and which lines were * missed. (jest/vitest: `--coverage`.) ⚠️ 100% coverage ≠ bug-free — it means * \"executed\", not \"asserted correctly\". use it to find untested code, not as a * trophy. */ /* the tdd loop ---------------------------------------------------------------- * 1. red — write a failing test for the behavior you want. * 2. green — write the simplest code that makes it pass. * 3. refactor — clean up, tests still green. repeat. * tests are a safety net: they let you change code fearlessly. * * jest / vitest equivalent (same idea, different names): * import { describe, it, expect } from 'vitest'; * it('adds', () => { expect(add(2,3)).tobe(5); }); * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. write a test for a `capitalize(str)` function (first letter upper). * 2. test that it throws (or returns '') on an empty string. * 3. mock a `logger` and assert it was called with the right message. * 4. run this file with --experimental-test-coverage and read the report. * 5. sketch (in comments) one unit, one integration, and one e2e test for a * login feature — note what each would and wouldn't catch. * ------------------------------------------------------------------------- */"},"lessons/40-security.js":{"title":"* 40 · security essentials — don't get hacked","learn":"* • xss and how to render user input safely * • csrf, cors, and csp in plain english * • input validation, auth tokens, and secure cookies * • prototype pollution & dependency safety * * security is about not trusting input. most web vulnerabilities come from * treating user-controlled data as if it were safe code or markup.","practice":"/* practice ------------------------------------------------------------------- * 1. write a saferender(el, text) helper that uses textcontent. * 2. add password-strength validation (min length, has number) to validatesignup. * 3. explain in a comment why cors errors can't be fixed from the browser. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 40 · security essentials — don't get hacked * ============================================================================= * run: node lessons/40-security.js * * what you'll learn * • xss and how to render user input safely * • csrf, cors, and csp in plain english * • input validation, auth tokens, and secure cookies * • prototype pollution & dependency safety * * security is about not trusting input. most web vulnerabilities come from * treating user-controlled data as if it were safe code or markup. * ========================================================================== */ // ── 1. xss (cross-site scripting) — the #1 frontend vulnerability ───────────── // xss happens when user input is injected into the page as html/script. // ❌ dangerous: el.innerhtml = userinput ← a <script> or onerror runs! // ✅ safe: el.textcontent = userinput ← rendered as plain text, never run. const userinput = '<img src=x onerror=\"stealcookies()\">'; // if you must build html, escape the dangerous characters first: function escapehtml(str) { return str .replaceall('&', '&amp;') .replaceall('<', '&lt;') .replaceall('>', '&gt;') .replaceall('\"', '&quot;') .replaceall(\"'\", '&#39;'); } console.log(escapehtml(userinput)); // => &lt;img src=x onerror=&quot;stealcookies()&quot;&gt; (harmless text now) // in real apps, prefer textcontent, or a vetted sanitizer like dompurify for // rich html. frameworks (react/vue) escape by default — don't bypass them. // ── 2. csrf (cross-site request forgery) ───────────────────────────────────── // a malicious site tricks the user's browser into sending a request to your // site using their logged-in cookies (e.g. a hidden form that transfers money). // defenses: // • csrf tokens — a secret per-session value the server checks on writes. // • samesite cookies — `set-cookie: token=...; samesite=strict` (or lax). // • check the origin/referer header on state-changing requests. // ── 3. cors (cross-origin resource sharing) ────────────────────────────────── // browsers block js from reading responses across origins unless the server // opts in with headers. cors is the server granting permission — it is not a // way to \"fix\" a blocked request from the client side. // server sends: access-control-allow-origin: https://your-app.com // \"no 'access-control-allow-origin' header\" = the api must allow your origin. // ── 4. csp (content security policy) ───────────────────────────────────────── // an http header that whitelists where scripts/styles/images may load from. // a strong csp turns many xss bugs into no-ops (inline scripts won't run). // content-security-policy: default-src 'self'; script-src 'self' // ── 5. validate & sanitize all input ───────────────────────────────────────── // never trust the client — validate on the server too (client checks are ux). function validatesignup({ email, age }) { const errors = []; if (!/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(email)) errors.push('invalid email'); if (!number.isinteger(age) || age < 13 || age > 120) errors.push('invalid age'); return { ok: errors.length === 0, errors }; } console.log(validatesignup({ email: 'bad', age: 5 })); // => { ok: false, errors: [ 'invalid email', 'invalid age' ] } console.log(validatesignup({ email: 'a@b.co', age: 30 })); // => { ok: true, errors: [] } // ── 6. auth tokens & cookies — rules of thumb ──────────────────────────────── // • never store secrets/passwords in plain text — hash with bcrypt/argon2 (server). // • a jwt is 3 base64 parts: header.payload.signature. the payload is not // encrypted — anyone can read it. don't put secrets in it; verify the signature. const fakejwt = 'eyjhbgcioijiuzi1nij9.eyj1c2vyijoiyw5hin0.sig'; const [, payload] = fakejwt.split('.'); console.log(json.parse(buffer.from(payload, 'base64url').tostring())); // => { user: 'ana' } (jwts use base64url, not plain base64) // • store session tokens in cookies set: httponly; secure; samesite=strict // (httponly = js can't read it → safe from xss theft; secure = https only.) // ── 7. prototype pollution ─────────────────────────────────────────────────── // merging untrusted json that contains \"__proto__\" can poison every object. // guard against keys named __proto__ / constructor / prototype when merging, // or use object.create(null) / map for untrusted key-value data. const safemap = new map(); safemap.set('__proto__', 'harmless here'); // a map key is just data, not the proto console.log(safemap.get('__proto__')); // => harmless here // ── 7b. sql injection — never build queries by string-concatenating input ──── // on the server, gluing user input straight into a query lets an attacker // rewrite it. the classic example: const evilname = \"'; drop table users; --\"; const unsafequery = `select * from users where name = '${evilname}'`; // ☠️ hijacked console.log(unsafequery); // => select * from users where name = ''; drop table users; --' // fix: parameterized queries. the input is sent as a separate value the database // driver binds and escapes, so it can never change the query's structure: // db.query('select * from users where name = ?', [name]); // mysql2 // db.query('select * from users where name = $1', [name]); // node-postgres // same rule for nosql (operator injection) and any shell command you build. // ── 8. dependency & supply-chain safety ────────────────────────────────────── // • run `npm audit` and keep dependencies patched. // • pin versions (lockfile) and review what you install — packages run code. // • don't commit secrets; use environment variables (see lessons 45 & 46). /* practice ------------------------------------------------------------------- * 1. write a saferender(el, text) helper that uses textcontent. * 2. add password-strength validation (min length, has number) to validatesignup. * 3. explain in a comment why cors errors can't be fixed from the browser. * ------------------------------------------------------------------------- */"},"lessons/41-design-patterns.js":{"title":"* 41 · design patterns — reusable solutions with shared names","learn":"* the classic patterns every team uses — knowing their names lets you * communicate designs in seconds (\"let's make it an observer\"). * * • module • singleton • factory • observer (pub/sub) • strategy * • decorator • facade • adapter • command • dependency injection * • a note on mvc / mvvm * * a pattern is just a well-known shape of code, not a library. use them when * they fit — not everywhere.","practice":"/* practice ------------------------------------------------------------------- * 1. build a logger module with private log history and a public add()/last(). * 2. add a 'logout' event to the eventbus and subscribe two listeners. * 3. add a 'discount' strategy set (none/student/senior) chosen at runtime. * 4. write a withtiming(fn) decorator that logs how long fn took (lesson 42). * 5. add a 'delete line' command to the history demo and test undo on it. * 6. refactor createorderservice to inject a third dependency (an emailer). * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 41 · design patterns — reusable solutions with shared names * ============================================================================= * run: node lessons/41-design-patterns.js * * what you'll learn * the classic patterns every team uses — knowing their names lets you * communicate designs in seconds (\"let's make it an observer\"). * * • module • singleton • factory • observer (pub/sub) • strategy * • decorator • facade • adapter • command • dependency injection * • a note on mvc / mvvm * * a pattern is just a well-known shape of code, not a library. use them when * they fit — not everywhere. * ========================================================================== */ // ── 1. module — group related code, hide the internals ─────────────────────── // expose a small public api; keep everything else private (via closures). const counter = (() => { let count = 0; // private — unreachable from outside return { increment() { count++; return count; }, reset() { count = 0; }, get value() { return count; }, }; })(); counter.increment(); counter.increment(); console.log(counter.value); // => 2 // (modern es modules — lesson 23 — are the file-level version of this.) // ── 2. singleton — exactly one shared instance ─────────────────────────────── // useful for things there should only be one of: a config, a cache, a db pool. const settings = (() => { let instance; function create() { return { theme: 'dark', loadedat: 'once' }; } return { get() { if (!instance) instance = create(); // created lazily, only the first time return instance; }, }; })(); console.log(settings.get() === settings.get()); // => true (same object every time) // ── 3. factory — a function that builds objects for you ─────────────────────── // centralizes creation logic so callers don't use `new` or know the details. function createuser(role) { const base = { role, createdat: 'now' }; const perks = { admin: { candelete: true, canedit: true }, editor: { candelete: false, canedit: true }, viewer: { candelete: false, canedit: false }, }; return { ...base, ...(perks[role] ?? perks.viewer) }; } console.log(createuser('admin')); // => { role: 'admin', createdat: 'now', candelete: true, canedit: true } console.log(createuser('viewer')); // => { ..., candelete: false, canedit: false } // ── 4. observer (pub/sub) — broadcast events to many listeners ─────────────── // subscribers register callbacks; the subject notifies them all on change. // this is how event systems, state stores, and reactive uis work under the hood. class eventbus { #listeners = {}; on(event, fn) { (this.#listeners[event] ??= []).push(fn); return () => this.off(event, fn); // return an unsubscribe function } off(event, fn) { this.#listeners[event] = (this.#listeners[event] ?? []).filter((f) => f !== fn); } emit(event, data) { (this.#listeners[event] ?? []).foreach((fn) => fn(data)); } } const bus = new eventbus(); const unsub = bus.on('login', (user) => console.log('welcome', user)); bus.emit('login', 'ana'); // => welcome ana unsub(); // stop listening bus.emit('login', 'bob'); // (nothing — unsubscribed) // ── 5. strategy — swap an algorithm at runtime ─────────────────────────────── // instead of a big if/else, store interchangeable behaviors and pick one. const shipping = { standard: (w) => w * 1.0, express: (w) => w * 2.5 + 5, pickup: () => 0, }; function quote(method, weight) { const strategy = shipping[method] ?? shipping.standard; return strategy(weight); } console.log(quote('express', 2)); // => 10 console.log(quote('pickup', 99)); // => 0 // ── 6. decorator — wrap something to add behavior, same interface ───────────── // take a function/object and return an enhanced version without editing the // original. (you've already met decorators: memoize and debounce wrap a fn.) function withlogging(fn) { return (...args) => { console.log(`calling with ${json.stringify(args)}`); const result = fn(...args); console.log(`→ returned ${result}`); return result; }; } const add = (a, b) => a + b; const loudadd = withlogging(add); // same (a, b) interface, extra behavior loudadd(2, 3); // logs the call + result, still returns 5 // ── 7. facade — a simple front over a complicated subsystem ─────────────────── // hide several messy steps behind one friendly method. (jquery, axios, and most // sdks are facades over fetch/xhr/etc.) const subsystema = { connect: () => 'a ready' }; const subsystemb = { auth: () => 'b authed' }; const subsystemc = { load: () => 'c loaded' }; const app = { start() { // callers don't need to know the 3 steps return [subsystema.connect(), subsystemb.auth(), subsystemc.load()].join(' | '); }, }; console.log('facade:', app.start()); // => a ready | b authed | c loaded // ── 8. adapter — make an incompatible interface fit ────────────────────────── // wrap an object so it matches the shape your code expects (e.g. integrating a // third-party api whose field names differ from yours). const oldapiuser = { user_name: 'ana', years_old: 30 }; // their shape function useradapter(raw) { // → your shape return { name: raw.user_name, age: raw.years_old }; } console.log('adapter:', useradapter(oldapiuser)); // => { name: 'ana', age: 30 } // ── 9. command — wrap an action as an object (enables undo/redo, queues) ────── // each command knows how to do() and undo() itself. a history stack (lesson 49) // then gives you undo for free — this is how editors implement ctrl+z. class history { #done = []; run(command) { command.execute(); this.#done.push(command); } undo() { this.#done.pop()?.undo(); } } const doc = { text: '' }; const typecmd = (s) => ({ execute: () => (doc.text += s), undo: () => (doc.text = doc.text.slice(0, -s.length)) }); const history = new history(); history.run(typecmd('hello')); history.run(typecmd(' world')); console.log('command:', doc.text); // => hello world history.undo(); console.log('after undo:', doc.text); // => hello // ── 10. dependency injection — pass collaborators in, don't hard-code them ──── // instead of a function reaching for a global, give it what it needs as an // argument. result: easy to swap a real logger for a fake one in tests (lesson 39). function createorderservice(logger, payments) { // dependencies injected here return { checkout(amount) { payments.charge(amount); logger.log(`charged ${amount}`); }, }; } const fakelogger = { log: (m) => console.log('di log:', m) }; const fakepayments = { charge: (n) => {} }; createorderservice(fakelogger, fakepayments).checkout(50); // => di log: charged 50 /* ── 11. mvc / mvvm (architectural patterns) — the big picture ──────────────── * bigger than the above; they organize a whole app, not one object: * mvc — model (data/rules) · view (ui) · controller (handles input, updates * the model, picks the view). classic server frameworks use this. * mvvm — model · view · viewmodel (exposes data the view binds to). the * viewmodel + data-binding is what react/vue/angular popularized. * takeaway: separate what your app knows (model) from how it's shown (view) so * each can change independently. frameworks give you this structure for free. */ /* when to reach for each ------------------------------------------------------ * module ..... hide internals, expose a clean api * singleton .. one shared resource (config/cache) — use sparingly * factory .... complex/conditional object creation * observer ... \"when x happens, tell everyone who cares\" (events, state) * strategy ... many interchangeable algorithms behind one call * decorator .. add behavior by wrapping, keep the same interface * facade ..... one simple method over a complex subsystem * adapter .... make a foreign interface fit your code * command .... actions as objects → undo/redo, queues, logging * dep. inject pass collaborators in → testable, swappable code * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. build a logger module with private log history and a public add()/last(). * 2. add a 'logout' event to the eventbus and subscribe two listeners. * 3. add a 'discount' strategy set (none/student/senior) chosen at runtime. * 4. write a withtiming(fn) decorator that logs how long fn took (lesson 42). * 5. add a 'delete line' command to the history demo and test undo on it. * 6. refactor createorderservice to inject a third dependency (an emailer). * ------------------------------------------------------------------------- */"},"lessons/42-performance.js":{"title":"* 42 · performance — make it fast (and know what \"fast\" means)","learn":"* • big-o intuition — why algorithm choice beats micro-tweaks * • memoization & caching * • debounce/throttle recap (lesson 30) * • browser rendering: reflow/repaint, lazy loading, code splitting * • core web vitals — how performance is actually measured in 2026 * • measuring & profiling: performance marks, performanceobserver * • list virtualization (windowing) for huge lists * * rule: measure before optimizing. \"premature optimization is the root of all * evil\" — make it correct, measure, then fix the real bottleneck.","practice":"/* practice ------------------------------------------------------------------- * 1. memoize a slow fibonacci(n) and compare call counts with/without it. * 2. rewrite an o(n²) \"find duplicates\" using a set to get o(n). * 3. name which web vital each fixes: slow hero image, janky button, jumpy layout. * 4. wrap two code blocks in performance.mark/measure and log which is slower. * 5. in words: why does virtualization keep a 100k-row list fast? (dom size.) * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 42 · performance — make it fast (and know what \"fast\" means) * ============================================================================= * run: node lessons/42-performance.js * * what you'll learn * • big-o intuition — why algorithm choice beats micro-tweaks * • memoization & caching * • debounce/throttle recap (lesson 30) * • browser rendering: reflow/repaint, lazy loading, code splitting * • core web vitals — how performance is actually measured in 2026 * • measuring & profiling: performance marks, performanceobserver * • list virtualization (windowing) for huge lists * * rule: measure before optimizing. \"premature optimization is the root of all * evil\" — make it correct, measure, then fix the real bottleneck. * ========================================================================== */ // ── 1. big-o intuition — how cost grows with input size ────────────────────── // o(1) constant ...... array[i], map.get(key) // o(log n) logarithmic ... binary search // o(n) linear ........ a single loop // o(n log n) ............... good sorts // o(n²) quadratic ..... nested loop over the same data — avoid at scale // // picking the right data structure changes the big-o. \"is x in this list?\": const big = array.from({ length: 100_000 }, (_, i) => i); const asset = new set(big); console.log(big.includes(99_999)); // o(n) — scans up to 100k items console.log(asset.has(99_999)); // o(1) — instant lookup ✅ // ── 2. memoization — cache expensive results by their inputs ───────────────── function memoize(fn) { const cache = new map(); return (...args) => { const key = json.stringify(args); if (cache.has(key)) return cache.get(key); // cache hit — skip the work const result = fn(...args); cache.set(key, result); return result; }; } let calls = 0; const slowsquare = (n) => { calls++; return n * n; }; const fastsquare = memoize(slowsquare); fastsquare(9); fastsquare(9); // served from cache — fn body not re-run fastsquare(9); console.log(fastsquare(9), 'computed', calls, 'time(s)'); // => 81 computed 1 time(s) // ── 3. debounce & throttle (limit how often code runs) — see lesson 30 ─────── // debounce: wait until activity stops (search-as-you-type, resize). // throttle: run at most once per interval (scroll, mousemove). // both prevent doing heavy work on every single event. // ── 4. browser rendering performance (concept) ─────────────────────────────── // • reflow (layout): the browser recomputes geometry — expensive. triggered by // changing size/position or reading layout props (offsetheight) mid-mutation. // • repaint: redrawing pixels (e.g. color change) — cheaper than reflow. // tips: batch dom writes; build nodes off-dom then insert once (lesson 24); // animate `transform`/`opacity` (gpu) instead of top/left/width. // ── 5. loading performance (concept) ───────────────────────────────────────── // • lazy loading: load things only when needed. // <img loading=\"lazy\"> // images // const mod = await import('./chart.js'); // dynamic import → code splitting // code splitting ships a smaller initial bundle; the rest loads on demand. // • defer non-critical js: <script defer src=\"app.js\"></script> // • compress & cache: gzip/brotli, http caching headers, a cdn. // ── 6. core web vitals — the metrics that matter (2026) ────────────────────── // lcp (largest contentful paint) — load speed → aim < 2.5s // inp (interaction to next paint) — responsiveness → aim < 200ms // cls (cumulative layout shift) — visual stability → aim < 0.1 // measure with lighthouse, the performance panel, or the web-vitals library. // ── 7. measuring in code ───────────────────────────────────────────────────── const t0 = performance.now(); let sum = 0; for (let i = 0; i < 1_000_000; i++) sum += i; const ms = performance.now() - t0; console.log(`loop took ${ms.tofixed(1)}ms`); // varies by machine // (console.time/timeend from lesson 36 do the same thing more conveniently.) // ── 8. profiling with marks & measures (the performance api) ───────────────── // performance.now() is one stopwatch. the performance api lets you drop named // marks and measure the span between them — those show up in browser devtools' // performance panel too, so you can see them on a real timeline. performance.mark('work-start'); let total = 0; for (let i = 0; i < 500_000; i++) total += i; performance.mark('work-end'); const measure = performance.measure('heavy-work', 'work-start', 'work-end'); console.log(`measured \"${measure.name}\": ${measure.duration.tofixed(1)}ms`); // a performanceobserver reacts to entries as they're recorded — this is how the // `web-vitals` library and monitoring tools collect lcp/inp/cls in real users' // browsers (then report them, lesson 48): const obs = new performanceobserver((list) => { for (const entry of list.getentries()) { console.log(`observed ${entry.entrytype} \"${entry.name}\": ${entry.duration.tofixed(1)}ms`); } }); obs.observe({ entrytypes: ['measure'] }); performance.measure('observed-span', 'work-start', 'work-end'); // in the browser you'd also observe: 'largest-contentful-paint', 'event' // (for inp), 'layout-shift' (for cls), 'longtask', 'resource', 'navigation'. settimeout(() => obs.disconnect(), 50); // stop observing (avoid leaks, lesson 37) /* ── 9. list virtualization (windowing) — render only what's visible ────────── * rendering 10,000 rows = 10,000 dom nodes = a frozen page. virtualization * renders only the ~20 rows currently in view (a \"window\") and swaps their * contents as you scroll. the list feels infinite but the dom stays tiny. * * const row_h = 30, visible = math.ceil(container.clientheight / row_h); * container.onscroll = () => { * const start = math.floor(container.scrolltop / row_h); * render(items.slice(start, start + visible + 2)); // only the window * }; * * libraries: tanstack virtual, react-window. this is the fix for slow long * lists/tables/feeds — it turns o(n) dom nodes into o(window). */ /* practice ------------------------------------------------------------------- * 1. memoize a slow fibonacci(n) and compare call counts with/without it. * 2. rewrite an o(n²) \"find duplicates\" using a set to get o(n). * 3. name which web vital each fixes: slow hero image, janky button, jumpy layout. * 4. wrap two code blocks in performance.mark/measure and log which is slower. * 5. in words: why does virtualization keep a 100k-row list fast? (dom size.) * ------------------------------------------------------------------------- */"},"lessons/43-polyfills.js":{"title":"* 43 · polyfills — implement the built-ins yourself","learn":"* re-building the methods you use every day. this is the single best way to * *truly* understand them — and it's the most common js interview exercise. * * we'll re-implement: map, filter, reduce, call/apply/bind, debounce, * and a minimal promise. * * (a real \"polyfill\" also checks `if (!array.prototype.x)` before defining, so * it only fills the gap in old engines. we focus on the implementations.)","practice":"/* practice ------------------------------------------------------------------- * 1. implement myforeach(arr, fn) (like map but returns nothing). * 2. implement myflat(arr, depth) using recursion (lesson 09). * 3. add a .catch(fn) method to mypromise (hint: then(undefined, fn)). * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 43 · polyfills — implement the built-ins yourself * ============================================================================= * run: node lessons/43-polyfills.js * * what you'll learn * re-building the methods you use every day. this is the single best way to * *truly* understand them — and it's the most common js interview exercise. * * we'll re-implement: map, filter, reduce, call/apply/bind, debounce, * and a minimal promise. * * (a real \"polyfill\" also checks `if (!array.prototype.x)` before defining, so * it only fills the gap in old engines. we focus on the implementations.) * ========================================================================== */ // ── 1. array.prototype.map ─────────────────────────────────────────────────── function mymap(arr, fn) { const out = []; for (let i = 0; i < arr.length; i++) out.push(fn(arr[i], i, arr)); return out; } console.log(mymap([1, 2, 3], (n) => n * 2)); // => [ 2, 4, 6 ] // ── 2. array.prototype.filter ──────────────────────────────────────────────── function myfilter(arr, predicate) { const out = []; for (let i = 0; i < arr.length; i++) { if (predicate(arr[i], i, arr)) out.push(arr[i]); } return out; } console.log(myfilter([1, 2, 3, 4], (n) => n % 2 === 0)); // => [ 2, 4 ] // ── 3. array.prototype.reduce ──────────────────────────────────────────────── function myreduce(arr, reducer, initial) { // faithful to real reduce: tell \"no seed\" from \"seed is undefined\" by arity, // not by `initial === undefined` — an explicit undefined seed is still a seed. const hasseed = arguments.length >= 3; let acc = hasseed ? initial : arr[0]; for (let i = hasseed ? 0 : 1; i < arr.length; i++) acc = reducer(acc, arr[i], i, arr); return acc; } console.log(myreduce([1, 2, 3, 4], (a, b) => a + b, 0)); // => 10 // ── 4. function.prototype.call / apply / bind ──────────────────────────────── // the trick: put the function on the target object so `this` becomes that object. function mycall(fn, context, ...args) { const key = symbol('fn'); context = context ?? globalthis; context[key] = fn; const result = context[key](...args); delete context[key]; return result; } function mybind(fn, context, ...preset) { return (...later) => mycall(fn, context, ...preset, ...later); } const person = { name: 'ana' }; function greet(greeting) { return `${greeting}, ${this.name}`; } console.log(mycall(greet, person, 'hi')); // => hi, ana const sayhello = mybind(greet, person, 'hello'); console.log(sayhello()); // => hello, ana // ── 5. debounce — delay until calls stop (lesson 30, built from scratch) ───── function debounce(fn, delay) { let timer; return (...args) => { cleartimeout(timer); // cancel the previous pending call timer = settimeout(() => fn(...args), delay); }; } const log = debounce((msg) => console.log('debounced:', msg), 50); log('a'); log('b'); log('c'); // only 'c' fires, ~50ms later // ── 6. a minimal promise ───────────────────────────────────────────────────── // simplified, but shows the core: state machine + queued callbacks + then(). class mypromise { constructor(executor) { this.state = 'pending'; this.value = undefined; this.callbacks = []; const resolve = (value) => this.#settle('fulfilled', value); const reject = (reason) => this.#settle('rejected', reason); try { executor(resolve, reject); } catch (e) { reject(e); } } #settle(state, value) { if (this.state !== 'pending') return; // settle only once this.state = state; this.value = value; this.callbacks.foreach((cb) => cb()); // flush anyone waiting } then(onfulfilled, onrejected) { return new mypromise((resolve, reject) => { const run = () => { try { if (this.state === 'fulfilled') resolve(onfulfilled ? onfulfilled(this.value) : this.value); else reject(onrejected ? onrejected(this.value) : this.value); } catch (e) { reject(e); } }; // if already settled, run on the microtask queue; else queue until settle this.state === 'pending' ? this.callbacks.push(run) : queuemicrotask(run); }); } } new mypromise((resolve) => settimeout(() => resolve(21), 10)) .then((n) => n * 2) .then((n) => console.log('mypromise result:', n)); // => 42 /* practice ------------------------------------------------------------------- * 1. implement myforeach(arr, fn) (like map but returns nothing). * 2. implement myflat(arr, depth) using recursion (lesson 09). * 3. add a .catch(fn) method to mypromise (hint: then(undefined, fn)). * ------------------------------------------------------------------------- */"},"lessons/44-typescript.js":{"title":"* 44 · typescript on-ramp — javascript with types","learn":"* what typescript adds on top of the js you already know, why teams use it, * and the core syntax — so your first .ts file feels familiar. * * typescript = javascript + a type layer checked before you run. the types are * erased at build time; the browser/node runs plain js. it catches a whole * class of bugs (\"undefined is not a function\") at your desk, not in production. * * run real ts: npm i -d typescript && npx tsc file.ts (or use ts-node / bun / deno) * below, the ts is shown in comments; the runnable code is the js equivalent.","practice":"/* practice ------------------------------------------------------------------- * 1. write (in a comment) a `product` interface: id:number, name:string, * price:number, instock?:boolean. * 2. annotate a `total(items: product[]): number` signature. * 3. add jsdoc types to a real iseven(n) function in this file. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 44 · typescript on-ramp — javascript with types * ============================================================================= * run: node lessons/44-typescript.js (the runnable parts are plain js) * * what you'll learn * what typescript adds on top of the js you already know, why teams use it, * and the core syntax — so your first .ts file feels familiar. * * typescript = javascript + a type layer checked before you run. the types are * erased at build time; the browser/node runs plain js. it catches a whole * class of bugs (\"undefined is not a function\") at your desk, not in production. * * run real ts: npm i -d typescript && npx tsc file.ts (or use ts-node / bun / deno) * below, the ts is shown in comments; the runnable code is the js equivalent. * ========================================================================== */ console.log('=== typescript concepts (ts in comments, js runs) ==='); /* ── 1. basic types ────────────────────────────────────────────────────────── * let name: string = 'ana'; * let age: number = 30; * let active: boolean = true; * let tags: string[] = ['js', 'ts']; * let pair: [string, number] = ['x', 1]; // tuple * type inference means you rarely annotate obvious things: * let count = 0; // inferred as number — reassigning to 'hi' errors */ /* ── 2. function signatures ────────────────────────────────────────────────── * function add(a: number, b: number): number { return a + b; } * const greet = (name: string): string => `hi ${name}`; * add(2, 'x'); // ❌ compile error: 'x' is not a number ← caught early! */ function add(a, b) { return a + b; } // the js this compiles to console.log('add(2,3):', add(2, 3)); // => 5 /* ── 3. interfaces & type aliases — shapes of objects ──────────────────────── * interface user { id: number; name: string; email?: string } // ? = optional * type id = number | string; // union type * function format(u: user): string { return `${u.id}:${u.name}`; } */ const user = { id: 1, name: 'ana' }; // a value matching the user shape console.log('user:', `${user.id}:${user.name}`); // => 1:ana /* ── 4. union types & narrowing ────────────────────────────────────────────── * function len(x: string | string[]): number { * if (typeof x === 'string') return x.length; // ts narrows x to string here * return x.length; // here x is string[] * } * narrowing = ts uses your runtime checks (typeof, in, array.isarray) to know * the precise type inside each branch. */ function len(x) { return typeof x === 'string' ? x.length : x.length; } console.log('len:', len('hello'), len(['a', 'b'])); // => 5 2 /* ── 5. generics — reusable, type-safe containers/functions ────────────────── * function first<t>(arr: t[]): t | undefined { return arr[0]; } * first<number>([1, 2, 3]); // returns number * first(['a', 'b']); // t inferred as string * think \"a type parameter\" — like a function argument, but for types. */ function first(arr) { return arr[0]; } console.log('first:', first([10, 20]), first(['x'])); // => 10 x /* ── 6. utility & helpers you'll meet ──────────────────────────────────────── * partial<user> // all fields optional * readonly<user> // all fields immutable * pick<user,'id'> // just some fields * enum role { admin, editor, viewer } // ⚠️ many teams now prefer a string * // union ('admin'|'editor') or `as const` * as const // freeze a literal's type * unknown vs any // prefer `unknown` (forces you to check before use) */ /* ── 7. jsdoc — types without typescript ───────────────────────────────────── * you can get editor type-checking in plain .js files using jsdoc comments — * a nice on-ramp before adopting .ts. this is real and checkable: */ /** @param {number} n @returns {number} */ function double(n) { return n * 2; } console.log('double:', double(21)); // => 42 /* why teams use it ------------------------------------------------------------ * • bugs caught at compile time, not runtime. * • autocomplete & refactoring that actually understands your data. * • types document the code and survive refactors. * cost: a build step and a learning curve. for anything beyond a small * script, most 2026 production codebases are typescript. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. write (in a comment) a `product` interface: id:number, name:string, * price:number, instock?:boolean. * 2. annotate a `total(items: product[]): number` signature. * 3. add jsdoc types to a real iseven(n) function in this file. * ------------------------------------------------------------------------- */"},"lessons/45-tooling.js":{"title":"* 45 · tooling & build systems — the modern js workflow","learn":"* the tools that turn your source code into a shippable app, and what each * one is for. you don't memorize commands — you learn the moving parts. * * npm/package.json · workspaces/monorepos · semver · bundlers · transpilers * · linters · git · ci/cd","practice":"/* practice ------------------------------------------------------------------- * 1. run `npm init -y` in a folder and add a \"start\": \"node index.js\" script. * 2. explain the difference between dependencies and devdependencies. * 3. scaffold a real app: `npm create vite@latest` and run `npm run dev`. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 45 · tooling & build systems — the modern js workflow * ============================================================================= * run: node lessons/45-tooling.js (a guided tour; prints the key concepts) * * what you'll learn * the tools that turn your source code into a shippable app, and what each * one is for. you don't memorize commands — you learn the moving parts. * * npm/package.json · workspaces/monorepos · semver · bundlers · transpilers * · linters · git · ci/cd * ========================================================================== */ console.log('=== the modern javascript toolchain ===\\n'); // ── 1. npm & package.json — the project manifest ───────────────────────────── // `npm init -y` creates package.json. it records dependencies and scripts. const packagejson = { name: 'my-app', version: '1.0.0', type: 'module', // use es modules (lesson 23) scripts: { dev: 'vite', // run with: npm run dev build: 'vite build', test: 'vitest', lint: 'eslint .', }, dependencies: { /* runtime deps: npm install <pkg> */ }, devdependencies: { /* build/test: npm install -d <pkg> */ }, }; console.log('package.json scripts → run with `npm run <name>`:'); console.log(object.keys(packagejson.scripts).join(', ')); // => dev, build, test, lint // • node_modules/ — installed packages (never commit it; it's huge). // • package-lock.json — pins exact versions so installs are reproducible. // ── 1b. monorepos & workspaces — many packages, one repo ───────────────────── // as a project grows you often split it into packages (e.g. ui, api, shared-utils) // that depend on each other. a monorepo keeps them in one repo with workspaces so // a single `npm install` links them locally — edit `shared-utils` and `ui` sees it // instantly, no publish step. const workspaceroot = { name: 'my-company', private: true, // a workspace root is never published workspaces: ['packages/*'], // npm/pnpm/yarn all support this field }; console.log('workspaces:', workspaceroot.workspaces[0]); // => packages/* // • tools: npm/pnpm/yarn workspaces (linking) + turborepo/nx (cached task runners // that only rebuild/test the packages that actually changed). // • why: share code without publishing, one lockfile, atomic cross-package changes. // ── 2. semantic versioning (semver): major.minor.patch ────────────────────── // ^1.2.3 → allow 1.x.x (minor+patch updates) ← npm default // ~1.2.3 → allow 1.2.x (patch only) // 1.2.3 → exactly this version console.log('semver: major(breaking).minor(features).patch(fixes)'); // ── 3. bundlers — many files → optimized output ────────────────────────────── // a bundler resolves your imports, bundles them, tree-shakes dead code, and // minifies for production. modern choices: // • vite — fast dev server + build (most common in 2026; migrating to rolldown) // • esbuild / rollup / rolldown — the engines under many tools // • webpack — older, powerful, lots of legacy projects console.log('bundler job: resolve imports → tree-shake → minify → split'); // ── 4. transpiling — new syntax → widely-supported js ──────────────────────── // • babel / esbuild convert modern js (and jsx/ts) into code older browsers run. // • a \"browserslist\" config decides how far back to compile. // • this is why you can write es2025 today and still support older targets. // ── 5. linting & formatting — consistency + catching mistakes ──────────────── // • eslint — flags bugs & bad patterns (unused vars, == misuse). `npx eslint .` // • prettier — auto-formats code so the team never argues about style. // run them on save and in ci so problems never reach main. // ── 6. git — version control basics (every project) ────────────────────────── const gitflow = ['git init', 'git add .', 'git commit -m \"msg\"', 'git push', 'git branch feature', 'git merge', 'open a pull request → review → merge']; console.log('\\ngit flow:', gitflow.join(' → ')); // • .gitignore keeps node_modules/, .env, and build output out of the repo. // ── 7. ci/cd — automate test & deploy ──────────────────────────────────────── // continuous integration: on every push, a server (github actions, etc.) runs // install → lint → test → build. red build = don't merge. // continuous deployment: green build auto-ships to staging/production. console.log('ci on push: install → lint → test → build → deploy'); // ── 8. source maps — debug the original code, not the bundle ───────────────── // build tools emit .map files linking minified output back to your source, so // devtools shows your code in the debugger even in production builds. /* the big picture ------------------------------------------------------------- * write code → lint/format → transpile → bundle → test → ci → deploy * you rarely wire this by hand: `npm create vite@latest` scaffolds most of it. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. run `npm init -y` in a folder and add a \"start\": \"node index.js\" script. * 2. explain the difference between dependencies and devdependencies. * 3. scaffold a real app: `npm create vite@latest` and run `npm run dev`. * ------------------------------------------------------------------------- */"},"lessons/46-nodejs.js":{"title":"* 46 · node.js — javascript on the server","learn":"* the node-specific apis that the browser doesn't have: process & env, * the file system, paths, events, streams, and a real http server. * * node is javascript outside the browser — it powers backends, clis, and * tooling. core modules live under the `node:` prefix.","practice":"/* practice ------------------------------------------------------------------- * 1. read process.argv and greet a name passed on the command line. * 2. write an object to a json file with fs.writefile, then read it back. * 3. add a '/time' route to the server that returns the current time. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 46 · node.js — javascript on the server * ============================================================================= * run: node lessons/46-nodejs.js * * (heads-up: node prints a harmless \"module_typeless_package_json\" warning — * this file is an es module and package.json has no \"type\" on purpose. ignore it.) * * what you'll learn * the node-specific apis that the browser doesn't have: process & env, * the file system, paths, events, streams, and a real http server. * * node is javascript outside the browser — it powers backends, clis, and * tooling. core modules live under the `node:` prefix. * ========================================================================== */ import process from 'node:process'; import path from 'node:path'; import os from 'node:os'; import fs from 'node:fs/promises'; import { eventemitter } from 'node:events'; import http from 'node:http'; // ── 1. process — info about the running program ────────────────────────────── console.log('node version :', process.version); // => v24.x console.log('platform :', process.platform); // => linux / darwin / win32 console.log('cwd :', process.cwd().split('/').pop()); // current folder name // cli args: node script.js foo bar → process.argv = [node, script, 'foo', 'bar'] console.log('args :', process.argv.slice(2)); // => [] (none here) // environment variables — where secrets/config live (never hard-code secrets): // run: api_key=abc node lessons/46-nodejs.js console.log('api_key :', process.env.api_key ?? '(not set — see lesson 40)'); // ── 2. path — build file paths the cross-platform way ──────────────────────── console.log('join :', path.join('src', 'utils', 'math.js')); // src/utils/math.js console.log('extname :', path.extname('report.pdf')); // => .pdf console.log('basename :', path.basename('/a/b/notes.txt')); // => notes.txt // ── 3. fs — read & write files (async/await) ───────────────────────────────── const tmpfile = path.join(os.tmpdir(), 'js-learn-demo.txt'); await fs.writefile(tmpfile, 'hello from node\\n'); // create/overwrite const contents = await fs.readfile(tmpfile, 'utf8'); // read back as text console.log('file says :', contents.trim()); // => hello from node await fs.appendfile(tmpfile, 'second line\\n'); // append await fs.unlink(tmpfile); // delete (cleanup) console.log('temp file cleaned up ✅'); // ── 4. eventemitter — node's built-in observer (lesson 41 pattern) ─────────── class order extends eventemitter {} const order = new order(); order.on('paid', (amount) => console.log(`order paid: $${amount}`)); // listener order.emit('paid', 99); // => order paid: $99 // many node objects (streams, servers, sockets) are eventemitters. // ── 5. streams — process data piece by piece, not all at once ──────────────── // streams let you handle huge files/responses with low memory by working on // chunks. (conceptual — fs.createreadstream(path).on('data', chunk => ...).) // examples: reading a 2gb log line-by-line, or piping a download to disk. // ── 6. a real http server ──────────────────────────────────────────────────── // http.createserver gives you a callback per request. we start it on a random // free port (0), make one request to ourselves, print the reply, then close. const server = http.createserver((req, res) => { res.writehead(200, { 'content-type': 'application/json' }); res.end(json.stringify({ ok: true, path: req.url })); }); await new promise((resolve) => server.listen(0, resolve)); // 0 = pick a free port const { port } = server.address(); const reply = await fetch(`http://localhost:${port}/hello`).then((r) => r.json()); console.log('server replied:', reply); // => { ok: true, path: '/hello' } server.close(); // stop listening so the program can exit // in real apps you'd use a framework (express/fastify/hono) on top of this. /* browser vs node ------------------------------------------------------------- * browser has: window, document, dom, localstorage. * node has: process, fs, path, http, os, buffer, eventemitter. * shared: js syntax, fetch, promises, console, timers, json. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. read process.argv and greet a name passed on the command line. * 2. write an object to a json file with fs.writefile, then read it back. * 3. add a '/time' route to the server that returns the current time. * ------------------------------------------------------------------------- */"},"lessons/47-browser-apis.js":{"title":"* 47 · advanced browser apis (browser)","learn":"* the powerful platform apis beyond dom/events: * web workers · service workers/pwa · indexeddb · observers · * web components · requestanimationframe · device apis","practice":"/* practice (in the browser) -------------------------------------------------- * 1. use intersectionobserver to log when a bottom element scrolls into view. * 2. define a <hello-world> web component that renders your name. * 3. animate a box across the screen with requestanimationframe. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 47 · advanced browser apis (browser) * ============================================================================= * how to run: these are browser features. open index.html and try them in the * console/devtools — they don't exist in node. this file runs harmlessly in * node (it just prints a notice); the real examples are in the comments. * * what you'll learn * the powerful platform apis beyond dom/events: * web workers · service workers/pwa · indexeddb · observers · * web components · requestanimationframe · device apis * ========================================================================== */ // guard so the file is harmless in node: if (typeof window === 'undefined') { console.log('⚠️ lesson 47 is browser-only. open index.html and read the code in devtools.'); } /* ── 1. web workers — run heavy js off the main thread ─────────────────────── * the main thread renders the ui; long loops there freeze the page. a worker * runs in parallel and talks via messages — no shared variables. * * // main.js * const worker = new worker('worker.js'); * worker.postmessage({ n: 40 }); * worker.onmessage = (e) => console.log('result', e.data); * * // worker.js * onmessage = (e) => postmessage(fib(e.data.n)); // cpu work, ui stays smooth */ /* ── 2. service workers & pwas — offline + installable ─────────────────────── * a service worker is a proxy between your app and the network. it can cache * assets so the app works offline and loads instantly. plus a manifest.json = * an installable progressive web app. * * navigator.serviceworker.register('/sw.js'); * // sw.js * self.addeventlistener('fetch', (e) => * e.respondwith(caches.match(e.request).then((c) => c ?? fetch(e.request)))); */ /* ── 3. indexeddb — a real database in the browser ─────────────────────────── * localstorage (lesson 34) holds small strings synchronously. indexeddb stores * large, structured, queryable data (objects, blobs) asynchronously. * * const req = indexeddb.open('mydb', 1); * req.onupgradeneeded = (e) => e.target.result.createobjectstore('users', { keypath: 'id' }); * req.onsuccess = (e) => { const db = e.target.result; ... transactions ... }; * libraries like `idb` make its callback api far nicer. */ /* ── 4. observer apis — react to changes efficiently ───────────────────────── * • intersectionobserver — \"is this element on screen?\" → lazy-load images, * infinite scroll, fade-in-on-scroll (no scroll-event spam). * new intersectionobserver(es => es.foreach(e => e.isintersecting && load(e.target))) * .observe(img); * • mutationobserver — watch the dom for added/removed/changed nodes. * • resizeobserver — react when an element's size changes. */ /* ── 5. web components — reusable custom elements (framework-free) ──────────── * define your own html tags with encapsulated markup/style via shadow dom. * * class mycounter extends htmlelement { * connectedcallback() { * const root = this.attachshadow({ mode: 'open' }); // isolated dom/css * root.innerhtml = `<button>+</button><span>0</span>`; * } * } * customelements.define('my-counter', mycounter); // <my-counter></my-counter> */ /* ── 6. requestanimationframe — smooth 60fps animation ─────────────────────── * don't animate with setinterval. raf runs your callback right before the next * paint, syncing to the display and pausing in background tabs. * * function tick(t) { move(); requestanimationframe(tick); } * requestanimationframe(tick); */ /* ── 7. device & misc apis (ask permission; https only) ────────────────────── * navigator.geolocation.getcurrentposition(pos => ...); // location * await navigator.clipboard.writetext('copied!'); // clipboard * new notification('hi!'); // notifications * matchmedia('(prefers-color-scheme: dark)').matches; // dark mode * navigator.online; // online status */ /* practice (in the browser) -------------------------------------------------- * 1. use intersectionobserver to log when a bottom element scrolls into view. * 2. define a <hello-world> web component that renders your name. * 3. animate a box across the screen with requestanimationframe. * ------------------------------------------------------------------------- */"},"lessons/48-realtime-and-production.js":{"title":"* 48 · real-time networking & production ops","learn":"* • pushing data in real time: websockets vs server-sent events vs polling * • running software in production: logging, observability, config, flags * • not overwhelming downstreams: concurrency/rate limits, queues, backpressure * • accessibility (a11y) & internationalization (i18n) basics * * \"it works on my machine\" isn't done. production code must be observable, * configurable, resilient, and usable by everyone.","practice":"/* practice ------------------------------------------------------------------- * 1. add a 'warn' log call and confirm it prints but 'debug' does not. * 2. extend choosetransport for a 'one-off request' → 'fetch'. * 3. read log_level from env and make the log() threshold respect it. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 48 · real-time networking & production ops * ============================================================================= * run: node lessons/48-realtime-and-production.js * * what you'll learn * • pushing data in real time: websockets vs server-sent events vs polling * • running software in production: logging, observability, config, flags * • not overwhelming downstreams: concurrency/rate limits, queues, backpressure * • accessibility (a11y) & internationalization (i18n) basics * * \"it works on my machine\" isn't done. production code must be observable, * configurable, resilient, and usable by everyone. * ========================================================================== */ // ── 1. real-time: three ways to get fresh data ─────────────────────────────── // • polling ........ ask repeatedly on a timer. simple, but wasteful/laggy. // setinterval(() => fetch('/api/messages'), 5000); // • sse (eventsource) ... server → client, one-way stream over plain http. // const es = new eventsource('/stream'); // es.onmessage = (e) => console.log('update:', e.data); // great for feeds // • websockets ..... full duplex (both directions), low latency. chat, games, // live cursors. a persistent connection, not request/response. // const ws = new websocket('wss://example.com'); // ws.onopen = () => ws.send('hello'); // ws.onmessage = (e) => console.log('got:', e.data); // on the server (node) you'd use the `ws` library or socket.io. console.log('real-time: poll (simple) · sse (one-way push) · websocket (two-way) — pick per need, not \"bigger is better\"'); // quick decision guide: function choosetransport(need) { if (need === 'two-way') return 'websocket'; if (need === 'server-push') return 'sse'; return 'polling'; } console.log(choosetransport('two-way')); // => websocket console.log(choosetransport('server-push')); // => sse // ── 2. logging — structured, leveled ───────────────────────────────────────── // don't ship console.log spam. use levels and structured (json) logs so they're // searchable in a log platform. (libraries: pino, winston.) const levels = { error: 0, warn: 1, info: 2, debug: 3 }; function log(level, msg, meta = {}) { if (levels[level] <= levels.info) { // current threshold = info console.log(json.stringify({ level, msg, ...meta })); } } log('info', 'user signed up', { userid: 42 }); // => {\"level\":\"info\",\"msg\":\"user signed up\",\"userid\":42} log('debug', 'noisy detail'); // suppressed (below threshold) // ── 3. monitoring, error tracking & observability ──────────────────────────── // • catch and report errors from real users (sentry, etc.) instead of losing them: // window.addeventlistener('error', (e) => report(e)); // window.addeventlistener('unhandledrejection', (e) => report(e.reason)); // process.on('uncaughtexception', report); // node // • observability has three pillars: logs (events), metrics (numbers over time), // traces (one request's path across services). the mental model is the same // everywhere: capture → enrich (user, release, request id) → ship → alert. // - error aggregation (sentry/bugsnag-style): groups duplicate crashes, // attaches stack + release + breadcrumbs, so one alert ≠ one email per user. // - distributed tracing (opentelemetry is the vendor-neutral standard): // follow a single request through api → db → queue to find the slow hop. // - apm ties latency/error-rate/throughput to releases so you spot regressions. // • track metrics (latency, error rate, throughput) and set alerts. // \"if you can't see it, you can't fix it.\" // ── 4. configuration & secrets ─────────────────────────────────────────────── // • config comes from environment variables, not hard-coded values (lesson 46). // • secrets (api keys, db passwords) live in a secret manager / .env that is // git-ignored — never committed (lesson 40). const config = { apiurl: process.env.api_url ?? 'http://localhost:3000', loglevel: process.env.log_level ?? 'info', }; console.log('config:', config); // ── 5. feature flags & graceful failure ────────────────────────────────────── // • feature flags toggle features without redeploying (gradual rollout, kill-switch). const flags = { newcheckout: false }; console.log(flags.newcheckout ? 'new checkout' : 'old checkout'); // => old checkout // • resilience: retries with backoff (lesson 30), timeouts, circuit breakers, // and fallback ui so one failed call doesn't crash the whole app. // • don't overwhelm downstreams. when you have more work than a service (or your // rate limit) can take, bound the flow: // - concurrency limit: run at most n at once (lesson 30 `maplimit`). // - rate limit: cap requests-per-second to respect a 429 budget. // - queue + backpressure: buffer work and let consumers pull at their pace // (p-queue/bullmq in js; streams signal \"slow down\" via `.pause()`/drain). // the goal: steady throughput instead of a thundering herd that trips 5xx. // ── 6. accessibility (a11y) — usable by everyone ───────────────────────────── // • semantic html first (<button>, <nav>, <label>) — it's accessible by default. // • provide alt text, keyboard navigation, visible focus, sufficient contrast. // • use aria only to fill gaps semantic html can't (aria-label, roles, live regions). // • test with a keyboard only and a screen reader. it's also often a legal requirement. // ── 7. internationalization (i18n) ─────────────────────────────────────────── // • don't concatenate translated strings; use a message catalog per locale. // • format with intl (lessons 06/32) — numbers, currency, dates, plurals: const price = new intl.numberformat('de-de', { style: 'currency', currency: 'eur' }); console.log('localized price:', price.format(1234.5)); // => 1.234,50 € /* the production checklist ---------------------------------------------------- * tested · linted · typed · secured · observable (logs+metrics+alerts) · * configurable (env) · resilient (retries/timeouts) · accessible · documented * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. add a 'warn' log call and confirm it prints but 'debug' does not. * 2. extend choosetransport for a 'one-off request' → 'fetch'. * 3. read log_level from env and make the log() threshold respect it. * ------------------------------------------------------------------------- */"},"lessons/49-data-structures.js":{"title":"* 49 · data structures — the containers behind every program","learn":"* the classic computer-science data structures, built in plain js: * • stack (lifo) and queue (fifo) * • linked list * • hash map (how map/objects work under the hood) * • binary tree + binary search tree * • graph (adjacency list) * * why this matters * arrays and objects (lessons 12–16) cover 90% of daily work. but knowing * these structures — when each is fast, and why — is the difference between * o(n) and o(1) code, and it's the backbone of every coding interview. * pair this with lesson 50 (algorithms) and lesson 42 (big-o).","practice":"/* practice ------------------------------------------------------------------- * 1. add a `reverse()` method to linkedlist that flips the chain in place. * 2. use your stack to reverse the characters of a string. * 3. add `min()`/`max()` to the bst (hint: go all the way left / right). * 4. add a directed-edge option to graph (link only a → b, not both ways). * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 49 · data structures — the containers behind every program * ============================================================================= * run: node lessons/49-data-structures.js * * what you'll learn * the classic computer-science data structures, built in plain js: * • stack (lifo) and queue (fifo) * • linked list * • hash map (how map/objects work under the hood) * • binary tree + binary search tree * • graph (adjacency list) * * why this matters * arrays and objects (lessons 12–16) cover 90% of daily work. but knowing * these structures — when each is fast, and why — is the difference between * o(n) and o(1) code, and it's the backbone of every coding interview. * pair this with lesson 50 (algorithms) and lesson 42 (big-o). * ========================================================================== */ // ── 1. stack (lifo — last in, first out) ───────────────────────────────────── // think a stack of plates: you add and remove from the top. used for: undo, // browser back, call stack, balancing brackets, depth-first traversal. class stack { #items = []; push(value) { this.#items.push(value); return this; } // add to top pop() { return this.#items.pop(); } // remove from top peek() { return this.#items.at(-1); } // look, don't remove get size() { return this.#items.length; } get isempty() { return this.#items.length === 0; } } const undo = new stack(); undo.push('type a').push('type b').push('type c'); console.log('stack peek:', undo.peek()); // => type c console.log('stack pop :', undo.pop()); // => type c (last in, first out) console.log('stack pop :', undo.pop()); // => type b // classic use: are the brackets balanced? \"([])\" ✅ \"([)]\" ❌ function balanced(str) { const pairs = { ')': '(', ']': '[', '}': '{' }; const stack = []; for (const ch of str) { if (ch === '(' || ch === '[' || ch === '{') stack.push(ch); else if (ch in pairs) { if (stack.pop() !== pairs[ch]) return false; // mismatch } } return stack.length === 0; // nothing left unclosed } console.log('balanced ([]):', balanced('([])')); // => true console.log('balanced ([):', balanced('([)]')); // => false // ── 2. queue (fifo — first in, first out) ──────────────────────────────────── // think a line at a shop: first to arrive is first served. used for: task // queues, print spoolers, breadth-first traversal, rate limiting. // note: array.shift() is o(n) (it re-indexes). for big queues use two stacks or // a ring buffer. we use shift() here for clarity. class queue { #items = []; enqueue(value) { this.#items.push(value); return this; } // add to back dequeue() { return this.#items.shift(); } // remove from front peek() { return this.#items[0]; } get size() { return this.#items.length; } } const line = new queue(); line.enqueue('ana').enqueue('bob').enqueue('cy'); console.log('queue dequeue:', line.dequeue()); // => ana (first in, first out) console.log('queue peek :', line.peek()); // => bob // ── 3. linked list ─────────────────────────────────────────────────────────── // a chain of nodes; each node holds a value + a pointer to the next node. // strength: o(1) insert/remove at the front (no re-indexing like arrays). // weakness: o(n) to reach the middle (no random access). great teaching tool. class linkedlist { #head = null; #size = 0; prepend(value) { // add to front — o(1) this.#head = { value, next: this.#head }; this.#size++; return this; } append(value) { // add to end — o(n) const node = { value, next: null }; if (!this.#head) { this.#head = node; } else { let cur = this.#head; while (cur.next) cur = cur.next; // walk to the last node cur.next = node; } this.#size++; return this; } toarray() { // walk the chain into an array const out = []; for (let cur = this.#head; cur; cur = cur.next) out.push(cur.value); return out; } get size() { return this.#size; } } const list = new linkedlist(); list.append('b').append('c').prepend('a'); console.log('linked list:', list.toarray()); // => [ 'a', 'b', 'c' ] // ── 4. hash map (how map / objects work under the hood) ────────────────────── // a hash map turns a key into an array index via a hash function, giving ~o(1) // lookup. collisions (two keys → same bucket) are handled by \"chaining\": each // bucket holds a list of [key, value] pairs. (in real code, just use `map`.) class hashmap { // note: this toy keeps a fixed 8 buckets. a real hash map tracks its \"load // factor\" (entries ÷ buckets) and resizes — allocating a bigger bucket array // and re-hashing everything — once it passes ~0.75, so lookups stay o(1) on // average instead of degrading to o(n) as one bucket's chain grows. (use the // built-in `map`, which does all this for you.) #buckets = array.from({ length: 8 }, () => []); #hash(key) { // turn a string into a bucket index let h = 0; for (const ch of string(key)) h = (h * 31 + ch.charcodeat(0)) % this.#buckets.length; return h; } set(key, value) { const bucket = this.#buckets[this.#hash(key)]; const pair = bucket.find((p) => p[0] === key); if (pair) pair[1] = value; // update existing else bucket.push([key, value]); // or add new (collision → same bucket) return this; } get(key) { const bucket = this.#buckets[this.#hash(key)]; return bucket.find((p) => p[0] === key)?.[1]; } } const ages = new hashmap(); ages.set('ana', 30).set('bob', 25); console.log('hashmap get ana:', ages.get('ana')); // => 30 console.log('hashmap get zz :', ages.get('zz')); // => undefined // ── 5. binary search tree (bst) ────────────────────────────────────────────── // a tree where every node has up to two children, and for each node: // left subtree < node < right subtree. // that ordering makes search/insert o(log n) on a balanced tree — like binary // search (lesson 50) but in a structure you can keep adding to. class bst { #root = null; insert(value) { this.#root = this.#insert(this.#root, value); return this; } #insert(node, value) { if (!node) return { value, left: null, right: null }; if (value < node.value) node.left = this.#insert(node.left, value); else if (value > node.value) node.right = this.#insert(node.right, value); return node; // duplicates ignored } has(value) { let node = this.#root; while (node) { if (value === node.value) return true; node = value < node.value ? node.left : node.right; // go one way only } return false; } inorder() { // in-order walk → sorted values const out = []; (function walk(node) { if (!node) return; walk(node.left); out.push(node.value); walk(node.right); })(this.#root); return out; } } const tree = new bst(); [8, 3, 10, 1, 6, 14].foreach((n) => tree.insert(n)); console.log('bst sorted :', tree.inorder()); // => [ 1, 3, 6, 8, 10, 14 ] console.log('bst has 6 :', tree.has(6)); // => true console.log('bst has 7 :', tree.has(7)); // => false // ── 6. graph (adjacency list) ──────────────────────────────────────────────── // a set of nodes (\"vertices\") connected by edges. the adjacency-list form maps // each node → an array of its neighbours. models networks: friends, roads, // dependencies, the web. (traversal — bfs/dfs — is in lesson 50.) class graph { #adj = new map(); addnode(node) { if (!this.#adj.has(node)) this.#adj.set(node, []); return this; } addedge(a, b) { // undirected: link both ways this.addnode(a).addnode(b); this.#adj.get(a).push(b); this.#adj.get(b).push(a); return this; } neighbours(node) { return this.#adj.get(node) ?? []; } get nodes() { return [...this.#adj.keys()]; } } const social = new graph(); social.addedge('ana', 'bob').addedge('ana', 'cy').addedge('bob', 'dee'); console.log(\"graph ana's friends:\", social.neighbours('ana')); // => [ 'bob', 'cy' ] /* which structure, when? ----------------------------------------------------- * stack ......... undo, parsing, depth-first work, the call stack * queue ......... scheduling, buffering, breadth-first work * linked list ... o(1) front insert/remove; teaching pointers * hash map ...... o(1) key→value lookup (you'll usually just use map) * bst ........... kept-sorted data with o(log n) search/insert (balanced) * graph ......... relationships/networks; pair with bfs/dfs (lesson 50) * * big-o recap (lesson 42): array index = o(1), array search = o(n), * set/map lookup = o(1), balanced bst search = o(log n). * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. add a `reverse()` method to linkedlist that flips the chain in place. * 2. use your stack to reverse the characters of a string. * 3. add `min()`/`max()` to the bst (hint: go all the way left / right). * 4. add a directed-edge option to graph (link only a → b, not both ways). * ------------------------------------------------------------------------- */"},"lessons/50-algorithms.js":{"title":"* 50 · algorithms — the problem-solving toolkit","learn":"* the algorithm patterns that show up in real code and every interview: * • searching: linear vs binary search * • sorting: bubble (to learn) vs merge & quick (to use) * • two-pointer & sliding-window techniques * • recursion & dynamic programming (memoization) * • graph traversal: bfs and dfs (uses lesson 49's structures) * * read each one with its big-o (lesson 42) in mind: the goal is rarely \"make it * work\" — it's \"make it work without blowing up as the input grows.\"","practice":"/* practice ------------------------------------------------------------------- * 1. write ispalindrome(str) with the two-pointer technique. * 2. implement insertionsort and compare its output to mergesort. * 3. use bfs to find the shortest path (list of nodes) between two graph nodes. * 4. solve \"climbing stairs\" (1 or 2 steps at a time) with memoized recursion. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 50 · algorithms — the problem-solving toolkit * ============================================================================= * run: node lessons/50-algorithms.js * * what you'll learn * the algorithm patterns that show up in real code and every interview: * • searching: linear vs binary search * • sorting: bubble (to learn) vs merge & quick (to use) * • two-pointer & sliding-window techniques * • recursion & dynamic programming (memoization) * • graph traversal: bfs and dfs (uses lesson 49's structures) * * read each one with its big-o (lesson 42) in mind: the goal is rarely \"make it * work\" — it's \"make it work without blowing up as the input grows.\" * ========================================================================== */ // ── 1. linear search — o(n) ────────────────────────────────────────────────── // check items one by one. works on any array. slow on large data. function linearsearch(arr, target) { for (let i = 0; i < arr.length; i++) if (arr[i] === target) return i; return -1; // not found } console.log('linear:', linearsearch([5, 3, 8, 1], 8)); // => 2 // ── 2. binary search — o(log n) ────────────────────────────────────────────── // much faster, but the array must be sorted. halve the search range each step: // look at the middle, then throw away the half that can't contain the target. function binarysearch(sorted, target) { let lo = 0, hi = sorted.length - 1; while (lo <= hi) { const mid = math.floor((lo + hi) / 2); if (sorted[mid] === target) return mid; if (sorted[mid] < target) lo = mid + 1; // target is in the right half else hi = mid - 1; // target is in the left half } return -1; } console.log('binary:', binarysearch([1, 3, 5, 8, 13, 21], 13)); // => 4 // 1m items: linear ≈ 1,000,000 checks; binary ≈ 20. that's the power of o(log n). // ── 3. bubble sort — o(n²) — learn it, don't ship it ───────────────────────── // repeatedly swap adjacent out-of-order pairs until sorted. easy to understand, // too slow for real data — but it teaches what sorting *is*. function bubblesort(arr) { const a = [...arr]; // copy — don't mutate the caller's array (lesson 12) for (let i = 0; i < a.length; i++) { for (let j = 0; j < a.length - 1 - i; j++) { if (a[j] > a[j + 1]) [a[j], a[j + 1]] = [a[j + 1], a[j]]; // swap } } return a; } console.log('bubble:', bubblesort([5, 2, 9, 1, 5, 6])); // => [1, 2, 5, 5, 6, 9] // ── 4. merge sort — o(n log n) — a real \"divide & conquer\" sort ────────────── // split the array in half, sort each half (recursively), then merge the two // sorted halves. reliable o(n log n) — the kind of algorithm engines use. function mergesort(arr) { if (arr.length <= 1) return arr; // base case const mid = math.floor(arr.length / 2); const left = mergesort(arr.slice(0, mid)); // sort left half const right = mergesort(arr.slice(mid)); // sort right half return merge(left, right); } function merge(left, right) { const out = []; let i = 0, j = 0; while (i < left.length && j < right.length) { // take the smaller front item out.push(left[i] <= right[j] ? left[i++] : right[j++]); } return out.concat(left.slice(i), right.slice(j)); // drain whatever's left } console.log('merge :', mergesort([5, 2, 9, 1, 5, 6])); // => [1, 2, 5, 5, 6, 9] // (in practice: arr.tosorted() — lesson 38. these show how sorting works.) // ── 5. quick sort — o(n log n) average — pick a pivot, partition ───────────── // choose a \"pivot\", put smaller items left and larger right, recurse on each. // ⚠️ two simplifications for readability: // • pivot = first element. on already-sorted input (or many duplicate keys) // that gives lopsided partitions → o(n²). real implementations pick a // random/median-of-three pivot (and 3-way partition) to avoid that. // • this builds new arrays with filter + spread, so it uses o(n) extra // memory. a production quicksort partitions in place (swapping within the // same array) for o(log n) stack space and no copies. function quicksort(arr) { if (arr.length <= 1) return arr; const [pivot, ...rest] = arr; const smaller = rest.filter((n) => n < pivot); const larger = rest.filter((n) => n >= pivot); return [...quicksort(smaller), pivot, ...quicksort(larger)]; } console.log('quick :', quicksort([5, 2, 9, 1, 5, 6])); // => [1, 2, 5, 5, 6, 9] // ── 6. two-pointer technique ───────────────────────────────────────────────── // walk two indices toward each other. turns many o(n²) problems into o(n). // example: does a sorted array contain two numbers that sum to a target? function haspairsum(sorted, target) { let lo = 0, hi = sorted.length - 1; while (lo < hi) { const sum = sorted[lo] + sorted[hi]; if (sum === target) return [sorted[lo], sorted[hi]]; if (sum < target) lo++; // need a bigger sum → move left pointer up else hi--; // need a smaller sum → move right pointer down } return null; } console.log('two-pointer:', haspairsum([1, 3, 4, 7, 9], 11)); // => [4, 7] // ── 7. sliding window ──────────────────────────────────────────────────────── // keep a moving \"window\" over the data instead of recomputing from scratch. // example: max sum of any k consecutive numbers — o(n) instead of o(n*k). function maxwindowsum(arr, k) { let windowsum = 0; for (let i = 0; i < k; i++) windowsum += arr[i]; // first window let best = windowsum; for (let i = k; i < arr.length; i++) { windowsum += arr[i] - arr[i - k]; // slide: add new, drop oldest best = math.max(best, windowsum); } return best; } console.log('sliding window:', maxwindowsum([2, 1, 5, 1, 3, 2], 3)); // => 9 (5+1+3) // ── 8. dynamic programming (memoization) ───────────────────────────────────── // naive recursive fibonacci is o(2ⁿ) — it recomputes the same values endlessly. // dp = remember sub-results so each is computed once. drops it to o(n). function fib(n, memo = new map()) { if (n <= 1) return n; if (memo.has(n)) return memo.get(n); // already solved → reuse const result = fib(n - 1, memo) + fib(n - 2, memo); memo.set(n, result); return result; } console.log('fib(40):', fib(40)); // => 102334155 (instant, thanks to memoization) // ── 9. graph traversal — bfs & dfs ─────────────────────────────────────────── // visit every node reachable from a start. bfs uses a queue (lesson 49) and // explores level by level (→ shortest path in unweighted graphs). dfs uses a // stack / recursion and dives deep first. const graph = { a: ['b', 'c'], b: ['a', 'd', 'e'], c: ['a', 'f'], d: ['b'], e: ['b', 'f'], f: ['c', 'e'], }; function bfs(graph, start) { const visited = new set([start]); const queue = [start]; // fifo const order = []; while (queue.length) { const node = queue.shift(); // take from the front order.push(node); for (const next of graph[node]) { if (!visited.has(next)) { visited.add(next); queue.push(next); } } } return order; } function dfs(graph, start, visited = new set(), order = []) { visited.add(start); order.push(start); for (const next of graph[start]) { if (!visited.has(next)) dfs(graph, next, visited, order); // dive deep first } return order; } console.log('bfs from a:', bfs(graph, 'a')); // => [ 'a', 'b', 'c', 'd', 'e', 'f' ] console.log('dfs from a:', dfs(graph, 'a')); // => [ 'a', 'b', 'd', 'e', 'f', 'c' ] /* complexity cheat sheet ----------------------------------------------------- * linear search ... o(n) binary search ... o(log n) (needs sorted) * bubble sort ..... o(n²) merge/quick ..... o(n log n) * two-pointer ..... o(n) sliding window .. o(n) * naive fib ....... o(2ⁿ) memoized fib .... o(n) * bfs / dfs ....... o(v + e) (vertices + edges) * * interview playbook: * • sorted input? → think binary search / two-pointer. * • \"subarray/substring of length k\"? → sliding window. * • overlapping sub-problems? → memoize (dp). * • graph/tree/grid? → bfs (shortest path) or dfs (explore all). * • always state the big-o of your solution out loud. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. write ispalindrome(str) with the two-pointer technique. * 2. implement insertionsort and compare its output to mergesort. * 3. use bfs to find the shortest path (list of nodes) between two graph nodes. * 4. solve \"climbing stairs\" (1 or 2 steps at a time) with memoized recursion. * ------------------------------------------------------------------------- */"},"lessons/51-binary-data.js":{"title":"* 51 · binary data — bytes, buffers, and files","learn":"* how javascript handles raw bytes — not just strings and numbers: * • arraybuffer — a fixed block of memory * • typed arrays (uint8array, float64array, …) — views over that memory * • dataview — read/write mixed types at exact byte offsets * • blob / file — chunks of binary data in the browser * • formdata — sending files and fields to a server * • textencoder / textdecoder — text ↔ bytes * • sharedarraybuffer + atomics — memory shared across threads * * why this matters * file uploads/downloads, images, audio, websockets (lesson 48), streaming * fetch responses, webgl, and webassembly all move bytes. strings can't * represent that efficiently — typed arrays can.","practice":"/* practice ------------------------------------------------------------------- * 1. make a uint8array of [72,105] and textdecoder.decode it (what word?). * 2. use a dataview to store two float32 values in one 8-byte buffer, read back. * 3. (browser) build a csv string, wrap it in a blob, and download it. * 4. (browser) add a file <input>, read the chosen file with file.text(). * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 51 · binary data — bytes, buffers, and files * ============================================================================= * run: node lessons/51-binary-data.js * (the blob/file/formdata parts are browser apis — shown as comments; * the arraybuffer/typedarray parts run in node too.) * * what you'll learn * how javascript handles raw bytes — not just strings and numbers: * • arraybuffer — a fixed block of memory * • typed arrays (uint8array, float64array, …) — views over that memory * • dataview — read/write mixed types at exact byte offsets * • blob / file — chunks of binary data in the browser * • formdata — sending files and fields to a server * • textencoder / textdecoder — text ↔ bytes * • sharedarraybuffer + atomics — memory shared across threads * * why this matters * file uploads/downloads, images, audio, websockets (lesson 48), streaming * fetch responses, webgl, and webassembly all move bytes. strings can't * represent that efficiently — typed arrays can. * ========================================================================== */ // ── 1. arraybuffer — a raw block of memory ─────────────────────────────────── // an arraybuffer is just n bytes. you can't read it directly — you need a view. const buffer = new arraybuffer(8); // 8 bytes, all zero console.log('buffer bytelength:', buffer.bytelength); // => 8 // ── 2. typed arrays — views over a buffer ──────────────────────────────────── // a typed array reads the buffer's bytes as numbers of a fixed size/type. // uint8array → 1 byte, 0..255 (the workhorse for raw bytes) // int32array → 4 bytes, signed integers // float64array → 8 bytes, decimals (same precision as a normal js number) const bytes = new uint8array(buffer); // view the 8-byte buffer as 8 × uint8 bytes[0] = 255; bytes[1] = 256; // wraps! 256 doesn't fit in a byte → becomes 0 bytes[2] = 42; console.log('uint8 view:', bytes); // => uint8array(8) [ 255, 0, 42, 0, 0, 0, 0, 0 ] // multiple views can share one buffer — they read the same bytes differently: const ints = new int32array(buffer); // 8 bytes → two 32-bit ints console.log('same bytes as int32:', ints); // values depend on byte order // typed arrays have most array methods (map/filter/reduce, lesson 13) but a // fixed length and a single number type — that's what makes them fast & compact. const doubled = uint8array.from([1, 2, 3], (n) => n * 2); console.log('typed map:', doubled); // => uint8array(3) [ 2, 4, 6 ] // ── 3. dataview — precise, mixed-type access ───────────────────────────────── // when a binary format packs different types at known offsets (file headers, // network protocols), dataview reads/writes them exactly — and lets you control // \"endianness\" (byte order). const dv = new dataview(new arraybuffer(8)); dv.setint16(0, 300); // write a 16-bit int at byte 0 dv.setfloat32(2, 3.14, true); // write a 32-bit float at byte 2 (true = little-endian) console.log('dataview int16 :', dv.getint16(0)); // => 300 console.log('dataview f32 :', dv.getfloat32(2, true).tofixed(2)); // => 3.14 // ── 4. text ↔ bytes (textencoder / textdecoder) ────────────────────────────── // strings are utf-16 in memory; on the wire/disk text is usually utf-8 bytes. const encoder = new textencoder(); const encoded = encoder.encode('hi 👋'); // string → uint8array of utf-8 bytes console.log('encoded bytes:', encoded); // emoji takes 4 bytes const decoder = new textdecoder(); console.log('decoded back:', decoder.decode(encoded)); // => hi 👋 // ── 5. blob & file (browser) — chunks of binary data ───────────────────────── /* a blob is an immutable bag of bytes with a mime type. a file is a blob with a * name (what you get from <input type=\"file\">). both are how the browser holds * images, downloads, and uploads. * * // make a blob and trigger a download: * const blob = new blob(['name,score\\nana,10'], { type: 'text/csv' }); * const url = url.createobjecturl(blob); * const a = object.assign(document.createelement('a'), * { href: url, download: 'data.csv' }); * a.click(); * url.revokeobjecturl(url); // free the memory when done * * // read a file the user picked: * input.addeventlistener('change', async () => { * const file = input.files[0]; // a file (blob + name + size) * const text = await file.text(); // read as string * const bytes = await file.arraybuffer(); // read as raw bytes * console.log(file.name, file.size, text); * }); */ // ── 6. formdata (browser) — send files + fields to a server ─────────────────── /* formdata builds a multipart request body — the standard way to upload files * alongside text fields. fetch (lesson 26) sets the right headers automatically. * * const form = new formdata(); * form.append('username', 'ana'); * form.append('avatar', fileinput.files[0]); // a file/blob * await fetch('/upload', { method: 'post', body: form }); * // ^ do not set content-type yourself — the browser adds the boundary. * * // formdata can also read an entire <form> at once: * const form2 = new formdata(document.queryselector('form')); * for (const [key, value] of form2) console.log(key, value); */ // ── 7. streaming binary (concept) ──────────────────────────────────────────── /* large responses don't have to load all at once. fetch bodies are streams of * uint8array chunks — read them progressively (great for progress bars): * * const res = await fetch('/big-file'); * const reader = res.body.getreader(); // a stream of byte chunks * let received = 0; * while (true) { * const { done, value } = await reader.read(); // value = uint8array chunk * if (done) break; * received += value.length; * console.log('received', received, 'bytes'); * } * (in node, see streams in lesson 46 — same idea, different api.) */ // ── 8. sharedarraybuffer + atomics — memory shared between threads ──────────── // a normal arraybuffer is copied (structured clone) when sent to a web worker // (lesson 47) / node worker_thread (lesson 46) — unless you explicitly transfer // it (move it without copying, which detaches the original). a sharedarraybuffer // is the same memory seen by both threads at once — true shared state, no copying. // (browsers require special coop/coep headers to enable it, for security.) const shared = new sharedarraybuffer(8); // 8 bytes, shareable across threads const sharedview = new int32array(shared); // when two threads touch the same memory you get race conditions. `atomics` // provides operations that are guaranteed to complete without interruption: atomics.store(sharedview, 0, 100); // safely write slot 0 atomics.add(sharedview, 0, 5); // atomic read-modify-write → 105 console.log('atomics value:', atomics.load(sharedview, 0)); // => 105 // atomics.wait / atomics.notify let one thread sleep until another signals it — // the building block of locks and cross-thread coordination: // // worker: atomics.wait(sharedview, 0, 105); // block while slot 0 === 105 // // main: atomics.store(sharedview, 0, 0); atomics.notify(sharedview, 0); // ⚠️ this is advanced/rare. you only need it for high-performance parallel work // (image/audio processing, simulations, wasm threads). for normal worker // communication, plain postmessage (lesson 47) is simpler and safer. /* mental model --------------------------------------------------------------- * arraybuffer = the memory (bytes). typed array / dataview = how you read it. * sharedarraybuffer = memory shared across threads; atomics = safe access to it. * blob/file = bytes + a type/name (browser). formdata = a way to send them. * textencoder/decoder = the bridge between text and utf-8 bytes. * * reach for these only when you actually handle binary: uploads, media, * protocols, webgl/wasm. for everyday data, json + objects (lessons 14/25) * are simpler and correct. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. make a uint8array of [72,105] and textdecoder.decode it (what word?). * 2. use a dataview to store two float32 values in one 8-byte buffer, read back. * 3. (browser) build a csv string, wrap it in a blob, and download it. * 4. (browser) add a file <input>, read the chosen file with file.text(). * ------------------------------------------------------------------------- */"},"lessons/52-bigint-and-language-corners.js":{"title":"* 52 · bigint & language corners","learn":"* the last few language features that round out \"i know all of javascript\": * • bigint — integers bigger than number can safely hold * • object.fromentries — build an object from key/value pairs * • array.prototype.flatmap — map + flatten in one step * • labeled statements — break/continue an outer loop * • eval & the function constructor — running code from a string (and why * you almost never should) * * these are niche — you won't reach for them daily — but knowing they exist * (and their gotchas) is the difference between \"most of js\" and \"all of js\".","practice":"/* practice ------------------------------------------------------------------- * 1. compute 100! (factorial) with bigint — impossible to do exactly with number. * 2. use object.entries + map + object.fromentries to uppercase every value * of { a: 'x', b: 'y' }. * 3. use flatmap to turn [{tags:['js','ts']},{tags:['css']}] into one tag list. * 4. use a labeled loop to find the first pair (i,j) in two arrays that sums to 7. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 52 · bigint & language corners * ============================================================================= * run: node lessons/52-bigint-and-language-corners.js * * what you'll learn * the last few language features that round out \"i know all of javascript\": * • bigint — integers bigger than number can safely hold * • object.fromentries — build an object from key/value pairs * • array.prototype.flatmap — map + flatten in one step * • labeled statements — break/continue an outer loop * • eval & the function constructor — running code from a string (and why * you almost never should) * * these are niche — you won't reach for them daily — but knowing they exist * (and their gotchas) is the difference between \"most of js\" and \"all of js\". * ========================================================================== */ // ── 1. bigint — arbitrary-precision integers ───────────────────────────────── // regular numbers are 64-bit floats. they can only represent integers exactly // up to number.max_safe_integer. past that, math silently goes wrong: console.log(number.max_safe_integer); // => 9007199254740991 (2^53 - 1) console.log(9007199254740991 + 1); // => 9007199254740992 ✅ console.log(9007199254740991 + 2); // => 9007199254740992 ❌ (should be ...93!) // bigint fixes this — write `n` after an integer literal, or call bigint(): const big = 9007199254740991n; console.log(big + 2n); // => 9007199254740993n ✅ exact console.log(bigint(42), typeof 42n); // => 42n 'bigint' // arithmetic works as usual — but division truncates (bigint has no decimals): console.log(10n / 3n); // => 3n (not 3.333…) console.log(2n ** 64n); // => 18446744073709551616n (huge, exact) // ⚠️ you cannot mix bigint and number in math — it throws on purpose: try { 1n + 1; } catch (e) { console.log('mix error:', e.message); } // typeerror console.log(1n + bigint(1)); // => 2n (convert first) // comparisons do work across types (no error): console.log(2n > 1, 2n === 2, 2n == 2); // => true false true // ^ === is false: different types (bigint vs number) // gotchas: no math.* (math.sqrt(4n) throws); json.stringify can't serialize it: try { json.stringify({ id: 5n }); } catch (e) { console.log('json error:', e.message); } // fix: convert to string in a replacer → json.stringify(obj, (k,v) => // typeof v === 'bigint' ? v.tostring() : v) // use cases: database bigint ids, twitter/discord \"snowflake\" ids, nanosecond // timestamps, cryptography — anywhere integers exceed 2^53. // ── 2. object.fromentries — [[k,v]] → { k: v } ─────────────────────────────── // the inverse of object.entries (lesson 14). turns pairs back into an object. const pairs = [['name', 'ana'], ['age', 30]]; console.log(object.fromentries(pairs)); // => { name: 'ana', age: 30 } // killer combo: transform an object by going object → entries → map → object. const prices = { apple: 1, pear: 2 }; const doubled = object.fromentries( object.entries(prices).map(([k, v]) => [k, v * 2]) ); console.log(doubled); // => { apple: 2, pear: 4 } // also converts a map (lesson 16) or urlsearchparams (lesson 26) into an object: console.log(object.fromentries(new map([['a', 1]]))); // => { a: 1 } // ── 3. array.prototype.flatmap — map, then flatten one level ────────────────── // equivalent to arr.map(fn).flat(1), but in one call. great when each item // maps to zero, one, or many results. console.log([1, 2, 3].flatmap((n) => [n, n * 10])); // => [1, 10, 2, 20, 3, 30] // return [] to drop an item, [x] to keep it → map + filter in one step: console.log([1, -2, 3, -4].flatmap((n) => (n > 0 ? [n] : []))); // => [1, 3] // split sentences into words across an array: console.log(['a b', 'c d'].flatmap((s) => s.split(' '))); // => ['a','b','c','d'] // (note: flatmap only flattens one level; use .flat(infinity) for deep nesting.) // ── 4. labeled statements — break/continue an outer loop ───────────────────── // by default break/continue affect the nearest loop. a label lets you target an // outer one — handy for breaking out of nested loops without a flag variable. outer: for (let i = 0; i < 3; i++) { for (let j = 0; j < 3; j++) { if (i + j === 3) { console.log(`breaking outer at i=${i}, j=${j}`); break outer; // jumps all the way out, not just the inner loop } } } // `continue label` similarly skips to the next iteration of the labeled loop. // use sparingly — often a helper function with an early `return` is clearer. // ── 5. eval & the function constructor — code from strings (avoid!) ─────────── // eval() runs a string as code in the current scope. it works… console.log(eval('2 + 3')); // => 5 // …but it's a security hole (runs any code, incl. attacker input), it's slow // (defeats engine optimizations), and it can read/modify your local variables. // rule: never eval untrusted input. you almost never need eval at all — // json.parse for data, optional chaining/bracket access for dynamic props. // the function constructor is slightly less dangerous: it builds a function from // a string but runs in the global scope (it can't see your locals): const addfn = new function('a', 'b', 'return a + b'); console.log(addfn(4, 5)); // => 9 // same security/perf caveats apply. legit uses are rare (templating engines, // sandboxes, repls) — for everyday code, treat both as \"do not use\". /* quick reference ------------------------------------------------------------ * bigint ............ 123n / bigint(x) — exact integers past 2^53; no mixing * with number, no decimals, no math, no direct json. * object.fromentries pairs → object; pair with object.entries to transform. * flatmap ........... map + flat(1); return [] to drop, [x] to keep. * label: loop ....... break/continue an outer loop by name. * eval/function ..... run strings as code — security + perf risk. avoid. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. compute 100! (factorial) with bigint — impossible to do exactly with number. * 2. use object.entries + map + object.fromentries to uppercase every value * of { a: 'x', b: 'y' }. * 3. use flatmap to turn [{tags:['js','ts']},{tags:['css']}] into one tag list. * 4. use a labeled loop to find the first pair (i,j) in two arrays that sums to 7. * ------------------------------------------------------------------------- */"},"lessons/53-internationalization.js":{"title":"* 53 · internationalization (the full intl api)","learn":"* the built-in `intl` api formats data the way each language/region expects — * no libraries needed. you met numberformat (lesson 06) & datetimeformat * (lesson 33); here are the rest: * • intl.collator — locale-aware sorting & comparison * • intl.pluralrules — pick the right plural form * • intl.relativetimeformat — \"3 days ago\", \"in 2 hours\" * • intl.listformat — \"a, b, and c\" * • intl.segmenter — split text into words/sentences (any language) * * big idea: never hand-build dates, numbers, plurals, or \"x ago\" strings — the * platform already knows the rules for ~hundreds of locales. (see lesson 48 for * i18n in the bigger picture: translations, rtl, etc.)","practice":"/* practice ------------------------------------------------------------------- * 1. sort ['café','car','cab'] with an intl.collator and compare to a plain sort. * 2. write likes(n) → \"1 like\" / \"n likes\" using intl.pluralrules. * 3. format \"in 5 minutes\" and \"2 weeks ago\" with intl.relativetimeformat. * 4. join ['html','css','js'] as \"html, css, and js\" with intl.listformat. * 5. use intl.segmenter to correctly count the characters in '👍🏽🎉'. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 53 · internationalization (the full intl api) * ============================================================================= * run: node lessons/53-internationalization.js * * what you'll learn * the built-in `intl` api formats data the way each language/region expects — * no libraries needed. you met numberformat (lesson 06) & datetimeformat * (lesson 33); here are the rest: * • intl.collator — locale-aware sorting & comparison * • intl.pluralrules — pick the right plural form * • intl.relativetimeformat — \"3 days ago\", \"in 2 hours\" * • intl.listformat — \"a, b, and c\" * • intl.segmenter — split text into words/sentences (any language) * * big idea: never hand-build dates, numbers, plurals, or \"x ago\" strings — the * platform already knows the rules for ~hundreds of locales. (see lesson 48 for * i18n in the bigger picture: translations, rtl, etc.) * ========================================================================== */ // ── recap: the two you already know ────────────────────────────────────────── console.log(new intl.numberformat('en-in', { style: 'currency', currency: 'inr' }).format(250000)); // => ₹2,50,000.00 (note the indian digit grouping — intl handles it) console.log(new intl.datetimeformat('en-gb', { datestyle: 'full' }).format(new date('2026-06-05'))); // => friday, 5 june 2026 // ── 1. intl.collator — sort/compare the way a language does ─────────────────── // string sort with < or default .sort() is by code-point, which is wrong for // accents and non-english alphabets. collator sorts correctly per locale. const words = ['zebra', 'apple', 'ärger', 'apple pie', 'apfel']; const collator = new intl.collator('de', { sensitivity: 'base' }); // german rules console.log('collator sort:', [...words].sort(collator.compare)); // 'ä' sorts near 'a' (correct in german) — a naive sort would misplace it. // `numeric: true` makes \"file2\" come before \"file10\" (human/natural order): const files = ['file10', 'file2', 'file1']; console.log('natural sort:', [...files].sort(new intl.collator(undefined, { numeric: true }).compare)); // => [ 'file1', 'file2', 'file10' ] (not file1, file10, file2) // ── 2. intl.pluralrules — choose the correct plural category ────────────────── // english has 2 forms (1 item / n items). other languages have up to 6. don't // hard-code `n === 1 ? 'item' : 'items'` — ask pluralrules which form to use. const enplural = new intl.pluralrules('en-us'); function items(n) { const form = enplural.select(n); // 'one' | 'other' (for english) const label = { one: 'item', other: 'items' }[form]; return `${n} ${label}`; } console.log(items(1), '/', items(5)); // => 1 item / 5 items // ordinals too (1st, 2nd, 3rd, 4th): const ordinal = new intl.pluralrules('en-us', { type: 'ordinal' }); const suffix = { one: 'st', two: 'nd', few: 'rd', other: 'th' }; console.log([1, 2, 3, 4, 11, 21].map((n) => `${n}${suffix[ordinal.select(n)]}`).join(' ')); // => 1st 2nd 3rd 4th 11th 21st // ── 3. intl.relativetimeformat — \"3 days ago\" / \"in 2 hours\" ───────────────── // stop writing your own \"time ago\" helper — this one is locale-correct. const rtf = new intl.relativetimeformat('en', { numeric: 'auto' }); console.log(rtf.format(-1, 'day')); // => yesterday ('auto' → words) console.log(rtf.format(3, 'day')); // => in 3 days console.log(rtf.format(-2, 'hour')); // => 2 hours ago // a tiny helper: turn a past date into a friendly relative string. function timeago(date) { // (demo uses a fixed \"now\" for reproducible output; real code uses date.now().) const seconds = math.round((date - new date('2026-06-05t12:00:00')) / 1000); const units = [['day', 86400], ['hour', 3600], ['minute', 60], ['second', 1]]; for (const [unit, secs] of units) { if (math.abs(seconds) >= secs || unit === 'second') { return rtf.format(math.round(seconds / secs), unit); } } } console.log(timeago(new date('2026-06-04t12:00:00'))); // => yesterday // ── 4. intl.listformat — join a list the way humans write it ───────────────── // \"a, b, and c\" (note the oxford comma + \"and\") — and it localizes. const fruits = ['apples', 'oranges', 'pears']; console.log(new intl.listformat('en', { type: 'conjunction' }).format(fruits)); // => apples, oranges, and pears console.log(new intl.listformat('en', { type: 'disjunction' }).format(fruits)); // => apples, oranges, or pears // ── 5. intl.segmenter — split text into words/sentences/graphemes ──────────── // \"just split on spaces\" breaks for many languages (chinese/japanese have no // spaces) and for emoji. segmenter splits text correctly anywhere. const seg = new intl.segmenter('en', { granularity: 'word' }); const segments = [...seg.segment('hello, world! 👋')]; const realwords = segments.filter((s) => s.iswordlike).map((s) => s.segment); console.log('words:', realwords); // => [ 'hello', 'world' ] // grapheme granularity counts user-perceived characters (emoji = 1, not many): const graphemes = [...new intl.segmenter().segment('a👨‍👩‍👧b')]; console.log('grapheme count:', graphemes.length); // => 3 ('.length' would say 8+) /* when to reach for each ------------------------------------------------------ * numberformat ...... currency, percent, units, digit grouping (lesson 06) * datetimeformat .... locale dates & times (lesson 33) * collator .......... sorting/searching strings correctly (accents, numeric) * pluralrules ....... \"1 item\" vs \"5 items\", ordinals (1st/2nd/3rd) * relativetimeformat \"3 days ago\", \"in 2 hours\" * listformat ........ \"a, b, and c\" * segmenter ......... counting/splitting words & characters in any language * * all of intl is built into node and every modern browser — zero dependencies. * --------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. sort ['café','car','cab'] with an intl.collator and compare to a plain sort. * 2. write likes(n) → \"1 like\" / \"n likes\" using intl.pluralrules. * 3. format \"in 5 minutes\" and \"2 weeks ago\" with intl.relativetimeformat. * 4. join ['html','css','js'] as \"html, css, and js\" with intl.listformat. * 5. use intl.segmenter to correctly count the characters in '👍🏽🎉'. * ------------------------------------------------------------------------- */"},"lessons/54-modern-auth.js":{"title":"* 54 · modern authentication","learn":"* • authn vs authz — who you are vs what you're allowed to do * • storing passwords safely with a slow, salted kdf (scrypt/bcrypt/argon2) * • sessions vs tokens (jwt): the trade-offs, and how to choose * • jwt anatomy, cookie security flags, oauth/oidc, passkeys, refresh tokens * * auth is the front door of every app — get it wrong and nothing else matters. * lesson 40 grazed tokens & cookies; this goes deeper. rule #1: don't roll your * own crypto or your own auth protocol — use vetted libraries and providers.","practice":"/* practice ------------------------------------------------------------------- * 1. write decodejwtpayload(token) that returns the parsed payload object * from a jwt string (split on '.', base64url-decode the middle part). * 2. write isexpired(payload, nowseconds) using the jwt `exp` claim (seconds). * return true when the token is past its expiry. * 3. extend chooseauth() so a 'thirdpartyapi' need also returns 'token'. * 4. using scryptsync + timingsafeequal, write needsrehash(stored) that * returns true when a stored hash's derived-key length is below 32 bytes * (a signal to upgrade the user's hash on next login). * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 54 · modern authentication * ============================================================================= * run: node lessons/54-modern-auth.js * * what you'll learn * • authn vs authz — who you are vs what you're allowed to do * • storing passwords safely with a slow, salted kdf (scrypt/bcrypt/argon2) * • sessions vs tokens (jwt): the trade-offs, and how to choose * • jwt anatomy, cookie security flags, oauth/oidc, passkeys, refresh tokens * * auth is the front door of every app — get it wrong and nothing else matters. * lesson 40 grazed tokens & cookies; this goes deeper. rule #1: don't roll your * own crypto or your own auth protocol — use vetted libraries and providers. * ========================================================================== */ const { scryptsync, randombytes, timingsafeequal } = require('node:crypto'); // ── 1. authn vs authz ──────────────────────────────────────────────────────── // two different questions people constantly conflate: // • authentication (authn) = who are you? proving identity (login). // • authorization (authz) = what may you do? permissions/roles (access). // you authenticate once, then authorize every request. a logged-in user is not // automatically allowed to do everything — check permissions on each action. function can(user, action) { const policy = { admin: ['read', 'write', 'delete'], member: ['read', 'write'] }; return (policy[user.role] ?? []).includes(action); } const ana = { name: 'ana', role: 'member' }; console.log(can(ana, 'read')); // => true console.log(can(ana, 'delete')); // => false (authenticated, but not authorized) // ── 2. passwords — never store plaintext, hash with a slow salted kdf ───────── // if your db leaks, plaintext passwords are an instant catastrophe. even a fast // hash (md5/sha256) is broken: gpus guess billions/sec. use a slow, salted // password kdf: bcrypt, argon2, or scrypt. two ideas do the work: // • salt — random per-user bytes mixed in, so identical passwords hash // differently and precomputed \"rainbow tables\" are useless. // • slow — deliberately expensive (cost factor) so brute-force is painful. // below: a runnable scrypt hash + verify with node:crypto. store `salt:hash`. // ⚠️ production: use the async `scrypt` (scryptsync blocks the event loop on a // server), tune the cost params to current owasp guidance, or prefer a vetted // library (argon2id is the modern first choice). this is a teaching demo. function hashpassword(password) { const salt = randombytes(16); const hash = scryptsync(password, salt, 32); // 32-byte derived key return `${salt.tostring('hex')}:${hash.tostring('hex')}`; } function verifypassword(password, stored) { const [salthex, hashhex] = stored.split(':'); const expected = buffer.from(hashhex, 'hex'); const actual = scryptsync(password, buffer.from(salthex, 'hex'), 32); return timingsafeequal(actual, expected); // constant-time compare } const record = hashpassword('correct horse battery staple'); console.log('stored looks like salt:hash =>', record.slice(0, 12) + '…'); // => stored looks like salt:hash => <first 12 chars of salt:hash>… console.log(verifypassword('correct horse battery staple', record)); // => true console.log(verifypassword('wrong password', record)); // => false // ── 3. constant-time comparison — don't leak secrets via timing ────────────── // `a === b` on strings/buffers can return early at the first mismatched byte. // an attacker measuring response time can recover a secret byte-by-byte. for // secrets (tokens, macs, hashes) compare in constant time — same work no matter // where the first difference is. node:crypto gives you timingsafeequal: function safeequal(a, b) { const ba = buffer.from(a), bb = buffer.from(b); if (ba.length !== bb.length) return false; // length isn't secret return timingsafeequal(ba, bb); } console.log(safeequal('token-abc', 'token-abc')); // => true console.log(safeequal('token-abc', 'token-xyz')); // => false // ── 4. sessions vs tokens — two ways to \"stay logged in\" ───────────────────── // after login the server must remember you across requests. two models: // • sessions (stateful): server stores session data; the cookie holds only an // opaque id. easy to revoke (delete the row) — but needs a session store. // • tokens (stateless, jwt): a self-contained signed token carries the claims. // no server lookup — but you can't easily revoke before it expires. // trade-off in one line: sessions are easy to revoke / harder to scale; tokens // scale across services / are harder to revoke. a blunt decision helper: function chooseauth({ multipleservices, needinstantrevoke, mobileorapi }) { if (needinstantrevoke) return 'session'; // logout must be immediate if (multipleservices || mobileorapi) return 'token'; // stateless across services return 'session'; // default: simplest } console.log(chooseauth({ needinstantrevoke: true })); // => session console.log(chooseauth({ multipleservices: true })); // => token console.log(chooseauth({ mobileorapi: true })); // => token console.log(chooseauth({})); // => session // ── 5. jwt anatomy — header.payload.signature (base64url) ──────────────────── // a jwt is three base64url parts joined by dots: xxxxx.yyyyy.zzzzz // • header — { alg, typ } which signing algorithm // • payload — the claims (sub, exp, role…). not encrypted — anyone can read. // • signature — proves it wasn't tampered with, computed with a secret key. // \"signed, not encrypted\" → never put secrets/passwords in a jwt payload. const samplejwt = 'eyjhbgcioijiuzi1niisinr5cci6ikpxvcj9' + // header '.eyjzdwiioij1c2vyxzqyiiwicm9szsi6imfkbwluiiwizxhwijoxnzawmdawmdawfq' + // payload '.c2lnbmf0dxjl'; // signature (fake here) const parts = samplejwt.split('.'); console.log('parts:', parts.length); // => parts: 3 const decode = (p) => json.parse(buffer.from(p, 'base64url').tostring()); console.log('header :', decode(parts[0])); // => header : { alg: 'hs256', typ: 'jwt' } console.log('payload:', decode(parts[1])); // => payload: { sub: 'user_42', role: 'admin', exp: 1700000000 } // ⚠️ decoding ≠ trusting. on the server you must verify the signature with your // secret/public key (e.g. jsonwebtoken's verify, or jose) and check `exp`. // anyone can craft a payload; only signature verification makes it trustworthy. // ── 6. cookie security flags — where the credential actually lives ─────────── // however you authenticate, the browser credential belongs in a hardened cookie: // set-cookie: sid=…; httponly; secure; samesite=lax; path=/ // • httponly — js can't read it (document.cookie) → an xss bug can't steal it. // • secure — sent only over https → not exposed on plaintext connections. // • samesite — lax/strict stops the cookie riding along on cross-site requests // → a strong csrf defense (lesson 40 §2). // ❌ the classic mistake: storing a jwt in localstorage. localstorage is readable // by any script on the page, so one xss = stolen token. prefer an httponly // cookie; if you must use a token in js, keep it short-lived (see §8). // ── 7. oauth 2.0 / oidc — \"log in with google\", don't roll your own ────────── // oauth 2.0 = delegated authorization (let app a act on a resource for the user). // openid connect (oidc) adds an identity layer on top (an id_token = who you are). // the authorization-code flow, in plain steps: const oauthflow = [ '1. app redirects user to the provider (google) with client_id + scopes', '2. user authenticates & consents on the provider (your app never sees the pw)', '3. provider redirects back with a one-time ?code=…', '4. app exchanges code (+ client_secret) server-side for access/id tokens', '5. app uses the access token to call apis / reads the id_token for identity', ]; oauthflow.foreach((s) => console.log(s)); // => 1. app redirects user to the provider (google) with client_id + scopes // => 2. user authenticates & consents on the provider (your app never sees the pw) // => 3. provider redirects back with a one-time ?code=… // => 4. app exchanges code (+ client_secret) server-side for access/id tokens // => 5. app uses the access token to call apis / reads the id_token for identity // use pkce for public clients (spas/mobile) and a `state` param against csrf. // don't implement the protocol yourself — use a library/provider (auth0, clerk, // next-auth, passport, keycloak). auth is a minefield; lean on vetted tooling. // ── 8. refresh tokens & rotation — short access, long refresh ──────────────── // best practice splits credentials by lifetime: // • access token — short-lived (minutes). used on every api call. if leaked, // it expires fast, limiting the blast radius. // • refresh token — longer-lived, kept in an httponly cookie. trades itself // for a new access token when the old one expires (no re-login). // rotation: each refresh issues a new refresh token and invalidates the old one; // if an already-used (stolen) one is replayed, you detect theft and revoke the // whole family. logout = delete the session / revoke the refresh token server-side // (you can't \"unsign\" a still-valid access jwt — hence keep it short). let serverepoch = 1; // bump this to invalidate all access tokens at once function issueaccesstoken(userid) { return { userid, epoch: serverepoch, ttl: '15m' }; } // ttl is illustrative; the epoch is what we actually verify below function isstillvalid(tok) { return tok.epoch === serverepoch; } const access = issueaccesstoken('user_42'); console.log('valid before logout:', isstillvalid(access)); // => valid before logout: true serverepoch++; // \"log out everywhere\" / rotate the signing epoch console.log('valid after logout:', isstillvalid(access)); // => valid after logout: false // ── 9. passkeys / webauthn — the passwordless 2026 direction ───────────────── // passkeys (built on the webauthn standard) replace passwords with public-key // crypto. at signup the device generates a key pair; the server stores only the // public key. to log in, the device signs a server challenge with the private // key (unlocked by face id / fingerprint / pin). the private key never leaves // the device and is bound to the site's origin, so passkeys are: // • phishing-resistant — a fake site can't get a signature for the real origin. // • nothing reusable to steal — the server holds only a public key. // • syncable across your devices via the platform keychain (device-bound // hardware keys are the exception — those deliberately stay on one device). // browser api: navigator.credentials.create()/get() with publickey options. // this is where modern auth is heading; offer passkeys alongside oauth/passwords. // ── 10. common mistakes checklist ──────────────────────────────────────────── // ❌ plaintext or fast-hash (md5/sha1) passwords ✅ scrypt/bcrypt/argon2 + salt // ❌ jwt in localstorage ✅ httponly + secure cookie // ❌ no `exp` / never-expiring tokens ✅ short access + refresh // ❌ weak/shared signing secret ✅ long random per-env secret // ❌ trusting a decoded jwt without verifying signature ✅ verify on the server // ❌ rolling your own auth protocol/crypto ✅ vetted libs & providers /* practice ------------------------------------------------------------------- * 1. write decodejwtpayload(token) that returns the parsed payload object * from a jwt string (split on '.', base64url-decode the middle part). * 2. write isexpired(payload, nowseconds) using the jwt `exp` claim (seconds). * return true when the token is past its expiry. * 3. extend chooseauth() so a 'thirdpartyapi' need also returns 'token'. * 4. using scryptsync + timingsafeequal, write needsrehash(stored) that * returns true when a stored hash's derived-key length is below 32 bytes * (a signal to upgrade the user's hash on next login). * ------------------------------------------------------------------------- */"},"lessons/55-accessibility.js":{"title":"* 55 · accessibility (a11y) — build for everyone, not just the mouse user","learn":"* • why semantic html is the foundation of accessibility (and free wins) * • how a control's accessible name is computed (label > aria-label > text) * • the cardinal rules of aria — and why \"no aria beats bad aria\" * • keyboard navigation & focus management (tabindex 0 / -1, never positive) * • color contrast — the wcag ratio, computed from scratch (aa = 4.5:1) * • live regions, reduced motion, accessible forms & modals * • a runnable \"a11y linter\" that flags the most common bugs * * a11y isn't a feature you bolt on — it's a baseline. ~1 in 6 people have a * disability; keyboard, screen-reader and low-vision users all hit your ui. * it's also a legal requirement (ada / en 301 549) and a frequent interview * topic. the dom/events lessons (24, 25) showed you how to change the page; * this one shows you how to do it so everyone can use it. * * the dom itself lives in the browser, so here we make the *principles* * runnable: helpers that compute accessible names, contrast ratios, and audit a * small virtual element tree — the exact logic real a11y tools use.","practice":"/* practice ------------------------------------------------------------------- * 1. extend accessiblename so an empty/whitespace-only text falls through to * the next source instead of being returned as a name. * 2. write largetextmeetsaa(fg, bg) using the 3:1 threshold (large text needs * less contrast than the 4.5:1 for body text). * 3. add a rule to audita11y that flags an <a> with no href (a link that isn't * a link — should be a <button>). * 4. write trapfocus(focusables, current, shiftkey) that returns the next * element to focus, wrapping at the ends (the core of a modal focus trap). * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 55 · accessibility (a11y) — build for everyone, not just the mouse user * ============================================================================= * run: node lessons/55-accessibility.js * * what you'll learn * • why semantic html is the foundation of accessibility (and free wins) * • how a control's accessible name is computed (label > aria-label > text) * • the cardinal rules of aria — and why \"no aria beats bad aria\" * • keyboard navigation & focus management (tabindex 0 / -1, never positive) * • color contrast — the wcag ratio, computed from scratch (aa = 4.5:1) * • live regions, reduced motion, accessible forms & modals * • a runnable \"a11y linter\" that flags the most common bugs * * a11y isn't a feature you bolt on — it's a baseline. ~1 in 6 people have a * disability; keyboard, screen-reader and low-vision users all hit your ui. * it's also a legal requirement (ada / en 301 549) and a frequent interview * topic. the dom/events lessons (24, 25) showed you how to change the page; * this one shows you how to do it so everyone can use it. * * the dom itself lives in the browser, so here we make the *principles* * runnable: helpers that compute accessible names, contrast ratios, and audit a * small virtual element tree — the exact logic real a11y tools use. * ========================================================================== */ 'use strict'; // ── 1. semantic html — the cheapest accessibility you'll ever get ──────────── // a real <button> is focusable, fires on enter and space, announces as \"button\" // to screen readers, and works with windows high contrast — all for free. a // <div onclick> gives you none of that, and you'd have to re-add it by hand. const semanticchoice = (intent) => ({ 'click action': '<button>', navigation: '<a href>', 'page section': '<section>/<nav>/<main>/<aside>', 'text input': '<input>/<textarea> with a <label>', 'list of items': '<ul>/<ol> + <li>', }[intent] || '<div> (last resort — re-implement semantics yourself)'); console.log(semanticchoice('click action')); // => <button> console.log(semanticchoice('navigation')); // => <a href> console.log(semanticchoice('mystery')); // => <div> (last resort — re-implement semantics yourself) // ── 2. the accessible name — what a screen reader actually announces ───────── // every interactive element needs an \"accessible name\". the browser computes it // in priority order. simplified, but this is the real precedence: // aria-labelledby > aria-label > associated <label> > text content > title function accessiblename(el) { if (el.arialabelledbytext) return el.arialabelledbytext; // text of referenced node(s) if (el.arialabel) return el.arialabel; if (el.labeltext) return el.labeltext; // <label for> or wrapping <label> if (el.text) return el.text; // visible text content if (el.title) return el.title; return ''; // ⚠️ no name → screen reader says just \"button\", useless } console.log(accessiblename({ text: 'save' })); // => save console.log(accessiblename({ arialabel: 'close dialog', text: '×' })); // => close dialog console.log(accessiblename({ title: 'only a title' })); // => only a title console.log(accessiblename({}) === ''); // => true (a nameless control — a bug) // ── 3. aria — the four rules, and \"no aria is better than bad aria\" ────────── // 1) prefer a native element with the semantics you need (rule 1 of aria). // 2) don't change native semantics (don't put role=\"button\" on a <button>). // 3) all interactive aria controls must be keyboard operable. // 4) don't use role=\"presentation\"/aria-hidden on a focusable element. // when you do build a custom widget, it needs role + state + keyboard handling. function togglebuttonattrs(pressed) { return { role: 'button', tabindex: 0, 'aria-pressed': string(pressed) }; } console.log(togglebuttonattrs(true)); // => { role: 'button', tabindex: 0, 'aria-pressed': 'true' } // a screen reader now announces \"<name>, toggle button, pressed\". flip // aria-pressed on every click — state in the dom, not just in a css class. // ── 4. keyboard navigation & focus management ──────────────────────────────── // everything you can do with a mouse must work with a keyboard (tab to move, // enter/space to activate, esc to dismiss). tabindex rules: // tabindex=\"0\" → in natural tab order (use for custom widgets) // tabindex=\"-1\" → focusable by script only (e.g. move focus to a dialog) // tabindex=\"2+\" → ❌ anti-pattern: hijacks order, impossible to maintain const validtabindex = (t) => t === 0 || t === -1; console.log(validtabindex(0)); // => true console.log(validtabindex(3)); // => false // focus management: when you open a modal, move focus into it; when it closes, // return focus to the element that opened it. never let focus fall to <body>. // ── 5. color contrast — the wcag ratio, from scratch ───────────────────────── // low contrast is the #1 automated-audit failure. wcag aa needs 4.5:1 for normal // text (3:1 for large text / ui). the ratio is (l1+0.05)/(l2+0.05) where l is // relative luminance. here's the real formula — runnable, no library: function relativeluminance(hex) { const n = parseint(hex.replace('#', ''), 16); const ch = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => { const s = v / 255; return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; }); return 0.2126 * ch[0] + 0.7152 * ch[1] + 0.0722 * ch[2]; } function contrastratio(fg, bg) { const a = relativeluminance(fg); const b = relativeluminance(bg); const ratio = (math.max(a, b) + 0.05) / (math.min(a, b) + 0.05); return math.round(ratio * 100) / 100; } const meetsaa = (fg, bg) => contrastratio(fg, bg) >= 4.5; // 4.5:1 = aa for normal text; large text / ui need only 3:1 console.log(contrastratio('#000000', '#ffffff')); // => 21 console.log(contrastratio('#ffffff', '#ffffff')); // => 1 console.log(meetsaa('#000000', '#ffffff')); // => true console.log(meetsaa('#aaaaaa', '#ffffff')); // => false (too light — fails aa) // ── 6. live regions, forms, modals & motion (the patterns) ─────────────────── // • live regions: aria-live=\"polite\" announces dynamic updates (a toast, a // \"3 results found\") without moving focus. use \"assertive\" only for errors. // • forms: every field needs a <label> (not just a placeholder — placeholders // vanish on input and are low-contrast). tie errors to the field with // aria-describedby and mark invalid fields aria-invalid=\"true\". // • modals: role=\"dialog\" aria-modal=\"true\", focus trapped inside, esc closes, // focus returns to the opener. (or just use the native <dialog> element.) // • motion: respect prefers-reduced-motion — gate animations behind it. function fieldattrs({ id, invalid }) { const a = { id, 'aria-invalid': string(!!invalid) }; if (invalid) a['aria-describedby'] = id + '-error'; // points at the error text return a; } console.log(fieldattrs({ id: 'email', invalid: true })); // => { id: 'email', 'aria-invalid': 'true', 'aria-describedby': 'email-error' } // ── 7. a tiny a11y linter — the bugs you'll actually ship ──────────────────── // audit a virtual element tree for the most common, highest-impact mistakes. function audita11y(nodes) { const issues = []; for (const n of nodes) { if (n.tag === 'img' && n.alt == null) issues.push(`<img> missing alt (src=${n.src})`); if (n.tag === 'button' && !accessiblename(n)) issues.push('<button> has no accessible name'); if (n.tag === 'input' && !n.labeltext && !n.arialabel) issues.push(`<input> \"${n.name}\" has no label`); if (typeof n.tabindex === 'number' && n.tabindex > 0) issues.push(`positive tabindex (${n.tabindex}) breaks tab order`); if (n.onclickdiv) issues.push('clickable <div> — use a <button> instead'); } return issues; } const page = [ { tag: 'img', src: 'logo.png', alt: 'acme logo' }, // ok { tag: 'img', src: 'hero.jpg' }, // ❌ no alt { tag: 'button', arialabel: 'menu' }, // ok { tag: 'button' }, // ❌ no name { tag: 'input', name: 'email', labeltext: 'email' }, // ok { tag: 'input', name: 'search' }, // ❌ no label { tag: 'a', text: 'home', tabindex: 5 }, // ❌ positive tabindex { tag: 'div', onclickdiv: true }, // ❌ clickable div ]; console.log(audita11y(page).length); // => 5 audita11y(page).foreach((i) => console.log('•', i)); // => • <img> missing alt (src=hero.jpg) // => • <button> has no accessible name // => • <input> \"search\" has no label // => • positive tabindex (5) breaks tab order // => • clickable <div> — use a <button> instead /* ----------------------------------------------------------------------------- * wcag in one breath — the pour principles * perceivable (alt text, captions, contrast) * operable (keyboard, no time traps, no seizure-inducing flashes) * understandable(clear labels, predictable behavior, helpful errors) * robust (valid semantic html that assistive tech can parse) * target wcag 2.2 level aa — the common legal baseline. * * interview corner * q: \"div with a click handler vs a button?\" * a: <button> is focusable, keyboard-operable (enter/space), and announced as * a button. a <div> needs tabindex=0, role=button, and key handlers to match * — so just use <button>. * q: \"is a placeholder a label?\" a: no. it disappears on input, is low * contrast, and isn't reliably announced. always use a real <label>. * q: \"how do you make a modal accessible?\" a: role=dialog aria-modal=true, * trap focus inside, esc to close, return focus to the opener (or <dialog>). * * common mistakes * • removing focus outlines (`outline: none`) with no visible replacement. * • aria-label on a non-interactive/!named element, or duplicating visible text. * • using color alone to convey meaning (add an icon/text too). * • positive tabindex; aria-hidden on a focusable element. * ---------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. extend accessiblename so an empty/whitespace-only text falls through to * the next source instead of being returned as a name. * 2. write largetextmeetsaa(fg, bg) using the 3:1 threshold (large text needs * less contrast than the 4.5:1 for body text). * 3. add a rule to audita11y that flags an <a> with no href (a link that isn't * a link — should be a <button>). * 4. write trapfocus(focusables, current, shiftkey) that returns the next * element to focus, wrapping at the ends (the core of a modal focus trap). * ------------------------------------------------------------------------- */"},"lessons/56-clean-code.js":{"title":"* 56 · clean code & professional javascript — write code humans can maintain","learn":"* • naming — the highest-leverage skill in programming * • function design: small, one job, few arguments, no surprises * • the single responsibility principle (and the rest of solid, briefly) * • dry — removing duplication without over-abstracting * • guard clauses: kill nesting and the \"arrow of doom\" * • cohesion (keep related things together) vs coupling (minimise the wires) * • the common code smells, each with a before → after refactor * • what technical debt is and how to manage it * * you can already make javascript work. this lesson is about the gap between * \"it works\" and \"a team can change it safely six months from now\" — the single * biggest difference between a junior and a professional. every refactor below * runs and proves the behavior is unchanged: clean code is a rewrite that keeps * the same outputs but is far easier to read.","practice":"/* practice ------------------------------------------------------------------- * 1. rename for intent: `function f(a, b) { return a * 0.01 * b; }` is a * percentage-of helper — rewrite it with names that need no comment. * 2. refactor with guard clauses: a function that nests `if (user) { if * (user.email) { if (user.verified) { return send(); } } }` — flatten it. * 3. turn a 4-positional-argument function `makebutton(label, primary, * disabled, large)` into one that takes an options object with defaults. * 4. spot the smell: `function save(u){ db.write(u); analytics.track(u); * sendemail(u); }` — name the principle it violates and split it. * ------------------------------------------------------------------------- */","body":"/* ============================================================================= * 56 · clean code & professional javascript — write code humans can maintain * ============================================================================= * run: node lessons/56-clean-code.js * * what you'll learn * • naming — the highest-leverage skill in programming * • function design: small, one job, few arguments, no surprises * • the single responsibility principle (and the rest of solid, briefly) * • dry — removing duplication without over-abstracting * • guard clauses: kill nesting and the \"arrow of doom\" * • cohesion (keep related things together) vs coupling (minimise the wires) * • the common code smells, each with a before → after refactor * • what technical debt is and how to manage it * * you can already make javascript work. this lesson is about the gap between * \"it works\" and \"a team can change it safely six months from now\" — the single * biggest difference between a junior and a professional. every refactor below * runs and proves the behavior is unchanged: clean code is a rewrite that keeps * the same outputs but is far easier to read. * ========================================================================== */ 'use strict'; // ── 1. naming — code is read ~10× more than it's written ───────────────────── // reveal intent. a good name removes the need for a comment. // ❌ const d = 86400000; const x = u.filter((e) => e.a); // ✅: const ms_per_day = 86_400_000; // a named constant, not a \"magic number\" const activeusers = (users) => users.filter((user) => user.isactive); console.log(activeusers([{ isactive: true }, { isactive: false }]).length); // => 1 // rules of thumb: searchable (no magic numbers), pronounceable, no encodings // (no `strname`), booleans read as yes/no (`isactive`, `hasaccess`), and // functions are verbs (`getuser`, `parsedate`), values are nouns. // ── 2. functions: small, one job, few arguments, no hidden side effects ────── // a function should do one thing at one level of abstraction. 0–2 args is ideal; // past 3, pass an options object (also makes calls self-documenting). // ❌ createuser('ada', 30, true, false, 'admin') ← what do the booleans mean? function createuser({ name, age, isadmin = false }) { return { name, age, role: isadmin ? 'admin' : 'member' }; } console.log(createuser({ name: 'ada', age: 30, isadmin: true })); // => { name: 'ada', age: 30, role: 'admin' } // command/query separation: a function either does something (command) or // answers something (query) — not both. and prefer pure functions (output // depends only on input, no side effects) — they're trivial to test and reuse. const add = (a, b) => a + b; // pure: same input → same output, touches nothing console.log(add(2, 3)); // => 5 // ── 3. single responsibility — one reason to change ────────────────────────── // ❌ one function that validates, saves, and emails is three reasons to change. // ✅ split it; each piece is testable and reusable on its own. const isvalidorder = (o) => o.items.length > 0 && o.total > 0; const ordersummary = (o) => `${o.items.length} item(s), $${o.total}`; function placeorder(order, { save, notify }) { if (!isvalidorder(order)) throw new error('invalid order'); save(order); // persistence: someone else's job notify(ordersummary(order)); // messaging: someone else's job return 'placed'; } const log = []; console.log(placeorder({ items: ['x'], total: 9 }, { save: () => log.push('saved'), notify: (m) => log.push(m) })); // => placed console.log(log); // => [ 'saved', '1 item(s), $9' ] // (that's the \"d\" in solid too — dependency inversion: placeorder depends on // injected `save`/`notify`, not on a concrete database or email library.) // ── 4. dry — don't repeat yourself (but don't over-abstract either) ────────── // ❌ three near-identical blocks computing a discounted price. // ✅ one function, called three times: const withdiscount = (price, pct) => price - price * (pct / 100); console.log([100, 200, 50].map((p) => withdiscount(p, 10))); // => [ 90, 180, 45 ] // caution: dry is about removing duplicated knowledge, not coincidentally // similar code. two things that merely look alike but change for different // reasons should stay separate — premature abstraction is its own smell. // ── 5. guard clauses — return early, kill the nesting ──────────────────────── // ❌ deeply nested \"arrow of doom\": // function pay(u){ if(u){ if(u.active){ if(u.balance>0){ ... } } } } // ✅ handle the exits first, then write the happy path flat: function charge(user, amount) { if (!user) return 'no user'; if (!user.active) return 'inactive'; if (user.balance < amount) return 'insufficient funds'; return `charged $${amount}`; // the happy path, un-nested } console.log(charge(null, 10)); // => no user console.log(charge({ active: false }, 10)); // => inactive console.log(charge({ active: true, balance: 100 }, 10)); // => charged $10 // ── 6. cohesion vs coupling ────────────────────────────────────────────────── // high cohesion: a module's parts belong together (a `money` module does money // things). low coupling: modules know as little about each other as possible — // talk through small, stable interfaces, not each other's internals. aim for // high cohesion + low coupling: you can change one part without breaking others. const money = { format: (cents) => `$${(cents / 100).tofixed(2)}`, add: (a, b) => a + b, }; console.log(money.format(1099)); // => $10.99 // ── 7. code smells — symptoms worth a second look ──────────────────────────── // • long function / god object → split by responsibility (§3) // • magic numbers/strings → name them (§1) // • boolean/flag parameters → split the function, or use an options object // • deep nesting → guard clauses (§5) // • duplicated logic → extract a function (§4) // • long parameter lists → pass an object // • comments explaining bad code → fix the code; keep comments for why, not what // • mutating shared state → prefer pure functions / return new values // refactor proof — same behavior, clearer code: const summessy = (a) => { let t = 0; for (let i = 0; i < a.length; i++) { t = t + a[i]; } return t; }; const sum = (nums) => nums.reduce((total, n) => total + n, 0); console.log(summessy([1, 2, 3]) === sum([1, 2, 3])); // => true // ── 8. technical debt — borrow deliberately, pay it back ───────────────────── // debt = a shortcut taken to ship now, repaid later with interest (slower future // changes, more bugs). some debt is smart (ship, learn, refactor). the danger is // untracked debt. make it visible and intentional: function tododebt(note, owner) { return `// todo(${owner}): ${note}`; // a searchable, owned marker — not silence } console.log(tododebt('replace o(n²) lookup with a map before launch', 'ada')); // => // todo(ada): replace o(n²) lookup with a map before launch // rules: leave the campsite cleaner than you found it; refactor in small safe // steps with tests (lesson 38) so behavior never changes by accident. /* ----------------------------------------------------------------------------- * interview corner * q: \"what makes code 'clean'?\" * a: it reveals intent: good names, small single-purpose functions, shallow * nesting, no duplication, and tests. you can read it top-to-bottom and * change one thing without fear. * q: \"when should you not dry something up?\" * a: when the two pieces only look alike but change for different reasons — * coupling them creates a worse problem than the duplication. * q: \"solid in one line each?\" * a: single-responsibility, open/closed, liskov substitution, interface * segregation, dependency inversion — all about isolating reasons to change. * * common mistakes * • clever one-liners over clear code. optimise for the next reader, not ego. * • comments that restate the code (`i++ // increment i`) instead of why. * • premature abstraction / over-engineering for imagined future needs (yagni). * • big-bang rewrites instead of small, test-backed refactors. * ---------------------------------------------------------------------------- */ /* practice ------------------------------------------------------------------- * 1. rename for intent: `function f(a, b) { return a * 0.01 * b; }` is a * percentage-of helper — rewrite it with names that need no comment. * 2. refactor with guard clauses: a function that nests `if (user) { if * (user.email) { if (user.verified) { return send(); } } }` — flatten it. * 3. turn a 4-positional-argument function `makebutton(label, primary, * disabled, large)` into one that takes an options object with defaults. * 4. spot the smell: `function save(u){ db.write(u); analytics.track(u); * sendemail(u); }` — name the principle it violates and split it. * ------------------------------------------------------------------------- */"}};
